"""## Visualización preliminar de mástiles, puntos Q, guardas y puntos N

Esta gráfica integra las superficies útiles de mástil solo con los puntos **Q**, los cables de guarda y los puntos auxiliares **N** generados en la presegmentación temprana. Permite revisar la coherencia geométrica inicial del modelo antes de continuar con la triangulación y los filtros posteriores.
"""

# @title
import numpy as np
import plotly.graph_objects as go
from math import atan2

# =========================================================
# SUPERFICIE 3D
# =========================================================

def _normalize_angle_local(theta):
    if "normalize_0_2pi" in globals():
        return normalize_0_2pi(theta)
    return theta % (2.0 * np.pi)


def rolling_sphere_z(u, a, R):
    """
    Perfil generatriz:
        z(u) = R - sqrt(R^2 - (u - a)^2)
    con 0 <= u <= a

    - En u = 0  -> z = altura del mástil
    - En u = a  -> z = 0
    """
    inside = R**2 - (u - a)**2
    inside = np.maximum(inside, 0.0)
    return R - np.sqrt(inside)


def build_partial_surface_for_interval(mast, sphere_radius, interval, nr=45, nt=80):
    """
    Construye una porción de superficie 3D solo en un intervalo angular útil.
    """
    a = effective_radius(mast.h, sphere_radius)

    if a <= 1e-12:
        return None

    theta1, theta2 = interval
    u = np.linspace(0.0, a, nr)
    theta = np.linspace(theta1, theta2, nt)

    U, TH = np.meshgrid(u, theta, indexing="xy")

    X = mast.x + U * np.cos(TH)
    Y = mast.y + U * np.sin(TH)
    Z = rolling_sphere_z(U, a, sphere_radius)

    return X, Y, Z


def add_mast_to_figure(fig, mast, idx, sphere_radius, results,
                       show_mast_line=True, show_base_circle=True):
    """
    Agrega al gráfico:
    - el segmento vertical del mástil
    - la circunferencia base en z=0
    - las superficies 3D solo en ángulos útiles
    """
    a = effective_radius(mast.h, sphere_radius)

    # Línea del mástil
    if show_mast_line:
        fig.add_trace(go.Scatter3d(
            x=[mast.x, mast.x],
            y=[mast.y, mast.y],
            z=[0.0, mast.h],
            mode="lines+markers+text",
            text=["", f"M{idx}"],
            textposition="top center",
            line=dict(width=8),
            marker=dict(size=4),
            name=f"Mástil {idx}",
            showlegend=False
        ))

    # Circunferencia base completa en z=0
    if show_base_circle and a > 1e-12:
        t = np.linspace(0.0, 2.0 * np.pi, 240)
        xb = mast.x + a * np.cos(t)
        yb = mast.y + a * np.sin(t)
        zb = np.zeros_like(t)

        fig.add_trace(go.Scatter3d(
            x=xb, y=yb, z=zb,
            mode="lines",
            line=dict(width=3, dash="dot"),
            name=f"Base M{idx}",
            showlegend=False
        ))

    # Superficies solo en los ángulos útiles
    useful_intervals = results[idx]["useful_intervals"]

    for k, interval in enumerate(useful_intervals):
        surface_data = build_partial_surface_for_interval(
            mast=mast,
            sphere_radius=sphere_radius,
            interval=interval,
            nr=45,
            nt=80
        )

        if surface_data is None:
            continue

        X, Y, Z = surface_data

        fig.add_trace(go.Surface(
            x=X,
            y=Y,
            z=Z,
            showscale=False,
            opacity=0.82,
            name=f"M{idx} útil {k+1}",
            hovertemplate=(
                f"Mástil {idx}<br>"
                "x=%{x:.2f}<br>"
                "y=%{y:.2f}<br>"
                "z=%{z:.2f}<extra></extra>"
            ),
            showlegend=False
        ))


def dibujar_aristas_Q(fig, masts, results, S, n_pts=200):
    """
    Dibuja, sobre el gráfico de superficies de mástil solo, las aristas
    correspondientes a los puntos Q útiles para cada mástil.
    """
    for i, data in results.items():
        mi = masts[i]
        ai = effective_radius(mi.h, S)

        if ai <= 1e-12:
            continue

        for pr in data["pair_results"]:
            for q in [pr.q_plus, pr.q_minus]:
                angle_q_i = _normalize_angle_local(atan2(q[1] - mi.y, q[0] - mi.x))

                is_useful = any(
                    low - 1e-9 <= angle_q_i <= high + 1e-9
                    for low, high in data["useful_intervals"]
                )

                if not is_useful:
                    continue

                r_vals = np.linspace(0.0, ai, n_pts)
                x1 = mi.x + r_vals * np.cos(angle_q_i)
                y1 = mi.y + r_vals * np.sin(angle_q_i)
                z1 = rolling_sphere_z(r_vals, ai, S)

                fig.add_trace(go.Scatter3d(
                    x=x1,
                    y=y1,
                    z=z1,
                    mode='lines',
                    line=dict(color='red', width=4),
                    showlegend=False
                ))


# =========================================================
# PUNTOS Q
# =========================================================

def collect_useful_Q_points(masts, results):
    """
    Recolecta puntos Q útiles y elimina duplicados.
    Cada punto Q se dibuja en z=0.
    """
    q_map = {}

    for i, data in results.items():
        mi = masts[i]

        for pr in data["pair_results"]:
            for q in [pr.q_plus, pr.q_minus]:
                angle_q_i = _normalize_angle_local(atan2(q[1] - mi.y, q[0] - mi.x))

                is_useful = any(
                    low - 1e-9 <= angle_q_i <= high + 1e-9
                    for low, high in data["useful_intervals"]
                )

                if not is_useful:
                    continue

                key = (round(float(q[0]), 8), round(float(q[1]), 8))

                if key not in q_map:
                    q_map[key] = {
                        "x": float(q[0]),
                        "y": float(q[1]),
                        "z": 0.0,
                        "masts": set()
                    }

                q_map[key]["masts"].add(i)

    q_points = []
    for k, (_, data) in enumerate(q_map.items()):
        q_points.append({
            "label": f"Q{k}",
            "x": data["x"],
            "y": data["y"],
            "z": data["z"],
            "masts": sorted(list(data["masts"]))
        })

    return q_points


def add_Q_points_to_figure(fig, q_points):
    """
    Agrega los puntos Q al gráfico.
    """
    if not q_points:
        return

    xs = [p["x"] for p in q_points]
    ys = [p["y"] for p in q_points]
    zs = [p["z"] for p in q_points]
    texts = [p["label"] for p in q_points]
    hovertexts = [
        f"{p['label']}<br>x={p['x']:.3f}<br>y={p['y']:.3f}<br>z={p['z']:.3f}<br>Útil para mástiles: {p['masts']}"
        for p in q_points
    ]

    fig.add_trace(go.Scatter3d(
        x=xs,
        y=ys,
        z=zs,
        mode="markers+text",
        text=texts,
        textposition="top center",
        marker=dict(size=5, color="red", symbol="circle"),
        name="Puntos Q",
        hovertext=hovertexts,
        hoverinfo="text"
    ))


# =========================================================
# GUARDAS
# =========================================================

def add_guard_wires_to_figure(fig, masts, guard_wire_inputs=None, guard_wire_fragments_pre=None):
    """
    Dibuja guardas:
    - si existen fragmentos presegmentados, dibuja esos fragmentos;
    - si no, dibuja las guardas originales.
    """
    if guard_wire_fragments_pre is not None and len(guard_wire_fragments_pre) > 0:
        for k, frag in enumerate(guard_wire_fragments_pre):
            p1 = frag["p1"]
            p2 = frag["p2"]

            fig.add_trace(go.Scatter3d(
                x=[p1[0], p2[0]],
                y=[p1[1], p2[1]],
                z=[p1[2], p2[2]],
                mode="lines",
                line=dict(color="green", width=7),
                name="Guardas segmentadas",
                showlegend=(k == 0),
                hovertemplate=(
                    f"Fragmento guarda<br>"
                    f"{frag['label1']} - {frag['label2']}<br>"
                    f"Guarda base: {frag['host_guard']}<extra></extra>"
                )
            ))
        return

    if guard_wire_inputs is None:
        return

    for k, gw in enumerate(guard_wire_inputs):
        i = int(gw["i"])
        j = int(gw["j"])

        mi = masts[i]
        mj = masts[j]

        fig.add_trace(go.Scatter3d(
            x=[mi.x, mj.x],
            y=[mi.y, mj.y],
            z=[mi.h, mj.h],
            mode="lines",
            line=dict(color="green", width=7),
            name="Guardas",
            showlegend=(k == 0),
            hovertemplate=f"Guarda M{i} - M{j}<extra></extra>"
        ))


# =========================================================
# PUNTOS N
# =========================================================

def add_N_points_to_figure(fig, early_N_nodes=None):
    """
    Agrega puntos N al gráfico.
    """
    if early_N_nodes is None or len(early_N_nodes) == 0:
        return

    xs = [float(n["x"]) for n in early_N_nodes]
    ys = [float(n["y"]) for n in early_N_nodes]
    zs = [float(n["z"]) for n in early_N_nodes]
    texts = [n["label"] for n in early_N_nodes]

    hovertexts = []
    for n in early_N_nodes:
        hovertexts.append(
            f"{n['label']}<br>"
            f"x={float(n['x']):.3f}<br>"
            f"y={float(n['y']):.3f}<br>"
            f"z={float(n['z']):.3f}<br>"
            f"host_guard={n.get('host_guard', '')}"
        )

    fig.add_trace(go.Scatter3d(
        x=xs,
        y=ys,
        z=zs,
        mode="markers+text",
        text=texts,
        textposition="top center",
        marker=dict(size=6, color="orange", symbol="diamond"),
        name="Puntos N",
        hovertext=hovertexts,
        hoverinfo="text"
    ))


# =========================================================
# GRÁFICA PRINCIPAL
# =========================================================

def plot_interactive_3d_rolling_surfaces(
    masts,
    sphere_radius,
    results,
    guard_wire_inputs=None,
    early_N_nodes=None,
    guard_wire_fragments_pre=None
):
    fig = go.Figure()

    for i, mast in enumerate(masts):
        add_mast_to_figure(
            fig=fig,
            mast=mast,
            idx=i,
            sphere_radius=sphere_radius,
            results=results,
            show_mast_line=True,
            show_base_circle=True
        )

    # =====================================================
    # Aristas Q sobre las superficies de mástil solo
    # =====================================================
    dibujar_aristas_Q(fig, masts, results, sphere_radius, n_pts=200)

    # =====================================================
    # Puntos Q
    # =====================================================
    q_points = collect_useful_Q_points(masts, results)
    add_Q_points_to_figure(fig, q_points)

    # =====================================================
    # Guardas
    # =====================================================
    add_guard_wires_to_figure(
        fig,
        masts,
        guard_wire_inputs=guard_wire_inputs,
        guard_wire_fragments_pre=guard_wire_fragments_pre
    )

    # =====================================================
    # Puntos N
    # =====================================================
    add_N_points_to_figure(fig, early_N_nodes=early_N_nodes)

    # Plano z = 0
    all_x = [m.x for m in masts]
    all_y = [m.y for m in masts]
    max_a = max(effective_radius(m.h, sphere_radius) for m in masts)

    xmin = min(all_x) - max_a - 5
    xmax = max(all_x) + max_a + 5
    ymin = min(all_y) - max_a - 5
    ymax = max(all_y) + max_a + 5

    Xg, Yg = np.meshgrid(
        np.linspace(xmin, xmax, 2),
        np.linspace(ymin, ymax, 2)
    )
    Zg = np.zeros_like(Xg)

    fig.add_trace(go.Surface(
        x=Xg, y=Yg, z=Zg,
        showscale=False,
        opacity=0.20,
        name="Plano z=0",
        hoverinfo="skip",
        showlegend=False
    ))

    fig.update_layout(
        title=f"Superficies 3D de esfera rodante (ángulos útiles) + Q + guardas + N - R = {sphere_radius}",
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=750
    )

    fig.show()


# =========================================================
# FUNCIÓN PRINCIPAL
# =========================================================

def run_model(
    mast_inputs,
    sphere_radius,
    guard_wire_inputs=None,
    early_N_nodes=None,
    guard_wire_fragments_pre=None
):
    """
    Usa directamente la única sección de entradas definida al inicio.
    """
    masts = [Mast(x, y, h) for x, y, h in mast_inputs]
    results = useful_angle_ranges_for_each_mast(masts, sphere_radius)

    print_useful_intervals(results, in_degrees=True)

    plot_interactive_3d_rolling_surfaces(
        masts=masts,
        sphere_radius=sphere_radius,
        results=results,
        guard_wire_inputs=guard_wire_inputs,
        early_N_nodes=early_N_nodes,
        guard_wire_fragments_pre=guard_wire_fragments_pre
    )

    return masts, results


# =========================================================
# EJECUCIÓN
# =========================================================

guard_wire_inputs_plot = guard_wire_inputs if "guard_wire_inputs" in globals() else None
early_N_nodes_plot = early_N_nodes if "early_N_nodes" in globals() else None
guard_wire_fragments_pre_plot = guard_wire_fragments_pre if "guard_wire_fragments_pre" in globals() else None

masts_3d, results_3d = run_model(
    mast_inputs=mast_inputs,
    sphere_radius=S,
    guard_wire_inputs=guard_wire_inputs_plot,
    early_N_nodes=early_N_nodes_plot,
    guard_wire_fragments_pre=guard_wire_fragments_pre_plot
)

"""# FASE 2: Triangulación de todas las TETRAS

## Filtro 1: Generación y filtrado inicial de triángulos candidatos M/N/Q

Esta celda construye todos los triángulos candidatos posibles a partir de los nodos disponibles del modelo: puntas de mástiles **M**, puntos auxiliares **N** sobre guardas y puntos **Q** asociados a los ángulos útiles. Antes de conservar los candidatos, se eliminan las ternas degeneradas o colineales en planta **XY**, evitando superficies sin área geométrica válida.

Después de esta depuración, los triángulos se clasifican según el tipo de nodos que los conforman y solo se conservan las configuraciones requeridas para las fases posteriores del modelo: **MMM**, **MMQ** y **NNM**. Los demás tipos de combinación, como **MQQ**, **MNQ**, **MMN**, **NNQ**, **NNN** o **QQQ**, se descartan en esta etapa.
"""

# @title
# =========================================================
# FILTRO 1 — GENERACIÓN DE TRIÁNGULOS CANDIDATOS
# PUNTAS DE MÁSTILES + PUNTOS N + PUNTOS Q ÚTILES
# =========================================================
#
# Objetivo:
#   Construir todas las ternas posibles a partir de los nodos M, N y Q,
#   pero conservar únicamente los triángulos de tipo:
#
#       - MMM : tres puntas de mástil
#       - MMQ : dos puntas de mástil y un punto Q
#       - NNM : dos puntos N y una punta de mástil
#       - MMN : dos puntas de mástil y un punto N
#
# Criterio:
#   Se forman combinaciones de tres nodos y se descartan aquellas que:
#     - sean degeneradas o colineales en planta XY;
#     - no pertenezcan a los tipos permitidos: MMM, MMQ, NNM o MMN.
#
# Corrección importante de visualización:
#   - Antes, las aristas reales de los triángulos se dibujaban con
#     showlegend=False y luego se agregaba una leyenda manual con trazas vacías.
#   - Por eso, al apagar "MMQ" o "NNM" en la leyenda, las líneas reales
#     seguían visibles.
#   - Ahora las aristas reales se agrupan por tipo en trazas únicas:
#       Triángulos MMM
#       Triángulos MMQ
#       Triángulos NNM
#       Triángulos MMN
#     De esta forma, la leyenda interactiva sí controla las líneas reales.
#
# Importante:
#   - Los M-M-N se generan solo como candidatos iniciales.
#   - Más adelante, entre Filtro 4 y el antiguo Filtro 5, se debe agregar
#     el nuevo filtro estructural para conservar únicamente los M-M-N cuya
#     arista M-M coincida con una arista M-M de un M-M-Q activo después
#     del Filtro 4.
#
# Entrada:
#   - all_points
#   - early_N_nodes, si existe
#
# Salida:
#   - tri_nodes
#   - candidate_triangles
#   - candidate_triangle_type_counts
#   - discarded_triangle_type_counts
#   - candidate_triangles_by_type
# =========================================================

import itertools
import numpy as np
import plotly.graph_objects as go


# =========================================================
# CONSTRUCCIÓN DE NODOS
# =========================================================

def build_candidate_nodes(all_points, early_N_nodes=None):
    """
    Construye los nodos candidatos:
      - M : puntas de mástiles reales, z = h
      - N : puntos auxiliares sobre guardas, z interpolado sobre la guarda
      - Q : puntos útiles proyectados en suelo, z = 0
    """
    real_masts = [p for p in all_points if p.h > 1e-12]
    q_points   = [p for p in all_points if abs(p.h) < 1e-12]

    tri_nodes = []

    # ---------------------------------
    # 1) Nodos M
    # ---------------------------------
    for i, m in enumerate(real_masts):
        tri_nodes.append({
            "type": "M",
            "label": f"M{i}",
            "x": float(m.x),
            "y": float(m.y),
            "z": float(m.h),
            "obj": m
        })

    # ---------------------------------
    # 2) Nodos N tempranos
    # ---------------------------------
    if early_N_nodes is not None:
        for n in early_N_nodes:
            # Se copia toda la información original del punto N.
            # Esto ayuda a conservar metadatos como host_guard,
            # lambda_on_guard, associated_mast, associated_masts, etc.
            n_node = dict(n)

            n_node.update({
                "type": "N",
                "label": str(n["label"]),
                "x": float(n["x"]),
                "y": float(n["y"]),
                "z": float(n["z"]),
                "obj": n,
                "host_guard": n.get("host_guard", None),
                "lambda_on_guard": n.get("lambda_on_guard", None),
                "associated_mast": n.get("associated_mast", None),
                "associated_masts": n.get("associated_masts", None),
            })

            tri_nodes.append(n_node)

    # ---------------------------------
    # 3) Nodos Q
    # ---------------------------------
    for k, q in enumerate(q_points):
        tri_nodes.append({
            "type": "Q",
            "label": f"Q{k}",
            "x": float(q.x),
            "y": float(q.y),
            "z": 0.0,
            "obj": q
        })

    return tri_nodes


# =========================================================
# UTILIDADES GEOMÉTRICAS
# =========================================================

def area_xy_of_triangle(n1, n2, n3):
    """
    Área en planta XY del triángulo.
    Sirve para detectar ternas degeneradas/colineales en XY.
    """
    x1, y1 = n1["x"], n1["y"]
    x2, y2 = n2["x"], n2["y"]
    x3, y3 = n3["x"], n3["y"]

    return 0.5 * abs(
        (x2 - x1) * (y3 - y1) -
        (x3 - x1) * (y2 - y1)
    )


def triangle_type_signature(n1, n2, n3):
    """
    Devuelve la firma ordenada del triángulo según los tipos de nodos.

    Ejemplos:
      M, M, M -> MMM
      M, M, Q -> MMQ
      N, N, M -> MNN
      M, M, N -> MMN
    """
    types = sorted([n1["type"], n2["type"], n3["type"]])
    return "".join(types)


def triangle_type_name(signature):
    """
    Convierte la firma ordenada a un nombre corto.
    """
    if signature == "MMM":
        return "MMM"

    if signature == "MMQ":
        return "MMQ"

    if signature == "MNN":
        return "NNM"

    if signature == "MMN":
        return "MMN"

    return signature


def triangle_type_long_name(signature):
    """
    Convierte la firma ordenada a un nombre largo compatible
    con los filtros posteriores.
    """
    if signature == "MMM":
        return "M-M-M"

    if signature == "MMQ":
        return "M-M-Q"

    if signature == "MNN":
        return "N-N-M"

    if signature == "MMN":
        return "M-M-N"

    return signature


def is_allowed_triangle_type(n1, n2, n3):
    """
    Tipos permitidos:
      - MMM
      - MMQ
      - NNM, representado internamente como MNN por orden alfabético
      - MMN
    """
    signature = triangle_type_signature(n1, n2, n3)

    allowed_signatures = {
        "MMM",
        "MMQ",
        "MNN",   # equivalente a NNM
        "MMN",   # equivalente a MMN
    }

    return signature in allowed_signatures


def get_triangle_mnq_nodes(tri_data):
    """
    Devuelve listas separadas de nodos M, N y Q para un triángulo.
    Es útil para diagnósticos posteriores.
    """
    nodes = tri_data["nodes"]

    m_nodes = [n for n in nodes if n["type"] == "M"]
    n_nodes = [n for n in nodes if n["type"] == "N"]
    q_nodes = [n for n in nodes if n["type"] == "Q"]

    return m_nodes, n_nodes, q_nodes


# =========================================================
# GENERACIÓN DE TRIÁNGULOS
# =========================================================

def generate_all_candidate_triangles_MNQ(tri_nodes, area_tol=1e-9):
    """
    Genera todas las combinaciones de 3 nodos M/N/Q y conserva solo:
      - MMM
      - MMQ
      - NNM
      - MMN

    Descarta:
      - degenerados en XY
      - tipos no permitidos
    """
    candidate_triangles = []

    degenerate_count = 0
    discarded_triangle_type_counts = {}
    candidate_triangle_type_counts = {}

    for idxs in itertools.combinations(range(len(tri_nodes)), 3):
        i, j, k = idxs
        n1, n2, n3 = tri_nodes[i], tri_nodes[j], tri_nodes[k]

        # ---------------------------------
        # 1) Descartar degenerados en XY
        # ---------------------------------
        area_xy = area_xy_of_triangle(n1, n2, n3)

        if area_xy <= area_tol:
            degenerate_count += 1
            continue

        # ---------------------------------
        # 2) Clasificar por tipo M/N/Q
        # ---------------------------------
        signature = triangle_type_signature(n1, n2, n3)
        type_name = triangle_type_name(signature)
        triangle_type_long = triangle_type_long_name(signature)

        # ---------------------------------
        # 3) Conservar solo MMM, MMQ, NNM y MMN
        # ---------------------------------
        if not is_allowed_triangle_type(n1, n2, n3):
            discarded_triangle_type_counts[type_name] = (
                discarded_triangle_type_counts.get(type_name, 0) + 1
            )
            continue

        candidate_triangle_type_counts[type_name] = (
            candidate_triangle_type_counts.get(type_name, 0) + 1
        )

        candidate_triangles.append({
            "indices": (i, j, k),
            "labels": (n1["label"], n2["label"], n3["label"]),
            "nodes": (n1, n2, n3),
            "area_xy": area_xy,

            # Nombre corto para gráficas y conteos
            "type": type_name,

            # Firma interna
            "type_signature": signature,

            # Nombre largo compatible con filtros posteriores
            "triangle_type": triangle_type_long
        })

    return (
        candidate_triangles,
        degenerate_count,
        candidate_triangle_type_counts,
        discarded_triangle_type_counts
    )


def group_candidate_triangles_by_type(candidate_triangles):
    """
    Agrupa los triángulos candidatos por tipo corto:
      MMM, MMQ, NNM, MMN.
    """
    grouped = {}

    for tri in candidate_triangles:
        tri_type = tri.get("type", None)

        if tri_type is None:
            continue

        grouped.setdefault(tri_type, []).append(tri)

    return grouped


# =========================================================
# VISUALIZACIÓN
# =========================================================

def color_by_triangle_type(tri_type):
    """
    Colores por tipo de triángulo.
    """
    if tri_type == "MMM":
        return "gray"

    if tri_type == "MMQ":
        return "red"

    if tri_type == "NNM":
        return "green"

    if tri_type == "MMN":
        return "purple"

    return "black"


def add_triangle_edges_grouped_by_type(fig, candidate_triangles):
    """
    Dibuja las aristas reales de los triángulos agrupadas por tipo.

    Ventaja:
      - La leyenda interactiva ahora sí apaga/enciende las líneas reales.
      - No se usa una leyenda manual con trazas vacías.
    """

    type_order = ["MMM", "MMQ", "NNM", "MMN"]

    grouped_edges = {
        tri_type: {
            "x": [],
            "y": [],
            "z": [],
            "text": []
        }
        for tri_type in type_order
    }

    for tri_data in candidate_triangles:
        tri_type = tri_data["type"]

        if tri_type not in grouped_edges:
            continue

        n1, n2, n3 = tri_data["nodes"]
        labels = tri_data["labels"]

        edges = [
            (n1, n2, labels[0], labels[1]),
            (n2, n3, labels[1], labels[2]),
            (n3, n1, labels[2], labels[0]),
        ]

        tri_label = "-".join(labels)

        for a, b, la, lb in edges:
            grouped_edges[tri_type]["x"].extend([a["x"], b["x"], None])
            grouped_edges[tri_type]["y"].extend([a["y"], b["y"], None])
            grouped_edges[tri_type]["z"].extend([a["z"], b["z"], None])

            hover_txt = (
                f"Tipo: {tri_type}<br>"
                f"Triángulo: {tri_label}<br>"
                f"Arista: {la} - {lb}"
            )

            grouped_edges[tri_type]["text"].extend([hover_txt, hover_txt, None])

    for tri_type in type_order:
        data = grouped_edges[tri_type]

        if len(data["x"]) == 0:
            continue

        width = 3 if tri_type == "MMN" else 3

        fig.add_trace(go.Scatter3d(
            x=data["x"],
            y=data["y"],
            z=data["z"],
            mode="lines",
            line=dict(
                color=color_by_triangle_type(tri_type),
                width=width
            ),
            name=f"Triángulos {tri_type}",
            hoverinfo="text",
            text=data["text"],
            showlegend=True
        ))


def add_nodes_to_figure(fig, tri_nodes):
    """
    Dibuja puntos M, N y Q.
    """

    # ---------------------------------
    # 1) Dibujar puntos Q
    # ---------------------------------
    q_nodes = [n for n in tri_nodes if n["type"] == "Q"]

    if q_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in q_nodes],
            y=[n["y"] for n in q_nodes],
            z=[n["z"] for n in q_nodes],
            mode="markers+text",
            marker=dict(size=6, color="orange"),
            text=[n["label"] for n in q_nodes],
            textposition="top center",
            name="Puntos Q",
            showlegend=True
        ))

    # ---------------------------------
    # 2) Dibujar puntos N
    # ---------------------------------
    n_nodes = [n for n in tri_nodes if n["type"] == "N"]

    if n_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in n_nodes],
            y=[n["y"] for n in n_nodes],
            z=[n["z"] for n in n_nodes],
            mode="markers+text",
            marker=dict(size=7, color="green", symbol="diamond"),
            text=[n["label"] for n in n_nodes],
            textposition="top center",
            name="Puntos N",
            showlegend=True
        ))

    # ---------------------------------
    # 3) Dibujar mástiles
    # ---------------------------------
    mast_nodes = [n for n in tri_nodes if n["type"] == "M"]

    first_mast_line = True
    first_mast_tip = True

    for n in mast_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"], n["x"]],
            y=[n["y"], n["y"]],
            z=[0.0, n["z"]],
            mode="lines",
            line=dict(color="blue", width=8),
            name="Mástiles",
            showlegend=first_mast_line,
            hoverinfo="text",
            text=[
                f"Mástil {n['label']}",
                f"Mástil {n['label']}"
            ]
        ))

        first_mast_line = False

        fig.add_trace(go.Scatter3d(
            x=[n["x"]],
            y=[n["y"]],
            z=[n["z"]],
            mode="markers+text",
            marker=dict(size=5, color="black"),
            text=[n["label"]],
            textposition="top center",
            name="Puntas de mástil",
            showlegend=first_mast_tip,
            hoverinfo="text",
            hovertext=f"{n['label']}<br>x={n['x']:.3f}<br>y={n['y']:.3f}<br>z={n['z']:.3f}"
        ))

        first_mast_tip = False


def add_ground_plane_to_figure(fig, tri_nodes):
    """
    Dibuja un plano de suelo transparente.
    """
    if tri_nodes:
        xy = np.array([[n["x"], n["y"]] for n in tri_nodes], dtype=float)
        xmin, ymin = np.min(xy, axis=0) - 5
        xmax, ymax = np.max(xy, axis=0) + 5
    else:
        xmin, ymin, xmax, ymax = -5, -5, 5, 5

    Xg, Yg = np.meshgrid(
        np.linspace(xmin, xmax, 2),
        np.linspace(ymin, ymax, 2)
    )
    Zg = np.zeros_like(Xg)

    fig.add_trace(go.Surface(
        x=Xg,
        y=Yg,
        z=Zg,
        showscale=False,
        opacity=0.10,
        hoverinfo="skip",
        name="Suelo",
        showlegend=False
    ))


def plot_all_candidate_triangles_MNQ(all_points, early_N_nodes=None):
    """
    Dibuja:
      - mástiles M
      - puntos N
      - puntos Q
      - triángulos candidatos conservados: MMM, MMQ, NNM y MMN
      - plano de suelo

    Además:
      - La leyenda interactiva controla realmente las líneas de cada tipo.
      - Se imprime diagnóstico específico de MMN.
    """
    tri_nodes = build_candidate_nodes(
        all_points=all_points,
        early_N_nodes=early_N_nodes
    )

    (
        candidate_triangles,
        degenerate_count,
        candidate_triangle_type_counts,
        discarded_triangle_type_counts
    ) = generate_all_candidate_triangles_MNQ(tri_nodes)

    candidate_triangles_by_type = group_candidate_triangles_by_type(
        candidate_triangles
    )

    # =====================================================
    # DIAGNÓSTICO EN CONSOLA
    # =====================================================
    n_M = sum(1 for n in tri_nodes if n["type"] == "M")
    n_N = sum(1 for n in tri_nodes if n["type"] == "N")
    n_Q = sum(1 for n in tri_nodes if n["type"] == "Q")

    print("====================================================")
    print("FILTRO 1 — GENERACIÓN DE TRIÁNGULOS CANDIDATOS M/N/Q")
    print("====================================================")
    print(f"Número total de nodos M/N/Q              : {len(tri_nodes)}")
    print(f"Número de nodos M                        : {n_M}")
    print(f"Número de nodos N                        : {n_N}")
    print(f"Número de nodos Q                        : {n_Q}")
    print(f"Número de ternas degeneradas en XY       : {degenerate_count}")
    print(f"Número de triángulos candidatos útiles   : {len(candidate_triangles)}")

    print("\nTriángulos conservados por tipo:")
    if candidate_triangle_type_counts:
        for key in ["MMM", "MMQ", "NNM", "MMN"]:
            print(f"  - {key}: {candidate_triangle_type_counts.get(key, 0)}")
    else:
        print("  No se conservaron triángulos.")

    print("\nTriángulos descartados por tipo:")
    if discarded_triangle_type_counts:
        for key in sorted(discarded_triangle_type_counts.keys()):
            print(f"  - {key}: {discarded_triangle_type_counts[key]}")
    else:
        print("  No se descartaron triángulos por tipo.")

    # Diagnóstico específico de MMN
    mmn_triangles = candidate_triangles_by_type.get("MMN", [])

    print("\nDiagnóstico específico de M-M-N:")
    print(f"  - M-M-N conservados: {len(mmn_triangles)}")

    if len(mmn_triangles) > 0:
        print("  - Primeros M-M-N conservados:")
        for tri in mmn_triangles[:20]:
            print(
                f"      {tri['labels']} | "
                f"area_xy = {tri['area_xy']:.6e}"
            )
    else:
        print("  - No quedaron M-M-N conservados.")
        print("    Posibles causas:")
        print("      1) Los M-M-N esperados son degenerados en XY.")
        print("      2) Los puntos N están alineados con la arista M-M.")
        print("      3) No existen combinaciones M-M-N válidas con área en planta.")

    # =====================================================
    # GRÁFICA
    # =====================================================
    fig = go.Figure()

    # ---------------------------------
    # 1) Dibujar aristas reales agrupadas por tipo
    # ---------------------------------
    add_triangle_edges_grouped_by_type(
        fig=fig,
        candidate_triangles=candidate_triangles
    )

    # ---------------------------------
    # 2) Dibujar nodos M, N y Q
    # ---------------------------------
    add_nodes_to_figure(
        fig=fig,
        tri_nodes=tri_nodes
    )

    # ---------------------------------
    # 3) Plano de suelo
    # ---------------------------------
    add_ground_plane_to_figure(
        fig=fig,
        tri_nodes=tri_nodes
    )

    # ---------------------------------
    # 4) Layout
    # ---------------------------------
    fig.update_layout(
        title=(
            "Filtro 1 — Triángulos candidatos conservados: "
            "MMM, MMQ, NNM y MMN"
        ),
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=850,
        legend=dict(
            title="Elementos",
            itemclick="toggle",
            itemdoubleclick="toggleothers"
        )
    )

    fig.show()

    return (
        tri_nodes,
        candidate_triangles,
        candidate_triangle_type_counts,
        discarded_triangle_type_counts,
        candidate_triangles_by_type
    )


# =========================================================
# EJECUCIÓN
# =========================================================

early_N_nodes_for_candidates = (
    early_N_nodes
    if "early_N_nodes" in globals()
    else None
)

(
    tri_nodes,
    candidate_triangles,
    candidate_triangle_type_counts,
    discarded_triangle_type_counts,
    candidate_triangles_by_type
) = plot_all_candidate_triangles_MNQ(
    all_points=all_points,
    early_N_nodes=early_N_nodes_for_candidates
)


# =========================================================
# VARIABLES FINALES DE REFERENCIA DEL FILTRO 1
# =========================================================
# Estas variables quedan disponibles para los filtros posteriores.
# Por ahora, los triángulos candidatos incluyen:
#   - M-M-M
#   - M-M-Q
#   - N-N-M
#   - M-M-N
#
# Los M-M-N todavía NO han sido validados estructuralmente.
# Esa validación debe ocurrir después del Filtro 4.

filtered_triangles_after_filter_1 = candidate_triangles
filtered_tri_nodes_after_filter_1 = tri_nodes

"""## Filtro 2: Validación estructural de M-M-Q y conservación de MMM/NNM/MMN

Este segmento aplica un filtro estructural sobre los triángulos candidatos generados previamente con nodos **M**, **N** y **Q**. En esta etapa ya solo llegan triángulos de tipo **MMM**, **MMQ**, **MMN** y **NNM**, debido a que las combinaciones no permitidas fueron descartadas en la generación inicial.

El filtro conserva directamente los triángulos **MMM**, **MMN** y **NNM**, ya que no dependen de la validación angular de puntos Q. En cambio, los triángulos **M-M-Q** son evaluados de forma estructural: para cada uno se calcula la dirección angular desde cada mástil hacia el punto Q y se compara con los bordes de los intervalos útiles previamente calculados. Si el punto Q coincide con un borde útil vigente desde ambos mástiles del triángulo, el **M-M-Q** se conserva; de lo contrario, se elimina.

Después del filtro se actualiza la lista de nodos activos, conservando todos los mástiles y eliminando visualmente los puntos **Q** y **N** huérfanos, es decir, aquellos que ya no pertenecen a ningún triángulo conservado. Finalmente, el código imprime un resumen de los triángulos eliminados y conservados por tipo, y genera una gráfica 3D con los triángulos restantes, los mástiles, los puntos Q activos, los puntos N activos, las guardas como referencia y las zonas de mástil solo.
"""

# @title
# =========================================================
# FILTRO 2 — VALIDACIÓN ESTRUCTURAL DE M-M-Q
# CON CONSERVACIÓN DIRECTA DE MMM, NNM Y MMN
# =========================================================
#
# Objetivo:
#   Aplicar una validación estructural únicamente sobre los triángulos M-M-Q,
#   conservando directamente los triángulos:
#
#       - M-M-M
#       - N-N-M
#       - M-M-N
#
# Contexto:
#   El Filtro 1 ya generó los triángulos candidatos usando nodos:
#
#       - M : puntas de mástiles
#       - N : puntos auxiliares sobre guardas
#       - Q : puntos asociados a bordes útiles
#
#   En esa etapa se conservaron solamente:
#
#       - MMM
#       - MMQ
#       - NNM
#       - MMN
#
# Criterio:
#   - MMM se conserva directamente.
#   - NNM se conserva directamente.
#   - MMN se conserva directamente por ahora.
#   - MMQ se conserva solo si el punto Q coincide con un borde útil
#     vigente desde ambos mástiles del triángulo.
#
# Importante:
#   - Este filtro NO valida estructuralmente los M-M-N.
#   - Los M-M-N deben pasar por una validación posterior entre el Filtro 4
#     y el antiguo Filtro 5.
#   - Esa validación posterior conservará únicamente los M-M-N cuya arista
#     M-M coincida con una arista M-M de un M-M-Q activo después del Filtro 4.
#
# Corrección importante de visualización:
#   - Ya no se usa una leyenda manual con trazas vacías.
#   - Ahora las aristas reales se agrupan por tipo:
#       Triángulos MMM
#       Triángulos MMQ
#       Triángulos NNM
#       Triángulos MMN
#   - Al apagar un tipo en la leyenda, se apagan sus líneas reales.
#
# Convención de colores:
#   - MMM : gris
#   - MMQ : rojo
#   - NNM : verde
#   - MMN : morado
#   - puntos Q activos : naranja
#   - puntos N activos : cian
#   - guardas : verde oscuro
#
# Entrada:
#   - candidate_triangles
#   - tri_nodes
#   - results
#   - masts
#   - S
#
# Salida:
#   - kept_triangles_2
#   - removed_triangles_2
#   - tri_nodes_after_mmq_filter
#   - tri_nodes_after_filter_2
#   - kept_triangles_after_filter_2
#   - filtered_triangles_after_filter_2
#   - filtered_tri_nodes_after_filter_2
#   - input_type_counts_2
#   - kept_type_counts_2
#   - removed_type_counts_2
# =========================================================

import numpy as np
import plotly.graph_objects as go


# =========================================================
# UTILIDADES DE TIPO DE NODO / TRIÁNGULO
# =========================================================

def node_family_2(node):
    """
    Normaliza los tipos de nodo usados en el flujo.

    Compatibilidad:
      - "M" o "mast_top" -> M
      - "N"              -> N
      - "Q"              -> Q
    """
    raw_type = str(node.get("type", "")).strip()
    label = str(node.get("label", "")).strip()

    if raw_type in ["M", "mast_top"]:
        return "M"

    if raw_type == "N" or raw_type.startswith("auxiliary_N"):
        return "N"

    if raw_type == "Q":
        return "Q"

    if label.startswith("M"):
        return "M"

    if label.startswith("N"):
        return "N"

    if label.startswith("Q"):
        return "Q"

    return raw_type


def triangle_family_code_2(tri):
    """
    Clasifica un triángulo según la cantidad de nodos M/N/Q.

    Retorna:
      - MMM
      - MMQ
      - NNM
      - MMN
      - otros códigos diagnósticos si aparecieran por error.
    """
    nodes = tri["nodes"]
    families = [node_family_2(n) for n in nodes]

    nM = families.count("M")
    nN = families.count("N")
    nQ = families.count("Q")

    if nM == 3:
        return "MMM"

    if nM == 2 and nQ == 1:
        return "MMQ"

    if nN == 2 and nM == 1:
        return "NNM"

    if nM == 2 and nN == 1:
        return "MMN"

    if nM == 1 and nQ == 2:
        return "MQQ"

    if nM == 1 and nN == 1 and nQ == 1:
        return "MNQ"

    if nN == 1 and nQ == 2:
        return "NQQ"

    if nN == 2 and nQ == 1:
        return "NNQ"

    if nQ == 3:
        return "QQQ"

    if nN == 3:
        return "NNN"

    return "".join(sorted(families))


def triangle_family_dashed_2(code):
    """
    Convierte códigos compactos a formato legible.
    """
    mapping = {
        "MMM": "M-M-M",
        "MMQ": "M-M-Q",
        "NNM": "N-N-M",
        "MMN": "M-M-N",
        "MQQ": "M-Q-Q",
        "MNQ": "M-N-Q",
        "NQQ": "N-Q-Q",
        "NNQ": "N-N-Q",
        "QQQ": "Q-Q-Q",
        "NNN": "N-N-N",
    }

    return mapping.get(code, code)


def decorate_triangle_type_2(tri):
    """
    Asegura que cada triángulo tenga:
      - type: código compacto, por ejemplo MMQ.
      - triangle_type: formato con guiones, por ejemplo M-M-Q.
    """
    tri_ext = dict(tri)

    code = triangle_family_code_2(tri_ext)
    tri_ext["type"] = code
    tri_ext["triangle_type"] = triangle_family_dashed_2(code)

    return tri_ext


def mast_index_from_node_2(mast_node):
    """
    Extrae el índice de un mástil a partir de una etiqueta tipo M0, M1, etc.
    """
    label = str(mast_node["label"])

    if not label.startswith("M"):
        raise ValueError(f"Etiqueta de mástil inválida: {label}")

    return int(label.replace("M", ""))


# =========================================================
# UTILIDADES ANGULARES
# =========================================================

def normalize_0_2pi_local_2(theta):
    """
    Usa normalize_0_2pi si ya existe en el notebook.
    Si no existe, aplica normalización local.
    """
    if "normalize_0_2pi" in globals():
        return normalize_0_2pi(theta)

    return theta % (2.0 * np.pi)


def angular_diff_2(a, b):
    """
    Diferencia angular mínima entre dos ángulos.
    """
    d = abs(a - b) % (2.0 * np.pi)
    return min(d, 2.0 * np.pi - d)


def get_all_useful_edges_2(mast_index, results_obj):
    """
    Obtiene todos los bordes angulares de los intervalos útiles de un mástil.
    """
    edges = []

    for a, b in results_obj[mast_index]["useful_intervals"]:
        edges.append(normalize_0_2pi_local_2(a))
        edges.append(normalize_0_2pi_local_2(b))

    return edges


def direction_angle_from_mast_to_q_2(q_node, mast_node):
    """
    Ángulo en planta desde el mástil hacia el punto Q.
    """
    dx = q_node["x"] - mast_node["x"]
    dy = q_node["y"] - mast_node["y"]

    return normalize_0_2pi_local_2(np.arctan2(dy, dx))


def node_matches_surviving_original_edge_2(
    q_node,
    mast_node,
    mast_index,
    original_results,
    updated_results,
    angle_tol=1e-4
):
    """
    Verifica si la dirección M -> Q coincide con un borde útil original
    que todavía existe en los resultados actualizados.
    """
    theta = direction_angle_from_mast_to_q_2(q_node, mast_node)

    original_edges = get_all_useful_edges_2(mast_index, original_results)
    updated_edges = get_all_useful_edges_2(mast_index, updated_results)

    for original_edge in original_edges:

        if angular_diff_2(theta, original_edge) > angle_tol:
            continue

        for updated_edge in updated_edges:
            if angular_diff_2(original_edge, updated_edge) <= angle_tol:
                return True, original_edge

    return False, None


# =========================================================
# FILTRO ESTRUCTURAL PARA M-M-Q
# =========================================================

def filter_mmq_by_surviving_original_useful_edges_2(
    triangles,
    original_results,
    updated_results,
    angle_tol=1e-4
):
    """
    Conserva:
      - MMM directamente.
      - NNM directamente.
      - MMN directamente.
      - MMQ solo si Q coincide con bordes útiles vigentes
        desde ambos mástiles.

    Descarta:
      - MMQ que no cumplan la validación angular.
      - cualquier otro tipo que llegue por error.
    """
    kept = []
    removed = []

    for tri in triangles:
        tri_ext = decorate_triangle_type_2(tri)
        tri_code = tri_ext["type"]

        # ---------------------------------
        # 1) Tipos que se conservan directamente
        # ---------------------------------
        if tri_code in ["MMM", "NNM", "MMN"]:
            tri_ext["kept_reason"] = (
                f"{triangle_family_dashed_2(tri_code)} conservado directamente en Filtro 2"
            )
            kept.append(tri_ext)
            continue

        # ---------------------------------
        # 2) Solo M-M-Q pasa por validación estructural
        # ---------------------------------
        if tri_code == "MMQ":

            mast_nodes = [
                n for n in tri_ext["nodes"]
                if node_family_2(n) == "M"
            ]

            q_nodes = [
                n for n in tri_ext["nodes"]
                if node_family_2(n) == "Q"
            ]

            if len(mast_nodes) != 2 or len(q_nodes) != 1:
                tri_ext["removed_reason"] = "M-M-Q inválido por composición de nodos"
                removed.append(tri_ext)
                continue

            q_node = q_nodes[0]
            m1, m2 = mast_nodes

            idx1 = mast_index_from_node_2(m1)
            idx2 = mast_index_from_node_2(m2)

            theta1 = direction_angle_from_mast_to_q_2(q_node, m1)
            theta2 = direction_angle_from_mast_to_q_2(q_node, m2)

            ok1, edge1 = node_matches_surviving_original_edge_2(
                q_node=q_node,
                mast_node=m1,
                mast_index=idx1,
                original_results=original_results,
                updated_results=updated_results,
                angle_tol=angle_tol
            )

            ok2, edge2 = node_matches_surviving_original_edge_2(
                q_node=q_node,
                mast_node=m2,
                mast_index=idx2,
                original_results=original_results,
                updated_results=updated_results,
                angle_tol=angle_tol
            )

            tri_ext["mmq_theta_m1_rad"] = theta1
            tri_ext["mmq_theta_m2_rad"] = theta2
            tri_ext["mmq_theta_m1_deg"] = float(np.degrees(theta1))
            tri_ext["mmq_theta_m2_deg"] = float(np.degrees(theta2))

            tri_ext["mmq_q_edge_match_m1"] = bool(ok1)
            tri_ext["mmq_q_edge_match_m2"] = bool(ok2)
            tri_ext["mmq_q_edge_info_m1"] = edge1
            tri_ext["mmq_q_edge_info_m2"] = edge2

            if ok1 and ok2:
                tri_ext["kept_reason"] = (
                    f"{q_node['label']} coincide con bordes útiles vigentes "
                    f"desde {m1['label']} y {m2['label']}"
                )
                kept.append(tri_ext)
            else:
                reasons = []

                if not ok1:
                    reasons.append(
                        f"{m1['label']}->{q_node['label']} no coincide con borde original vigente"
                    )

                if not ok2:
                    reasons.append(
                        f"{m2['label']}->{q_node['label']} no coincide con borde original vigente"
                    )

                tri_ext["removed_reason"] = " | ".join(reasons)
                removed.append(tri_ext)

            continue

        # ---------------------------------
        # 3) Protección: si llega otro tipo, se descarta
        # ---------------------------------
        tri_ext["removed_reason"] = (
            f"Tipo {tri_code} no permitido en Filtro 2. "
            "Debió ser eliminado en la generación inicial."
        )
        removed.append(tri_ext)

    return kept, removed


# =========================================================
# NODOS ACTIVOS DESPUÉS DEL FILTRO
# =========================================================

def build_active_tri_nodes_from_triangles_2(tri_nodes, triangles):
    """
    Conserva:
      - todos los mástiles M;
      - solo los puntos Q que aparecen en triángulos conservados;
      - solo los puntos N que aparecen en triángulos conservados.
    """
    active_labels = set()

    for tri in triangles:
        for n in tri["nodes"]:
            active_labels.add(str(n["label"]))

    active_tri_nodes = []

    for n in tri_nodes:
        fam = node_family_2(n)

        if fam == "M":
            active_tri_nodes.append(n)
            continue

        if str(n["label"]) in active_labels:
            active_tri_nodes.append(n)

    return active_tri_nodes


# =========================================================
# CONTEOS Y LISTADOS
# =========================================================

def triangles_type_counts_2(triangles):
    """
    Conteo por tipo compacto.
    """
    counts = {}

    for tri in triangles:
        code = triangle_family_code_2(tri)
        counts[code] = counts.get(code, 0) + 1

    return counts


def grouped_triangles_by_type_2(triangles):
    """
    Agrupa triángulos por tipo compacto.
    """
    grouped = {}

    for tri in triangles:
        code = triangle_family_code_2(tri)
        grouped.setdefault(code, []).append(tri)

    return grouped


# =========================================================
# UTILIDADES DE GRÁFICA — COLORES Y GROSORES
# =========================================================

def triangle_color_2(tri_code):
    """
    Color por tipo de triángulo conservado.
    """
    if tri_code == "MMM":
        return "gray"

    if tri_code == "MMQ":
        return "red"

    if tri_code == "NNM":
        return "green"

    if tri_code == "MMN":
        return "purple"

    return "black"


def triangle_width_2(tri_code):
    """
    Grosor por tipo de triángulo conservado.
    """
    if tri_code == "MMN":
        return 3

    if tri_code == "NNM":
        return 3

    return 3


# =========================================================
# GRÁFICA — GUARDAS
# =========================================================

def plot_guard_references_filter_2(
    fig,
    masts,
    guard_wire_inputs=None,
    guard_wire_fragments_pre=None
):
    """
    Dibuja guardas como referencia.
    Se dibujan antes de los triángulos para que los triángulos queden encima.
    """
    x_vals = []
    y_vals = []
    z_vals = []
    text_vals = []

    # ---------------------------------
    # 1) Guardas segmentadas, si existen
    # ---------------------------------
    if guard_wire_fragments_pre is not None and len(guard_wire_fragments_pre) > 0:

        for frag in guard_wire_fragments_pre:
            p1 = frag["p1"]
            p2 = frag["p2"]

            label1 = frag.get("label1", "")
            label2 = frag.get("label2", "")
            host_guard = frag.get("host_guard", "")

            hover_txt = (
                f"Fragmento de guarda<br>"
                f"{label1} - {label2}<br>"
                f"Guarda base: {host_guard}"
            )

            x_vals.extend([p1[0], p2[0], None])
            y_vals.extend([p1[1], p2[1], None])
            z_vals.extend([p1[2], p2[2], None])
            text_vals.extend([hover_txt, hover_txt, None])

        fig.add_trace(go.Scatter3d(
            x=x_vals,
            y=y_vals,
            z=z_vals,
            mode="lines",
            line=dict(color="darkgreen", width=5),
            name="Guardas segmentadas",
            hoverinfo="text",
            text=text_vals,
            showlegend=True
        ))

        return

    # ---------------------------------
    # 2) Guardas directas
    # ---------------------------------
    if guard_wire_inputs is None:
        return

    for gw in guard_wire_inputs:

        if isinstance(gw, dict):
            i = int(gw["i"])
            j = int(gw["j"])
        else:
            i = int(gw[0])
            j = int(gw[1])

        mi = masts[i]
        mj = masts[j]

        hover_txt = f"Guarda M{i} - M{j}"

        x_vals.extend([mi.x, mj.x, None])
        y_vals.extend([mi.y, mj.y, None])
        z_vals.extend([mi.h, mj.h, None])
        text_vals.extend([hover_txt, hover_txt, None])

    if len(x_vals) > 0:
        fig.add_trace(go.Scatter3d(
            x=x_vals,
            y=y_vals,
            z=z_vals,
            mode="lines",
            line=dict(color="darkgreen", width=5),
            name="Guardas",
            hoverinfo="text",
            text=text_vals,
            showlegend=True
        ))


# =========================================================
# GRÁFICA — TRIÁNGULOS AGRUPADOS POR TIPO
# =========================================================

def add_triangle_edges_grouped_by_type_filter_2(fig, kept_triangles):
    """
    Dibuja las aristas reales de los triángulos conservados agrupadas por tipo.

    Ventaja:
      - La leyenda interactiva sí apaga/enciende las líneas reales.
      - No se usa leyenda manual con trazas vacías.
    """
    type_order = ["MMM", "MMQ", "NNM", "MMN"]

    grouped_edges = {
        tri_type: {
            "x": [],
            "y": [],
            "z": [],
            "text": []
        }
        for tri_type in type_order
    }

    for tri_data in kept_triangles:
        tri_ext = decorate_triangle_type_2(tri_data)
        tri_code = tri_ext["type"]

        if tri_code not in grouped_edges:
            continue

        n1, n2, n3 = tri_ext["nodes"]
        labels = tri_ext["labels"]
        tri_type = tri_ext["triangle_type"]

        edges = [
            (n1, n2, labels[0], labels[1]),
            (n2, n3, labels[1], labels[2]),
            (n3, n1, labels[2], labels[0]),
        ]

        tri_label = "-".join(labels)

        for a, b, la, lb in edges:
            grouped_edges[tri_code]["x"].extend([a["x"], b["x"], None])
            grouped_edges[tri_code]["y"].extend([a["y"], b["y"], None])
            grouped_edges[tri_code]["z"].extend([a["z"], b["z"], None])

            hover_txt = (
                f"Tipo: {tri_code}<br>"
                f"Triángulo: {tri_label}<br>"
                f"Formato: {tri_type}<br>"
                f"Arista: {la} - {lb}"
            )

            grouped_edges[tri_code]["text"].extend([hover_txt, hover_txt, None])

    for tri_code in type_order:
        data = grouped_edges[tri_code]

        if len(data["x"]) == 0:
            continue

        fig.add_trace(go.Scatter3d(
            x=data["x"],
            y=data["y"],
            z=data["z"],
            mode="lines",
            line=dict(
                color=triangle_color_2(tri_code),
                width=triangle_width_2(tri_code)
            ),
            name=f"Triángulos {tri_code}",
            hoverinfo="text",
            text=data["text"],
            showlegend=True
        ))


# =========================================================
# GRÁFICA — NODOS ACTIVOS
# =========================================================

def plot_active_Q_nodes_filter_2(fig, tri_nodes):
    """
    Dibuja puntos Q activos.
    """
    q_nodes = [
        n for n in tri_nodes
        if node_family_2(n) == "Q"
    ]

    if not q_nodes:
        return

    fig.add_trace(go.Scatter3d(
        x=[n["x"] for n in q_nodes],
        y=[n["y"] for n in q_nodes],
        z=[n["z"] for n in q_nodes],
        mode="markers+text",
        marker=dict(size=6, color="orange", symbol="circle"),
        text=[n["label"] for n in q_nodes],
        textposition="top center",
        name="Q activos",
        hovertext=[
            (
                f"{n['label']}<br>"
                f"x={float(n['x']):.3f}<br>"
                f"y={float(n['y']):.3f}<br>"
                f"z={float(n['z']):.3f}"
            )
            for n in q_nodes
        ],
        hoverinfo="text",
        showlegend=True
    ))


def plot_active_N_nodes_filter_2(fig, tri_nodes):
    """
    Dibuja puntos N activos.
    """
    n_nodes = [
        n for n in tri_nodes
        if node_family_2(n) == "N"
    ]

    if not n_nodes:
        return

    fig.add_trace(go.Scatter3d(
        x=[n["x"] for n in n_nodes],
        y=[n["y"] for n in n_nodes],
        z=[n["z"] for n in n_nodes],
        mode="markers+text",
        marker=dict(size=9, color="cyan", symbol="diamond"),
        text=[n["label"] for n in n_nodes],
        textposition="top center",
        name="N activos",
        hovertext=[
            (
                f"{n['label']}<br>"
                f"x={float(n['x']):.3f}<br>"
                f"y={float(n['y']):.3f}<br>"
                f"z={float(n['z']):.3f}"
            )
            for n in n_nodes
        ],
        hoverinfo="text",
        showlegend=True
    ))


def plot_reference_N_nodes_filter_2(fig, early_N_nodes=None, active_labels=None):
    """
    Dibuja puntos N generados temprano pero no activos.
    Esto ayuda a diagnosticar si existen N que no quedaron conectados
    a ningún triángulo conservado.
    """
    if early_N_nodes is None or len(early_N_nodes) == 0:
        return

    active_labels = active_labels or set()

    ref_nodes = [
        n for n in early_N_nodes
        if str(n["label"]) not in active_labels
    ]

    if not ref_nodes:
        return

    fig.add_trace(go.Scatter3d(
        x=[float(n["x"]) for n in ref_nodes],
        y=[float(n["y"]) for n in ref_nodes],
        z=[float(n["z"]) for n in ref_nodes],
        mode="markers+text",
        marker=dict(size=7, color="cyan", symbol="diamond-open"),
        text=[n["label"] for n in ref_nodes],
        textposition="bottom center",
        name="N generados no activos",
        hovertext=[
            (
                f"{n['label']}<br>"
                f"x={float(n['x']):.3f}<br>"
                f"y={float(n['y']):.3f}<br>"
                f"z={float(n['z']):.3f}<br>"
                f"host_guard={n.get('host_guard', '')}<br>"
                f"No pertenece a triángulo conservado"
            )
            for n in ref_nodes
        ],
        hoverinfo="text",
        showlegend=True
    ))


def plot_masts_filter_2(fig, tri_nodes):
    """
    Dibuja mástiles.
    """
    mast_nodes = [
        n for n in tri_nodes
        if node_family_2(n) == "M"
    ]

    x_lines = []
    y_lines = []
    z_lines = []
    text_lines = []

    for n in mast_nodes:
        hover_txt = f"Mástil {n['label']}"

        x_lines.extend([n["x"], n["x"], None])
        y_lines.extend([n["y"], n["y"], None])
        z_lines.extend([0.0, n["z"], None])
        text_lines.extend([hover_txt, hover_txt, None])

    if len(x_lines) > 0:
        fig.add_trace(go.Scatter3d(
            x=x_lines,
            y=y_lines,
            z=z_lines,
            mode="lines",
            line=dict(color="blue", width=8),
            name="Mástiles",
            hoverinfo="text",
            text=text_lines,
            showlegend=True
        ))

    if mast_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in mast_nodes],
            y=[n["y"] for n in mast_nodes],
            z=[n["z"] for n in mast_nodes],
            mode="markers+text",
            marker=dict(size=5, color="black"),
            text=[n["label"] for n in mast_nodes],
            textposition="top center",
            name="Puntas de mástil",
            hovertext=[
                (
                    f"{n['label']}<br>"
                    f"x={float(n['x']):.3f}<br>"
                    f"y={float(n['y']):.3f}<br>"
                    f"z={float(n['z']):.3f}"
                )
                for n in mast_nodes
            ],
            hoverinfo="text",
            showlegend=True
        ))


# =========================================================
# GRÁFICA — REFERENCIAS DE MÁSTIL SOLO Y SUELO
# =========================================================

def plot_single_mast_reference_filter_2(fig, masts, results, sphere_radius):
    """
    Dibuja referencias en planta de las zonas de mástil solo.
    """
    if "effective_radius" not in globals():
        print("ADVERTENCIA: no existe effective_radius; no se dibuja referencia de mástil solo.")
        return

    for i, mast in enumerate(masts):
        ai = effective_radius(mast.h, sphere_radius)
        useful_intervals = results[i]["useful_intervals"]

        for th1, th2 in useful_intervals:
            theta = np.linspace(th1, th2, 80)
            r = np.linspace(0.0, ai, 20)

            TH, RR = np.meshgrid(theta, r, indexing="xy")

            X = mast.x + RR * np.cos(TH)
            Y = mast.y + RR * np.sin(TH)
            Z = np.zeros_like(X)

            fig.add_trace(go.Surface(
                x=X,
                y=Y,
                z=Z,
                showscale=False,
                opacity=0.10,
                hoverinfo="skip",
                name=f"Mástil solo M{i}",
                showlegend=False
            ))


def plot_ground_filter_2(fig, tri_nodes):
    """
    Dibuja plano base.
    """
    if tri_nodes:
        xy = np.array([[n["x"], n["y"]] for n in tri_nodes], dtype=float)

        xmin, ymin = xy.min(axis=0) - 5
        xmax, ymax = xy.max(axis=0) + 5
    else:
        xmin, ymin, xmax, ymax = -5, -5, 5, 5

    Xg, Yg = np.meshgrid(
        np.linspace(xmin, xmax, 2),
        np.linspace(ymin, ymax, 2)
    )

    fig.add_trace(go.Surface(
        x=Xg,
        y=Yg,
        z=np.zeros_like(Xg),
        opacity=0.08,
        showscale=False,
        hoverinfo="skip",
        name="Suelo",
        showlegend=False
    ))


# =========================================================
# GRÁFICA PRINCIPAL DEL FILTRO 2
# =========================================================

def plot_triangles_after_mmq_edge_filter_2(
    tri_nodes,
    kept_triangles,
    masts,
    results,
    sphere_radius,
    guard_wire_inputs=None,
    guard_wire_fragments_pre=None,
    early_N_nodes=None,
    show_single_mast_reference=True,
    show_guard_references=True
):
    """
    Grafica el resultado del Filtro 2.
    """
    fig = go.Figure()

    # ---------------------------------
    # 1) Guardas primero, para que los triángulos queden encima
    # ---------------------------------
    if show_guard_references:
        plot_guard_references_filter_2(
            fig=fig,
            masts=masts,
            guard_wire_inputs=guard_wire_inputs,
            guard_wire_fragments_pre=guard_wire_fragments_pre
        )

    # ---------------------------------
    # 2) Triángulos conservados agrupados por tipo
    # ---------------------------------
    add_triangle_edges_grouped_by_type_filter_2(
        fig=fig,
        kept_triangles=kept_triangles
    )

    # ---------------------------------
    # 3) Puntos activos
    # ---------------------------------
    plot_active_Q_nodes_filter_2(fig, tri_nodes)
    plot_active_N_nodes_filter_2(fig, tri_nodes)

    # ---------------------------------
    # 4) Puntos N generados pero no activos
    # ---------------------------------
