def triangle_color_5(tri_code):
    if tri_code == "MMM":
        return "gray"
    if tri_code == "MMQ":
        return "red"
    if tri_code == "NNM":
        return "green"
    if tri_code == "MMN":
        return "purple"
    return "black"


def triangle_width_5(tri_code):
    return TRIANGLE_LINE_WIDTH_5


def plot_guard_references_filter_5(fig, masts, guard_wire_inputs=None):
    if guard_wire_inputs is None:
        return

    x_vals = []
    y_vals = []
    z_vals = []
    text_vals = []

    for gw in guard_wire_inputs:
        if isinstance(gw, dict):
            i = int(gw["i"])
            j = int(gw["j"])
        else:
            i = int(gw[0])
            j = int(gw[1])

        mi = masts[i]
        mj = masts[j]

        hover_txt = f"Guarda M{i} - M{j}"
        x_vals.extend([mi.x, mj.x, None])
        y_vals.extend([mi.y, mj.y, None])
        z_vals.extend([mi.h, mj.h, None])
        text_vals.extend([hover_txt, hover_txt, None])

    if len(x_vals) > 0:
        fig.add_trace(go.Scatter3d(
            x=x_vals,
            y=y_vals,
            z=z_vals,
            mode="lines",
            line=dict(color="darkgreen", width=GUARD_LINE_WIDTH_5),
            name="Guardas",
            hoverinfo="text",
            text=text_vals,
            showlegend=True
        ))


def add_triangle_edges_grouped_by_type_filter_5(fig, triangles):
    type_order = ["MMM", "MMQ", "NNM", "MMN"]

    grouped_edges = {
        tri_type: {"x": [], "y": [], "z": [], "text": []}
        for tri_type in type_order
    }

    for tri_data in triangles:
        tri_ext = decorate_triangle_type_5(tri_data)
        tri_code = tri_ext["type"]

        if tri_code not in grouped_edges:
            continue

        n1, n2, n3 = tri_ext["nodes"]
        labels = tri_ext["labels"]
        tri_type = tri_ext["triangle_type"]
        tri_label = "-".join([str(x) for x in labels])

        edges = [
            (n1, n2, labels[0], labels[1]),
            (n2, n3, labels[1], labels[2]),
            (n3, n1, labels[2], labels[0]),
        ]

        for a, b, la, lb in edges:
            grouped_edges[tri_code]["x"].extend([a["x"], b["x"], None])
            grouped_edges[tri_code]["y"].extend([a["y"], b["y"], None])
            grouped_edges[tri_code]["z"].extend([a["z"], b["z"], None])

            hover_txt = (
                f"Tipo: {tri_code}<br>"
                f"Triángulo: {tri_label}<br>"
                f"Formato: {tri_type}<br>"
                f"Arista: {la} - {lb}"
            )
            grouped_edges[tri_code]["text"].extend([hover_txt, hover_txt, None])

    for tri_code in type_order:
        data = grouped_edges[tri_code]

        if len(data["x"]) == 0:
            continue

        fig.add_trace(go.Scatter3d(
            x=data["x"],
            y=data["y"],
            z=data["z"],
            mode="lines",
            line=dict(color=triangle_color_5(tri_code), width=triangle_width_5(tri_code)),
            name=f"Triángulos {tri_code}",
            hoverinfo="text",
            text=data["text"],
            showlegend=True
        ))


def add_removed_mlike_grouped_filter_5(fig, removed_triangles):
    if not removed_triangles:
        return

    x_vals = []
    y_vals = []
    z_vals = []
    text_vals = []

    for tri_data in removed_triangles:
        tri_ext = decorate_triangle_type_5(tri_data)
        n1, n2, n3 = tri_ext["nodes"]
        labels = tri_ext["labels"]
        tri_type = tri_ext["triangle_type"]

        xs = [n1["x"], n2["x"], n3["x"], n1["x"], None]
        ys = [n1["y"], n2["y"], n3["y"], n1["y"], None]
        zs = [n1["z"], n2["z"], n3["z"], n1["z"], None]

        hover_txt = (
            f"{tri_type} eliminado<br>"
            f"{'-'.join([str(x) for x in labels])}<br>"
            f"{tri_ext.get('removed_reason', '')}"
        )

        x_vals.extend(xs)
        y_vals.extend(ys)
        z_vals.extend(zs)
        text_vals.extend([hover_txt for _ in xs])

    fig.add_trace(go.Scatter3d(
        x=x_vals,
        y=y_vals,
        z=z_vals,
        mode="lines+markers",
        line=dict(color="red", width=TRIANGLE_LINE_WIDTH_5),
        marker=dict(size=4, color="red"),
        name="M-like eliminados por capa mástil solo",
        hoverinfo="text",
        text=text_vals,
        showlegend=True
    ))


# Alias compatible con versiones anteriores.
def add_removed_mmm_grouped_filter_5(fig, removed_triangles):
    add_removed_mlike_grouped_filter_5(fig, removed_triangles)


def add_n_nodes_to_fig_5(fig, tri_nodes):
    n_nodes = [n for n in tri_nodes if node_family_5(n) == "N"]

    if n_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in n_nodes],
            y=[n["y"] for n in n_nodes],
            z=[n["z"] for n in n_nodes],
            mode="markers+text",
            marker=dict(size=9, color="cyan", symbol="diamond"),
            text=[n["label"] for n in n_nodes],
            textposition="top center",
            name="N activos",
            hoverinfo="text",
            hovertext=[
                f"{n['label']}<br>x={float(n['x']):.3f}<br>y={float(n['y']):.3f}<br>z={float(n['z']):.3f}"
                for n in n_nodes
            ],
            showlegend=True
        ))


def add_q_nodes_to_fig_5(fig, tri_nodes, name="Q activos"):
    q_nodes = [n for n in tri_nodes if node_family_5(n) == "Q"]

    if q_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in q_nodes],
            y=[n["y"] for n in q_nodes],
            z=[n["z"] for n in q_nodes],
            mode="markers+text",
            marker=dict(size=6, color="orange"),
            text=[n["label"] for n in q_nodes],
            textposition="top center",
            name=name,
            hoverinfo="text",
            hovertext=[
                f"{n['label']}<br>x={float(n['x']):.3f}<br>y={float(n['y']):.3f}<br>z={float(n['z']):.3f}"
                for n in q_nodes
            ],
            showlegend=True
        ))


def add_masts_to_fig_from_nodes_5(fig, tri_nodes):
    mast_nodes = [n for n in tri_nodes if node_family_5(n) == "M"]

    x_lines = []
    y_lines = []
    z_lines = []
    text_lines = []

    for n in mast_nodes:
        hover_txt = f"Mástil {n['label']}"
        x_lines.extend([n["x"], n["x"], None])
        y_lines.extend([n["y"], n["y"], None])
        z_lines.extend([0.0, n["z"], None])
        text_lines.extend([hover_txt, hover_txt, None])

    if len(x_lines) > 0:
        fig.add_trace(go.Scatter3d(
            x=x_lines,
            y=y_lines,
            z=z_lines,
            mode="lines",
            line=dict(color="blue", width=MAST_LINE_WIDTH_5),
            name="Mástiles",
            hoverinfo="text",
            text=text_lines,
            showlegend=True
        ))

    if mast_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in mast_nodes],
            y=[n["y"] for n in mast_nodes],
            z=[n["z"] for n in mast_nodes],
            mode="markers+text",
            marker=dict(size=5, color="black"),
            text=[n["label"] for n in mast_nodes],
            textposition="top center",
            name="Puntas de mástil",
            hoverinfo="text",
            hovertext=[
                f"{n['label']}<br>x={float(n['x']):.3f}<br>y={float(n['y']):.3f}<br>z={float(n['z']):.3f}"
                for n in mast_nodes
            ],
            showlegend=True
        ))


def add_ground_to_fig_5(fig, tri_nodes=None, masts=None):
    if tri_nodes is not None and len(tri_nodes) > 0:
        all_xy = np.array([[n["x"], n["y"]] for n in tri_nodes], dtype=float)
    elif masts is not None and len(masts) > 0:
        all_xy = np.array([[m.x, m.y] for m in masts], dtype=float)
    else:
        return

    xmin, ymin = all_xy.min(axis=0) - 5
    xmax, ymax = all_xy.max(axis=0) + 5

    Xg, Yg = np.meshgrid(np.linspace(xmin, xmax, 2), np.linspace(ymin, ymax, 2))

    fig.add_trace(go.Surface(
        x=Xg,
        y=Yg,
        z=np.zeros_like(Xg),
        opacity=0.08,
        showscale=False,
        hoverinfo="skip",
        name="Suelo",
        showlegend=False
    ))


def add_single_mast_reference_to_fig_5(
    fig,
    masts,
    results_obj,
    sphere_radius,
    opacity=0.13,
    name_prefix="Capa mástil solo"
):
    for i, mast in enumerate(masts):
        ai = local_effective_radius_5(mast.h, sphere_radius)
        useful_intervals = get_result_by_mast_5(results_obj, i).get("useful_intervals", [])

        for th1, th2 in useful_intervals:
            for a, b in normalize_interval_no_wrap_5((th1, th2)):
                theta = np.linspace(a, b, 80)
                r = np.linspace(0.0, ai, 25)
                TH, RR = np.meshgrid(theta, r, indexing="xy")
                X = mast.x + RR * np.cos(TH)
                Y = mast.y + RR * np.sin(TH)
                Z = np.zeros_like(X)

                fig.add_trace(go.Surface(
                    x=X,
                    y=Y,
                    z=Z,
                    showscale=False,
                    opacity=opacity,
                    hoverinfo="skip",
                    name=f"{name_prefix} M{i}",
                    showlegend=False
                ))


def plot_after_mlike_single_mast_overlap_filter_5(
    tri_nodes,
    kept_triangles,
    removed_triangles,
    masts,
    results_obj,
    sphere_radius,
    invasion_points=None,
    guard_wire_inputs=None,
    show_removed_mlike=True,
    show_invasion_points=True,
    show_single_mast_reference=True,
    show_guard_references=True
):
    fig = go.Figure()

    if show_guard_references:
        plot_guard_references_filter_5(fig=fig, masts=masts, guard_wire_inputs=guard_wire_inputs)

    add_triangle_edges_grouped_by_type_filter_5(fig=fig, triangles=kept_triangles)

    if show_removed_mlike:
        add_removed_mlike_grouped_filter_5(fig=fig, removed_triangles=removed_triangles)

    if show_invasion_points and invasion_points:
        fig.add_trace(go.Scatter3d(
            x=[p["x"] for p in invasion_points],
            y=[p["y"] for p in invasion_points],
            z=[0.25 for _ in invasion_points],
            mode="markers",
            marker=dict(size=5, color="red"),
            name="Puntos interiores de invasión",
            hoverinfo="text",
            text=[
                f"M{p['mast_idx']}<br>θ={p['theta_deg']:.2f}°<br>r={p['r']:.4f} / ai={p['ai']:.4f}"
                for p in invasion_points
            ],
            showlegend=True
        ))

    add_q_nodes_to_fig_5(fig, tri_nodes, name="Q activos")
    add_n_nodes_to_fig_5(fig, tri_nodes)
    add_masts_to_fig_from_nodes_5(fig, tri_nodes)

    if show_single_mast_reference:
        add_single_mast_reference_to_fig_5(
            fig=fig,
            masts=masts,
            results_obj=results_obj,
            sphere_radius=sphere_radius,
            opacity=0.13,
            name_prefix="Capa mástil solo"
        )

    add_ground_to_fig_5(fig, tri_nodes=tri_nodes, masts=masts)

    fig.update_layout(
        title="Filtro 4 — M-M-M / M-M-N / N-N-M vs capa de mástil solo en planta",
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=850,
        legend=dict(
            title="Elementos",
            itemclick="toggle",
            itemdoubleclick="toggleothers"
        )
    )

    fig.show()


# Alias compatible con el nombre anterior.
def plot_after_mmm_single_mast_overlap_filter_5(*args, **kwargs):
    # Traduce nombres antiguos de argumentos.
    if "show_removed_mmm" in kwargs:
        kwargs["show_removed_mlike"] = kwargs.pop("show_removed_mmm")
    return plot_after_mlike_single_mast_overlap_filter_5(*args, **kwargs)


def plot_new_useful_angles_guard_case_5(
    masts,
    results_obj,
    corrected_results_obj,
    sphere_radius,
    guard_case_records,
    title="Nuevos rangos útiles corregidos por el caso puntual con cable de guarda"
):
    fig = go.Figure()

    for mast_idx, mast in enumerate(masts):
        ai = local_effective_radius_5(mast.h, sphere_radius)
        theta = np.linspace(0, 2.0 * np.pi, 300)
        X = mast.x + ai * np.cos(theta)
        Y = mast.y + ai * np.sin(theta)

        fig.add_trace(go.Scatter(
            x=X,
            y=Y,
            mode="lines",
            line=dict(width=1.2),
            name=f"Círculo M{mast_idx}"
        ))

        fig.add_trace(go.Scatter(
            x=[mast.x],
            y=[mast.y],
            mode="markers+text",
            marker=dict(size=7, color="black"),
            text=[f"M{mast_idx}"],
            textposition="top center",
            name=f"M{mast_idx}"
        ))

    highlight_masts = set()

    for case in guard_case_records:
        highlight_masts.add(case["mast_a_idx"])
        highlight_masts.add(case["mast_b_idx"])
        highlight_masts.add(case["cut_mast_idx"])

    for mast_idx in sorted(highlight_masts):
        mast = masts[mast_idx]
        ai = local_effective_radius_5(mast.h, sphere_radius)
        useful_intervals = list(get_result_by_mast_5(corrected_results_obj, mast_idx).get("useful_intervals", []))

        for interval_idx, (th1, th2) in enumerate(useful_intervals):
            for a, b in normalize_interval_no_wrap_5((th1, th2)):
                theta = np.linspace(a, b, 120)
                X = mast.x + ai * np.cos(theta)
                Y = mast.y + ai * np.sin(theta)

                fig.add_trace(go.Scatter(
                    x=X,
                    y=Y,
                    mode="lines",
                    line=dict(width=3),
                    name=f"Útil corregido M{mast_idx}-{interval_idx}"
                ))

    for case in guard_case_records:
        q = case["new_q"]
        fig.add_trace(go.Scatter(
            x=[q["x"]],
            y=[q["y"]],
            mode="markers+text",
            marker=dict(size=9, color="orange"),
            text=[q["label"]],
            textposition="bottom center",
            name=q["label"]
        ))

    fig.update_layout(
        title=title,
        xaxis_title="X",
        yaxis_title="Y",
        yaxis_scaleanchor="x",
        template="simple_white",
        height=700,
        legend=dict(itemsizing="constant")
    )

    fig.show()


def plot_final_corrected_qm_graph_5(
    tri_nodes,
    kept_triangles,
    removed_triangles,
    masts,
    results_obj,
    corrected_results_obj,
    sphere_radius,
    removed_single_mast_intervals,
    q_points_new,
    qm_segments_new,
    invasion_points=None,
    guard_wire_inputs=None,
    title="Resultado corregido con segmentos Q-M redefinidos"
):
    fig = go.Figure()

    plot_guard_references_filter_5(fig=fig, masts=masts, guard_wire_inputs=guard_wire_inputs)
    add_triangle_edges_grouped_by_type_filter_5(fig=fig, triangles=kept_triangles)
    add_removed_mlike_grouped_filter_5(fig=fig, removed_triangles=removed_triangles)

    q_nodes = [
        n for n in tri_nodes
        if node_family_5(n) == "Q"
        and not q_node_belongs_to_removed_single_mast_layer_5(
            q_node=n,
            masts=masts,
            sphere_radius=sphere_radius,
            removed_interval_records=removed_single_mast_intervals,
            tol=REMOVED_Q_NODE_TOL_5
        )
    ]

    if q_nodes:
        fig.add_trace(go.Scatter3d(
            x=[n["x"] for n in q_nodes],
            y=[n["y"] for n in q_nodes],
            z=[n["z"] for n in q_nodes],
            mode="markers+text",
            marker=dict(size=6, color="orange"),
            text=[n["label"] for n in q_nodes],
            textposition="top center",
            name="Q activos corregidos",
            showlegend=True
        ))

    add_n_nodes_to_fig_5(fig, tri_nodes)

    if q_points_new:
        fig.add_trace(go.Scatter3d(
            x=[q["x"] for q in q_points_new],
            y=[q["y"] for q in q_points_new],
            z=[q["z"] for q in q_points_new],
            mode="markers+text",
            marker=dict(size=8, color="red"),
            text=[q["label"] for q in q_points_new],
            textposition="top center",
            name="Q nuevo",
            showlegend=True
        ))

    if qm_segments_new:
        x_seg = []
        y_seg = []
        z_seg = []
        text_seg = []

        for seg in qm_segments_new:
            hover_txt = f"{seg['mast_label']} → {seg['q_label']}"
            x_seg.extend([seg["x"][0], seg["x"][1], None])
            y_seg.extend([seg["y"][0], seg["y"][1], None])
            z_seg.extend([seg["z"][0], seg["z"][1], None])
            text_seg.extend([hover_txt, hover_txt, None])

        fig.add_trace(go.Scatter3d(
            x=x_seg,
            y=y_seg,
            z=z_seg,
            mode="lines",
            line=dict(color="red", width=QM_SEGMENT_LINE_WIDTH_5),
            name="Segmentos Q-M nuevos",
            hoverinfo="text",
            text=text_seg,
            showlegend=True
        ))

    if invasion_points:
        fig.add_trace(go.Scatter3d(
            x=[p["x"] for p in invasion_points],
            y=[p["y"] for p in invasion_points],
            z=[0.25 for _ in invasion_points],
            mode="markers",
            marker=dict(size=4, color="red"),
            name="Puntos invasión",
            hoverinfo="skip",
            showlegend=True
        ))

    mast_nodes_for_plot = [
        {"label": f"M{mast_idx}", "x": mast.x, "y": mast.y, "z": mast.h, "type": "M"}
        for mast_idx, mast in enumerate(masts)
    ]

    add_masts_to_fig_from_nodes_5(fig, mast_nodes_for_plot)

    add_single_mast_reference_to_fig_5(
        fig=fig,
        masts=masts,
        results_obj=corrected_results_obj,
        sphere_radius=sphere_radius,
        opacity=0.12,
        name_prefix="Capa corregida"
    )

    add_ground_to_fig_5(fig, tri_nodes=tri_nodes, masts=masts)

    fig.update_layout(
        title=title,
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=850,
        legend=dict(
            title="Elementos",
            itemclick="toggle",
            itemdoubleclick="toggleothers"
        )
    )

    fig.show()


