"""## Filtro 10: ELIMINACIÓN DE M-M-M Y M-M-N CUYAS ARISTAS SE CORTAN CON ARISTAS DE N-N-M EN PLANTA XY"""

# @title
# =========================================================
# FILTRO 10 — INVASIÓN DE ÁREA EN PLANTA CONTRA N-N-M
# CON EXCEPCIÓN ESTRUCTURAL PARA M-M-N PARALELO A N-N
# =========================================================
#
# Objetivo:
#   Volver al criterio inicial de invasión/solape de área en planta XY.
#   Se eliminan triángulos M-M-M y M-M-N si invaden en área XY a un N-N-M.
#
# Excepción para M-M-N:
#   Un M-M-N NO se elimina aunque invada área de N-N-M si cumple todo esto:
#     1) comparte dos de sus aristas con dos N-N-M distintos;
#     2) cada N-N-M comparte una arista distinta con ese M-M-N;
#     3) esos dos N-N-M comparten el mismo segmento N-N;
#     4) el segmento M-M del M-M-N es paralelo/alineado e igual en longitud
#        al segmento N-N compartido.
#
# Salidas principales:
#   kept_triangles_10
#   removed_triangles_area_invasion_nnm_10
#   removed_mmm_area_invasion_nnm_10
#   removed_mmn_area_invasion_nnm_10
#   protected_mmn_parallel_to_shared_nn_10
#   area_invasion_log_10
#   mmn_parallel_shared_nn_protection_log_10
#   nnm_reference_triangles_10
#   tri_nodes_after_filter_10
#   filtered_triangles_final
#   filtered_tri_nodes_final
#   filtered_results_final
# =========================================================

import numpy as np
import plotly.graph_objects as go
from collections import Counter


# =========================================================
# 0) PARÁMETROS
# =========================================================

XY_GEOM_TOL_10 = 1e-9
XY_AREA_ABS_TOL_10 = 1e-8

# Se considera invasión si el área de intersección supera estos umbrales.
AREA_INVASION_MIN_RATIO_CANDIDATE_10 = 1e-5
AREA_INVASION_MIN_RATIO_NNM_10 = 1e-5

SEGMENT_MIN_LENGTH_XY_10 = 1e-9

# Tolerancias de la excepción M-M-N.
PARALLEL_CROSS_TOL_10 = 1e-6
PARALLEL_DOT_TOL_10 = 1e-6
EQUAL_LENGTH_REL_TOL_10 = 1e-6

# Normalmente MM y NN son segmentos opuestos/paralelos, no necesariamente colineales.
REQUIRE_COLLINEAR_MM_NN_FOR_PROTECTION_10 = False
COLLINEAR_DISTANCE_TOL_10 = 1e-6

# Gráfica final post-filtro.
SHOW_SINGLE_MAST_REFERENCE_10 = True
SHOW_REMOVED_TRIANGLES_10 = False

TRIANGLE_LINE_WIDTH_10 = 3
GUARD_LINE_WIDTH_10 = 3
MAST_LINE_WIDTH_10 = 8


# =========================================================
# 1) UTILIDADES DE NODOS Y TRIÁNGULOS
# =========================================================

def node_family_filter_10(node):
    raw_type = str(node.get("type", "")).strip()
    label = str(node.get("label", "")).strip()

    if raw_type in {"M", "mast", "mast_top"} or label.startswith("M"):
        return "M"
    if raw_type == "N" or raw_type.startswith("auxiliary_N") or label.startswith("N"):
        return "N"
    if raw_type == "Q" or label.startswith("Q"):
        return "Q"
    return raw_type


def normalize_triangle_type_filter_10(tri_type):
    if tri_type is None:
        return None
    tri_type = str(tri_type).strip()
    return {
        "MMM": "M-M-M",
        "MMQ": "M-M-Q",
        "NNM": "N-N-M",
        "MMN": "M-M-N",
        "MQQ": "M-Q-Q",
        "QQQ": "Q-Q-Q",
        "MNQ": "M-N-Q",
        "NNN": "N-N-N",
        "NNQ": "N-N-Q",
    }.get(tri_type, tri_type)


def compact_triangle_type_filter_10(tri_type):
    tri_type = normalize_triangle_type_filter_10(tri_type)
    return {
        "M-M-M": "MMM",
        "M-M-Q": "MMQ",
        "N-N-M": "NNM",
        "M-M-N": "MMN",
        "M-Q-Q": "MQQ",
        "Q-Q-Q": "QQQ",
        "M-N-Q": "MNQ",
        "N-N-N": "NNN",
        "N-N-Q": "NNQ",
    }.get(tri_type, tri_type)


def classify_triangle_type_filter_10(tri_data):
    families = [node_family_filter_10(n) for n in tri_data["nodes"]]
    nM = families.count("M")
    nN = families.count("N")
    nQ = families.count("Q")

    if nM == 3:
        return "M-M-M"
    if nM == 2 and nQ == 1:
        return "M-M-Q"
    if nN == 2 and nM == 1:
        return "N-N-M"
    if nM == 2 and nN == 1:
        return "M-M-N"
    if nM == 1 and nQ == 2:
        return "M-Q-Q"
    if nQ == 3:
        return "Q-Q-Q"
    if nM == 1 and nN == 1 and nQ == 1:
        return "M-N-Q"
    if nN == 3:
        return "N-N-N"
    if nN == 2 and nQ == 1:
        return "N-N-Q"
    return "UNKNOWN"


def decorate_triangle_type_filter_10(tri):
    tri_ext = dict(tri)
    raw_type = tri_ext.get("triangle_type", tri_ext.get("type", None))
    tri_type = normalize_triangle_type_filter_10(raw_type)

    if tri_type is None or tri_type == "UNKNOWN":
        tri_type = classify_triangle_type_filter_10(tri_ext)

    tri_ext["triangle_type"] = tri_type
    tri_ext["type"] = compact_triangle_type_filter_10(tri_type)
    return tri_ext


def triangle_labels_filter_10(tri_data):
    if "labels" in tri_data:
        return tri_data["labels"]
    return tuple(str(n.get("label", "")) for n in tri_data.get("nodes", []))


def format_labels_filter_10(labels):
    if isinstance(labels, (tuple, list)):
        return "-".join(str(x) for x in labels)
    return str(labels)


def edge_label_key_filter_10(a_label, b_label):
    return tuple(sorted([str(a_label), str(b_label)]))


def node_xy_filter_10(node):
    return np.array([float(node["x"]), float(node["y"])], dtype=float)


def triangle_edges_filter_10(tri_data):
    tri_ext = decorate_triangle_type_filter_10(tri_data)
    n1, n2, n3 = tri_ext["nodes"]
    return [(n1, n2), (n2, n3), (n3, n1)]


def triangle_nodes_by_family_filter_10(tri_data):
    out = {"M": [], "N": [], "Q": [], "OTHER": []}
    for n in decorate_triangle_type_filter_10(tri_data)["nodes"]:
        fam = node_family_filter_10(n)
        out[fam if fam in out else "OTHER"].append(n)
    return out


def get_mmn_mm_edge_filter_10(tri_data):
    families = triangle_nodes_by_family_filter_10(tri_data)
    m_nodes = families["M"]
    if len(m_nodes) != 2:
        return None
    m1, m2 = m_nodes
    return {
        "nodes": (m1, m2),
        "labels": (str(m1["label"]), str(m2["label"])),
        "key": edge_label_key_filter_10(m1["label"], m2["label"]),
        "p1": node_xy_filter_10(m1),
        "p2": node_xy_filter_10(m2),
    }


def get_nnm_nn_edge_filter_10(tri_data):
    families = triangle_nodes_by_family_filter_10(tri_data)
    n_nodes = families["N"]
    if len(n_nodes) != 2:
        return None
    n1, n2 = n_nodes
    return {
        "nodes": (n1, n2),
        "labels": (str(n1["label"]), str(n2["label"])),
        "key": edge_label_key_filter_10(n1["label"], n2["label"]),
        "p1": node_xy_filter_10(n1),
        "p2": node_xy_filter_10(n2),
    }


def build_active_tri_nodes_after_filter_10(tri_nodes_input, triangles):
    node_by_label = {}
    for n in tri_nodes_input:
        node_by_label[str(n["label"])] = n
    for tri in triangles:
        for n in tri["nodes"]:
            node_by_label[str(n["label"])] = n

    active_labels = {str(n["label"]) for tri in triangles for n in tri["nodes"]}
    active_nodes = []
    for label, n in node_by_label.items():
        if node_family_filter_10(n) == "M" or label in active_labels:
            active_nodes.append(n)
    return active_nodes


def get_result_by_mast_filter_10(results_obj, mast_idx):
    return results_obj[mast_idx]


# =========================================================
# 2) GEOMETRÍA DE ÁREA EN PLANTA XY
# =========================================================

def polygon_area_signed_xy_filter_10(poly):
    P = np.asarray(poly, dtype=float)
    if len(P) < 3:
        return 0.0
    x = P[:, 0]
    y = P[:, 1]
    return 0.5 * float(np.dot(x, np.roll(y, -1)) - np.dot(y, np.roll(x, -1)))


def polygon_area_xy_filter_10(poly):
    return abs(polygon_area_signed_xy_filter_10(poly))


def triangle_polygon_xy_filter_10(tri_data):
    return [node_xy_filter_10(n) for n in decorate_triangle_type_filter_10(tri_data)["nodes"]]


def ensure_ccw_polygon_filter_10(poly):
    P = np.asarray(poly, dtype=float)
    if polygon_area_signed_xy_filter_10(P) < 0:
        P = P[::-1].copy()
    return P


def line_intersection_2d_filter_10(P1, P2, A, B, tol=1e-12):
    P1 = np.asarray(P1, dtype=float)
    P2 = np.asarray(P2, dtype=float)
    A = np.asarray(A, dtype=float)
    B = np.asarray(B, dtype=float)
    r = P2 - P1
    s = B - A
    den = r[0]*s[1] - r[1]*s[0]
    if abs(den) <= tol:
        return P2.copy()
    qmp = A - P1
    t = (qmp[0]*s[1] - qmp[1]*s[0]) / den
    return P1 + t*r


def clip_polygon_by_edge_filter_10(subject_polygon, A, B, tol=1e-9):
    subject = [np.asarray(p, dtype=float) for p in subject_polygon]
    if len(subject) == 0:
        return []

    A = np.asarray(A, dtype=float)
    B = np.asarray(B, dtype=float)
    edge_vec = B - A

    def inside(P):
        return (edge_vec[0]*(P[1] - A[1]) - edge_vec[1]*(P[0] - A[0])) >= -tol

    output = []
    S = subject[-1]
    S_inside = inside(S)

    for E in subject:
        E_inside = inside(E)
        if E_inside:
            if not S_inside:
                output.append(line_intersection_2d_filter_10(S, E, A, B, tol=tol))
            output.append(E)
        elif S_inside:
            output.append(line_intersection_2d_filter_10(S, E, A, B, tol=tol))
        S = E
        S_inside = E_inside

    return output


def convex_polygon_intersection_filter_10(poly_subject, poly_clip, tol=1e-9):
    subject = ensure_ccw_polygon_filter_10(poly_subject)
    clip = ensure_ccw_polygon_filter_10(poly_clip)
    output = [p for p in subject]
    for i in range(len(clip)):
        output = clip_polygon_by_edge_filter_10(output, clip[i], clip[(i + 1) % len(clip)], tol=tol)
        if len(output) == 0:
            return []
    return output


def triangle_overlap_area_xy_filter_10(tri_a, tri_b, tol=1e-9):
    poly_a = triangle_polygon_xy_filter_10(tri_a)
    poly_b = triangle_polygon_xy_filter_10(tri_b)
    area_a = polygon_area_xy_filter_10(poly_a)
    area_b = polygon_area_xy_filter_10(poly_b)

    if area_a <= XY_AREA_ABS_TOL_10 or area_b <= XY_AREA_ABS_TOL_10:
        return {
            "overlap_area": 0.0,
            "area_a": float(area_a),
            "area_b": float(area_b),
            "ratio_a": 0.0,
            "ratio_b": 0.0,
            "intersection_polygon": [],
        }

    inter_poly = convex_polygon_intersection_filter_10(poly_a, poly_b, tol=tol)
    overlap_area = polygon_area_xy_filter_10(inter_poly)
    return {
        "overlap_area": float(overlap_area),
        "area_a": float(area_a),
        "area_b": float(area_b),
        "ratio_a": float(overlap_area / max(area_a, XY_AREA_ABS_TOL_10)),
        "ratio_b": float(overlap_area / max(area_b, XY_AREA_ABS_TOL_10)),
        "intersection_polygon": inter_poly,
    }


def is_area_invasion_filter_10(overlap_record):
    overlap_area = float(overlap_record.get("overlap_area", 0.0))
    ratio_a = float(overlap_record.get("ratio_a", 0.0))
    ratio_b = float(overlap_record.get("ratio_b", 0.0))
    return (
        overlap_area > XY_AREA_ABS_TOL_10
        and ratio_a >= AREA_INVASION_MIN_RATIO_CANDIDATE_10
        and ratio_b >= AREA_INVASION_MIN_RATIO_NNM_10
    )


# =========================================================
# 3) EXCEPCIÓN ESTRUCTURAL PARA M-M-N
# =========================================================

def segment_vector_and_length_filter_10(edge_rec):
    v = np.asarray(edge_rec["p2"], dtype=float) - np.asarray(edge_rec["p1"], dtype=float)
    return v, float(np.linalg.norm(v))


def segments_parallel_equal_length_filter_10(edge_a, edge_b):
    va, La = segment_vector_and_length_filter_10(edge_a)
    vb, Lb = segment_vector_and_length_filter_10(edge_b)

    if La <= SEGMENT_MIN_LENGTH_XY_10 or Lb <= SEGMENT_MIN_LENGTH_XY_10:
        return False, {"reason": "segment_too_short", "length_a": La, "length_b": Lb}

    cross_norm = abs(va[0]*vb[1] - va[1]*vb[0]) / max(La*Lb, SEGMENT_MIN_LENGTH_XY_10)
    dot_abs = abs(float(np.dot(va, vb))) / max(La*Lb, SEGMENT_MIN_LENGTH_XY_10)
    length_rel_error = abs(La - Lb) / max(La, Lb, SEGMENT_MIN_LENGTH_XY_10)

    parallel_ok = cross_norm <= PARALLEL_CROSS_TOL_10 and abs(1.0 - dot_abs) <= PARALLEL_DOT_TOL_10
    length_ok = length_rel_error <= EQUAL_LENGTH_REL_TOL_10
    collinear_ok = True
    collinear_distance = None

    if REQUIRE_COLLINEAR_MM_NN_FOR_PROTECTION_10:
        A = np.asarray(edge_a["p1"], dtype=float)
        B = np.asarray(edge_a["p2"], dtype=float)
        C = np.asarray(edge_b["p1"], dtype=float)
        D = np.asarray(edge_b["p2"], dtype=float)
        v = B - A
        Lv = float(np.linalg.norm(v))
        if Lv <= SEGMENT_MIN_LENGTH_XY_10:
            collinear_ok = False
            collinear_distance = np.inf
        else:
            def d_line(P):
                return abs(v[0]*(P[1] - A[1]) - v[1]*(P[0] - A[0])) / Lv
            collinear_distance = max(float(d_line(C)), float(d_line(D)))
            collinear_ok = collinear_distance <= COLLINEAR_DISTANCE_TOL_10

    ok = bool(parallel_ok and length_ok and collinear_ok)
    return ok, {
        "reason": "ok" if ok else "not_parallel_equal_length",
        "length_a": La,
        "length_b": Lb,
        "cross_norm": float(cross_norm),
        "dot_abs": float(dot_abs),
        "length_rel_error": float(length_rel_error),
        "parallel_ok": bool(parallel_ok),
        "length_ok": bool(length_ok),
        "collinear_required": bool(REQUIRE_COLLINEAR_MM_NN_FOR_PROTECTION_10),
        "collinear_ok": bool(collinear_ok),
        "collinear_distance": collinear_distance,
    }


def build_nnm_reference_records_filter_10(nnm_triangles):
    records = []
    for idx, tri in enumerate(nnm_triangles):
        tri_ext = decorate_triangle_type_filter_10(tri)
        edge_records = []
        for edge_idx, (a, b) in enumerate(triangle_edges_filter_10(tri_ext)):
            a_label = str(a["label"])
            b_label = str(b["label"])
            edge_records.append({
                "edge_idx": edge_idx,
                "nodes": (a, b),
                "labels": (a_label, b_label),
                "key": edge_label_key_filter_10(a_label, b_label),
                "families": (node_family_filter_10(a), node_family_filter_10(b)),
                "p1": node_xy_filter_10(a),
                "p2": node_xy_filter_10(b),
            })
        nn_edge = get_nnm_nn_edge_filter_10(tri_ext)
        records.append({
            "nnm_index": idx,
            "tri": tri_ext,
            "labels": triangle_labels_filter_10(tri_ext),
            "labels_fmt": format_labels_filter_10(triangle_labels_filter_10(tri_ext)),
            "edges": edge_records,
            "edge_keys": {rec["key"] for rec in edge_records},
            "nn_edge": nn_edge,
            "nn_key": None if nn_edge is None else nn_edge["key"],
        })
    return records


def mmn_parallel_shared_nn_protection_filter_10(mmn_tri, nnm_reference_records):
    tri_ext = decorate_triangle_type_filter_10(mmn_tri)
    if tri_ext["triangle_type"] != "M-M-N":
        return False, {"protected": False, "reason": "not_mmn"}

    mm_edge = get_mmn_mm_edge_filter_10(tri_ext)
    if mm_edge is None:
        return False, {"protected": False, "reason": "mm_edge_not_found"}

    mmn_edges = []
    for edge_idx, (a, b) in enumerate(triangle_edges_filter_10(tri_ext)):
        a_label = str(a["label"])
        b_label = str(b["label"])
        mmn_edges.append({
            "edge_idx": edge_idx,
            "nodes": (a, b),
            "labels": (a_label, b_label),
            "key": edge_label_key_filter_10(a_label, b_label),
            "families": (node_family_filter_10(a), node_family_filter_10(b)),
        })

    shared_records = []
    for mmn_edge in mmn_edges:
        for nnm_rec in nnm_reference_records:
            if mmn_edge["key"] in nnm_rec["edge_keys"]:
                shared_records.append({
                    "mmn_edge_idx": mmn_edge["edge_idx"],
                    "mmn_edge_key": mmn_edge["key"],
                    "mmn_edge_labels": mmn_edge["labels"],
                    "mmn_edge_families": mmn_edge["families"],
                    "nnm_index": nnm_rec["nnm_index"],
                    "nnm_labels": nnm_rec["labels"],
                    "nnm_labels_fmt": nnm_rec["labels_fmt"],
                    "nn_key": nnm_rec["nn_key"],
                    "nn_edge": nnm_rec["nn_edge"],
                })

    for i in range(len(shared_records)):
        rec_i = shared_records[i]
        for j in range(i + 1, len(shared_records)):
            rec_j = shared_records[j]

            # Dos aristas distintas del MMN.
            if rec_i["mmn_edge_key"] == rec_j["mmn_edge_key"]:
                continue

            # Dos NNM distintos.
            if rec_i["nnm_index"] == rec_j["nnm_index"]:
                continue

            # Ambos NNM deben compartir el mismo segmento NN.
            if rec_i["nn_key"] is None or rec_i["nn_key"] != rec_j["nn_key"]:
                continue

            nn_edge = rec_i["nn_edge"]
            if nn_edge is None:
                continue

            parallel_ok, parallel_info = segments_parallel_equal_length_filter_10(mm_edge, nn_edge)
            if not parallel_ok:
                continue

            return True, {
                "protected": True,
                "reason": (
                    "MMN protegido: comparte dos aristas con dos NNM que comparten el mismo segmento NN; "
                    "además MM es paralelo/alineado y de igual longitud al NN compartido."
                ),
                "mmn_labels": triangle_labels_filter_10(tri_ext),
                "mmn_labels_fmt": format_labels_filter_10(triangle_labels_filter_10(tri_ext)),
                "mm_edge_key": mm_edge["key"],
                "mm_edge_labels": mm_edge["labels"],
                "shared_edge_1": rec_i,
                "shared_edge_2": rec_j,
                "shared_nn_key": rec_i["nn_key"],
                "shared_nn_labels": nn_edge["labels"],
                "parallel_info": parallel_info,
            }

    return False, {
        "protected": False,
        "reason": "no_pair_of_shared_edges_with_same_nn_and_parallel_mm",
        "mmn_labels": triangle_labels_filter_10(tri_ext),
        "mmn_labels_fmt": format_labels_filter_10(triangle_labels_filter_10(tri_ext)),
        "mm_edge_key": mm_edge["key"],
        "mm_edge_labels": mm_edge["labels"],
        "shared_records": shared_records,
    }


# =========================================================
# 4) FILTRO PRINCIPAL
# =========================================================

def triangle_area_invasion_records_against_nnm_filter_10(tri_ext, nnm_reference_records, geom_tol=1e-9):
    records = []
    tri_labels = triangle_labels_filter_10(tri_ext)
    tri_labels_fmt = format_labels_filter_10(tri_labels)

    for nnm_rec in nnm_reference_records:
        overlap = triangle_overlap_area_xy_filter_10(tri_ext, nnm_rec["tri"], tol=geom_tol)
        if not is_area_invasion_filter_10(overlap):
            continue

        records.append({
            "candidate_triangle_labels": tri_labels,
            "candidate_triangle_labels_fmt": tri_labels_fmt,
            "candidate_triangle_type": tri_ext["triangle_type"],
            "nnm_index": nnm_rec["nnm_index"],
            "nnm_triangle_labels": nnm_rec["labels"],
            "nnm_triangle_labels_fmt": nnm_rec["labels_fmt"],
            "overlap_area": float(overlap["overlap_area"]),
            "candidate_area": float(overlap["area_a"]),
            "nnm_area": float(overlap["area_b"]),
            "overlap_ratio_candidate": float(overlap["ratio_a"]),
            "overlap_ratio_nnm": float(overlap["ratio_b"]),
            "intersection_polygon": overlap["intersection_polygon"],
            "reason": "Invasión de área en planta XY contra N-N-M.",
        })
    return records


def filter_mmm_mmn_by_area_invasion_nnm_10(triangles, tri_nodes, geom_tol=1e-9):
    decorated_triangles = [decorate_triangle_type_filter_10(tri) for tri in triangles]
    nnm_reference_triangles = [tri for tri in decorated_triangles if tri["triangle_type"] == "N-N-M"]
    nnm_reference_records = build_nnm_reference_records_filter_10(nnm_reference_triangles)

    kept = []
    removed = []
    area_invasion_log = []
    protection_log = []
    protected_mmn = []

    for tri_ext in decorated_triangles:
        tri_type = tri_ext["triangle_type"]

        if tri_type not in {"M-M-M", "M-M-N"}:
            tri_ext["kept_reason_filter10"] = (
                f"{tri_type} conservado directamente en Filtro 10. "
                "El criterio de invasión de área solo evalúa M-M-M y M-M-N contra N-N-M."
            )
            kept.append(tri_ext)
            continue

        invasion_records = triangle_area_invasion_records_against_nnm_filter_10(
            tri_ext=tri_ext,
            nnm_reference_records=nnm_reference_records,
            geom_tol=geom_tol,
        )

        tri_ext["area_invasion_nnm_records_10"] = invasion_records
        tri_ext["n_area_invasions_nnm_10"] = len(invasion_records)

        if not invasion_records:
            tri_ext["kept_reason_filter10"] = f"{tri_type} conservado porque no invade en área XY ningún N-N-M."
            kept.append(tri_ext)
            continue

        if tri_type == "M-M-N":
            protected, protection_info = mmn_parallel_shared_nn_protection_filter_10(
                mmn_tri=tri_ext,
                nnm_reference_records=nnm_reference_records,
            )
            protection_log.append({
                **protection_info,
                "candidate_labels": triangle_labels_filter_10(tri_ext),
                "candidate_labels_fmt": format_labels_filter_10(triangle_labels_filter_10(tri_ext)),
                "n_area_invasions": len(invasion_records),
            })

            if protected:
                tri_ext["kept_reason_filter10"] = protection_info["reason"]
                tri_ext["mmn_parallel_shared_nn_protection_10"] = protection_info
                tri_ext["protected_by_parallel_shared_nn_10"] = True
                protected_mmn.append(tri_ext)
                kept.append(tri_ext)
                continue

        tri_ext["removed_reason"] = (
            f"{tri_type} eliminado porque invade en área XY uno o más triángulos N-N-M. "
            "No aplica excepción estructural de M-M-N."
        )
        tri_ext["removed_by_filter10_stage"] = "area_invasion_with_nnm"
        removed.append(tri_ext)
        area_invasion_log.extend(invasion_records)

    tri_nodes_after = build_active_tri_nodes_after_filter_10(tri_nodes, kept)
    return (
        kept,
        removed,
        tri_nodes_after,
        area_invasion_log,
        protection_log,
        protected_mmn,
        nnm_reference_triangles,
        nnm_reference_records,
    )


# =========================================================
# 5) GUARDAS Y GRÁFICA
