def guard_wire_segments_from_inputs_filter_10(masts, guard_wire_inputs=None):
    segments = []
    if guard_wire_inputs is None:
        return segments
    for k, gw in enumerate(guard_wire_inputs):
        if isinstance(gw, dict):
            i = int(gw["i"])
            j = int(gw["j"])
        else:
            i = int(gw[0])
            j = int(gw[1])
        mi = masts[i]
        mj = masts[j]
        p1 = np.array([mi.x, mi.y, mi.h], dtype=float)
        p2 = np.array([mj.x, mj.y, mj.h], dtype=float)
        segments.append({
            "guard_idx": k,
            "label_a": f"M{i}",
            "label_b": f"M{j}",
            "labels": (f"M{i}", f"M{j}"),
            "p1": p1,
            "p2": p2,
            "p1_xy": p1[:2],
            "p2_xy": p2[:2],
        })
    return segments


def triangle_color_filter_10(tri_type):
    tri_type = normalize_triangle_type_filter_10(tri_type)
    if tri_type == "M-M-M":
        return "gray"
    if tri_type == "M-M-Q":
        return "red"
    if tri_type == "N-N-M":
        return "green"
    if tri_type == "M-M-N":
        return "purple"
    return "black"


def plot_guard_segments_filter_10(fig, guard_segments):
    if not guard_segments:
        return
    x_vals, y_vals, z_vals, text_vals = [], [], [], []
    for guard in guard_segments:
        p1 = guard["p1"]
        p2 = guard["p2"]
        hover_txt = f"Guarda {guard['label_a']} - {guard['label_b']}"
        x_vals.extend([p1[0], p2[0], None])
        y_vals.extend([p1[1], p2[1], None])
        z_vals.extend([p1[2], p2[2], None])
        text_vals.extend([hover_txt, hover_txt, None])
    fig.add_trace(go.Scatter3d(
        x=x_vals, y=y_vals, z=z_vals,
        mode="lines",
        line=dict(color="darkgreen", width=GUARD_LINE_WIDTH_10),
        name="Guardas",
        hoverinfo="text",
        text=text_vals,
        showlegend=True,
    ))


def add_triangle_edges_grouped_by_type_filter_10(fig, triangles):
    type_order = ["M-M-M", "M-M-Q", "N-N-M", "M-M-N"]
    grouped = {t: {"x": [], "y": [], "z": [], "text": []} for t in type_order}
    other = {"x": [], "y": [], "z": [], "text": []}

    order = []
    for t in ["M-M-M", "M-M-Q", "M-M-N", "N-N-M"]:
        order.extend([tri for tri in triangles if decorate_triangle_type_filter_10(tri)["triangle_type"] == t])
    order.extend([tri for tri in triangles if decorate_triangle_type_filter_10(tri)["triangle_type"] not in type_order])

    for tri_data in order:
        tri_ext = decorate_triangle_type_filter_10(tri_data)
        tri_type = tri_ext["triangle_type"]
        target = grouped.get(tri_type, other)
        n1, n2, n3 = tri_ext["nodes"]
        labels_fmt = format_labels_filter_10(triangle_labels_filter_10(tri_ext))
        for a, b in [(n1, n2), (n2, n3), (n3, n1)]:
            target["x"].extend([a["x"], b["x"], None])
            target["y"].extend([a["y"], b["y"], None])
            target["z"].extend([a["z"], b["z"], None])
            target["text"].extend([
                f"Tipo: {tri_type}<br>Triángulo: {labels_fmt}<br>Arista: {a.get('label', '')}-{b.get('label', '')}<br>{tri_ext.get('kept_reason_filter10', '')}",
                f"Tipo: {tri_type}<br>Triángulo: {labels_fmt}<br>Arista: {a.get('label', '')}-{b.get('label', '')}<br>{tri_ext.get('kept_reason_filter10', '')}",
                None,
            ])

    names = {
        "M-M-M": "Triángulos MMM",
        "M-M-Q": "Triángulos MMQ",
        "N-N-M": "Triángulos NNM",
        "M-M-N": "Triángulos MMN",
    }
    for tri_type in type_order:
        data = grouped[tri_type]
        if not data["x"]:
            continue
        fig.add_trace(go.Scatter3d(
            x=data["x"], y=data["y"], z=data["z"],
            mode="lines",
            line=dict(color=triangle_color_filter_10(tri_type), width=TRIANGLE_LINE_WIDTH_10),
            name=names.get(tri_type, tri_type),
            hoverinfo="text",
            text=data["text"],
            showlegend=True,
        ))
    if other["x"]:
        fig.add_trace(go.Scatter3d(
            x=other["x"], y=other["y"], z=other["z"],
            mode="lines",
            line=dict(color="black", width=TRIANGLE_LINE_WIDTH_10),
            name="Otros triángulos",
            hoverinfo="text",
            text=other["text"],
            showlegend=True,
        ))


