def add_single_mast_reference_filter_10(fig, masts, results, sphere_radius):
    if results is None:
        return
    if "effective_radius" not in globals():
        print("ADVERTENCIA: no existe effective_radius; no se dibuja referencia de mástil solo.")
        return
    for i, mast in enumerate(masts):
        try:
            ai = effective_radius(mast.h, sphere_radius)
            useful_intervals = get_result_by_mast_filter_10(results, i)["useful_intervals"]
            for th1, th2 in useful_intervals:
                theta = np.linspace(th1, th2, 80)
                r = np.linspace(0.0, ai, 20)
                TH, RR = np.meshgrid(theta, r, indexing="xy")
                X = mast.x + RR * np.cos(TH)
                Y = mast.y + RR * np.sin(TH)
                Z = np.zeros_like(X)
                fig.add_trace(go.Surface(
                    x=X, y=Y, z=Z,
                    showscale=False,
                    opacity=0.10,
                    hoverinfo="skip",
                    name=f"Capa mástil solo M{i}",
                    showlegend=False,
                ))
        except Exception:
            pass


def add_ground_filter_10(fig, tri_nodes):
    xy = np.array([[n["x"], n["y"]] for n in tri_nodes], dtype=float)
    if len(xy) > 0:
        xmin, ymin = xy.min(axis=0) - 5
        xmax, ymax = xy.max(axis=0) + 5
    else:
        xmin, ymin, xmax, ymax = -5, -5, 5, 5
    Xg, Yg = np.meshgrid(np.linspace(xmin, xmax, 2), np.linspace(ymin, ymax, 2))
    fig.add_trace(go.Surface(
        x=Xg, y=Yg, z=np.zeros_like(Xg),
        opacity=0.08,
        showscale=False,
        hoverinfo="skip",
        name="Suelo",
        showlegend=False,
    ))


