GUARD_LENGTH_REL_TOL_11      = 1e-5
THREE_GUARD_REQUIRE_END_LENGTH_EQUAL_11 = False


# =========================================================
# 1) TIPOS DE NODOS Y TRIÁNGULOS
# =========================================================

def node_family_filter_11(node):
    raw = str(node.get("type", "")).strip()
    lbl = str(node.get("label", "")).strip()
    if raw in {"M", "mast", "mast_top"} or lbl.startswith("M"):
        return "M"
    if raw == "N" or raw.startswith("auxiliary_N") or lbl.startswith("N"):
        return "N"
    if raw == "Q" or lbl.startswith("Q"):
        return "Q"
    return raw


def normalize_triangle_type_filter_11(t):
    if t is None:
        return None
    raw = str(t).strip().upper().replace("_", "-")
    m = {"MMM":"M-M-M","MMN":"M-M-N","NNM":"N-N-M","MMQ":"M-M-Q",
         "MQQ":"M-Q-Q","QQQ":"Q-Q-Q","MNQ":"M-N-Q","NNN":"N-N-N","NNQ":"N-N-Q"}
    return m.get(raw.replace("-",""), raw)


def compact_triangle_type_filter_11(t):
    t = normalize_triangle_type_filter_11(t)
    m = {"M-M-M":"MMM","M-M-N":"MMN","N-N-M":"NNM","M-M-Q":"MMQ",
         "M-Q-Q":"MQQ","Q-Q-Q":"QQQ","M-N-Q":"MNQ","N-N-N":"NNN","N-N-Q":"NNQ"}
    return m.get(t, t)


def classify_triangle_type_filter_11(tri_data):
    fams = [node_family_filter_11(n) for n in tri_data.get("nodes", [])]
    nM, nN, nQ = fams.count("M"), fams.count("N"), fams.count("Q")
    if nM==3: return "M-M-M"
    if nM==2 and nN==1: return "M-M-N"
    if nN==2 and nM==1: return "N-N-M"
    if nM==2 and nQ==1: return "M-M-Q"
    if nM==1 and nQ==2: return "M-Q-Q"
    if nQ==3: return "Q-Q-Q"
    if nM==1 and nN==1 and nQ==1: return "M-N-Q"
    if nN==3: return "N-N-N"
    if nN==2 and nQ==1: return "N-N-Q"
    return "UNKNOWN"


def decorate_triangle_type_filter_11(tri):
    e = dict(tri)
    raw = e.get("triangle_type", e.get("type", None))
    t = normalize_triangle_type_filter_11(raw)
    if t is None or t == "UNKNOWN":
        t = classify_triangle_type_filter_11(e)
    e["triangle_type"] = t
    e["type"] = compact_triangle_type_filter_11(t)
    return e


def triangle_labels_filter_11(tri_data):
    if "labels" in tri_data:
        return tri_data["labels"]
    return tuple(str(n.get("label","")) for n in tri_data.get("nodes",[]))


def format_labels_filter_11(labels):
    if isinstance(labels,(tuple,list)):
        return "-".join(str(x) for x in labels)
    return str(labels)


def candidate_can_compete_filter_11(t):
    return t in {"M-M-M","M-M-N"}


def fixed_surface_type_filter_11(t):
    return t in {"M-M-Q","N-N-M"}


def get_nodes_by_family_filter_11(tri):
    e = decorate_triangle_type_filter_11(tri)
    out = {"M":[],"N":[],"Q":[],"OTHER":[]}
    for n in e.get("nodes",[]):
        f = node_family_filter_11(n)
        out[f if f in out else "OTHER"].append(n)
    return out


def get_mmn_mm_key_filter_11(tri):
    e = decorate_triangle_type_filter_11(tri)
    if e["triangle_type"] != "M-M-N":
        return None
    ms = get_nodes_by_family_filter_11(e)["M"]
    if len(ms) != 2:
        return None
    return tuple(sorted([ms[0]["label"], ms[1]["label"]]))


def triangle_contains_mn_key_filter_11(tri, mn_key):
    """True si el triángulo contiene ambos nodos del par mn_key como vértices."""
    e = decorate_triangle_type_filter_11(tri)
    labels = {str(n["label"]) for n in e.get("nodes",[])}
    return mn_key[0] in labels and mn_key[1] in labels


# =========================================================
# 2) GEOMETRÍA BÁSICA
# =========================================================

def node_xyz_filter_11(node):
    return np.array([float(node["x"]), float(node["y"]), float(node["z"])], dtype=float)


def node_xy_filter_11(node):
    return np.array([float(node["x"]), float(node["y"])], dtype=float)


def triangle_points_xyz_filter_11(tri_data):
    e = decorate_triangle_type_filter_11(tri_data)
    return [node_xyz_filter_11(n) for n in e["nodes"]]


def triangle_area_xy_filter_11(tri_data):
    e = decorate_triangle_type_filter_11(tri_data)
    n1,n2,n3 = e["nodes"]
    x1,y1 = float(n1["x"]),float(n1["y"])
    x2,y2 = float(n2["x"]),float(n2["y"])
    x3,y3 = float(n3["x"]),float(n3["y"])
    return 0.5*abs((x2-x1)*(y3-y1)-(y2-y1)*(x3-x1))


def point_in_triangle_xy_filter_11(px,py,n1,n2,n3,tol=1e-9):
    x1,y1 = float(n1["x"]),float(n1["y"])
    x2,y2 = float(n2["x"]),float(n2["y"])
    x3,y3 = float(n3["x"]),float(n3["y"])
    d = (y2-y3)*(x1-x3)+(x3-x2)*(y1-y3)
    if abs(d)<tol: return False
    l1 = ((y2-y3)*(px-x3)+(x3-x2)*(py-y3))/d
    l2 = ((y3-y1)*(px-x3)+(x1-x3)*(py-y3))/d
    return l1>=-tol and l2>=-tol and (1-l1-l2)>=-tol


def sample_points_triangle_interior_filter_11(tri_data, divisions=14):
    e = decorate_triangle_type_filter_11(tri_data)
    n1,n2,n3 = e["nodes"]
    x1,y1=float(n1["x"]),float(n1["y"])
    x2,y2=float(n2["x"]),float(n2["y"])
    x3,y3=float(n3["x"]),float(n3["y"])
    pts=[]
    for i in range(1,divisions):
        for j in range(1,divisions-i):
            a,b=i/divisions,j/divisions
            c=1-a-b
            if c<=0: continue
            pts.append({"x":float(a*x1+b*x2+c*x3),"y":float(a*y1+b*y2+c*y3)})
    return pts


def points_inside_triangle_count_filter_11(pts, tri_data):
    e = decorate_triangle_type_filter_11(tri_data)
    n1,n2,n3 = e["nodes"]
    return sum(1 for p in pts
               if point_in_triangle_xy_filter_11(p["x"],p["y"],n1,n2,n3,tol=XY_GEOM_TOL_11))


def triangle_pair_overlap_samples_filter_11(ta,tb,divisions=18,
                                             min_common_points=1,min_overlap_ratio=0.01):
    ta=decorate_triangle_type_filter_11(ta)
    tb=decorate_triangle_type_filter_11(tb)
    empty={"overlaps":False,"common_a_in_b":0,"common_b_in_a":0,"overlap_ratio":0.0}
    if triangle_area_xy_filter_11(ta)<=XY_AREA_TOL_11: return empty
    if triangle_area_xy_filter_11(tb)<=XY_AREA_TOL_11: return empty
    sa=sample_points_triangle_interior_filter_11(ta,divisions=divisions)
    sb=sample_points_triangle_interior_filter_11(tb,divisions=divisions)
    if not sa or not sb: return empty
    a_in_b=points_inside_triangle_count_filter_11(sa,tb)
    b_in_a=points_inside_triangle_count_filter_11(sb,ta)
    denom=max(1,min(len(sa),len(sb)))
    ratio=max(a_in_b,b_in_a)/denom
    overlaps=max(a_in_b,b_in_a)>=min_common_points and ratio>=min_overlap_ratio
    return {"overlaps":bool(overlaps),"common_a_in_b":int(a_in_b),
            "common_b_in_a":int(b_in_a),"overlap_ratio":float(ratio)}


def triangle_shape_metrics_filter_11(tri_data):
    p1,p2,p3=triangle_points_xyz_filter_11(tri_data)
    edges=[float(np.linalg.norm(p2-p1)),float(np.linalg.norm(p3-p2)),
           float(np.linalg.norm(p1-p3))]
    mn,mx=min(edges),max(edges)
    er=0.0 if mx<=1e-15 else mn/mx
    a,b,c=edges[1],edges[2],edges[0]
    angs=[]
    for u,v,w in [(b,c,a),(a,c,b),(a,b,c)]:
        den=2*u*v
        if den<=1e-15: angs.append(0.0)
        else: angs.append(float(np.degrees(np.arccos(float(np.clip((u*u+v*v-w*w)/den,-1,1))))))
    mina=min(angs)
    aq=max(0.0,min(1.0,mina/60.0))
    eq=max(0.0,min(1.0,er))
    areaq=0.0 if triangle_area_xy_filter_11(tri_data)<=XY_AREA_TOL_11 else 1.0
    sq=0.45*aq+0.45*eq+0.10*areaq
    return {"edge_lengths":edges,"min_edge":mn,"max_edge":mx,"edge_ratio":er,
            "angles_deg":angs,"min_angle_deg":mina,"angle_quality":aq,
            "edge_quality":eq,"area_quality":areaq,"shape_quality":sq}


# =========================================================
# 3) SOPORTE FÍSICO DE ESFERA
# =========================================================

def circumcenter_3d_filter_11(p1,p2,p3,tol=1e-12):
    p1,p2,p3=(np.asarray(x,dtype=float) for x in (p1,p2,p3))
    a,b=p2-p1,p3-p1
    n=np.cross(a,b); nn=float(np.linalg.norm(n))
    if nn<=tol: return None,None,None
    nu=n/nn
    A=np.vstack([2*a,2*b,nu])
    rhs=np.array([float(np.dot(p2,p2)-np.dot(p1,p1)),
                  float(np.dot(p3,p3)-np.dot(p1,p1)),
                  float(np.dot(nu,p1))],dtype=float)
    try: ctr=np.linalg.solve(A,rhs)
    except np.linalg.LinAlgError: return None,None,None
    return ctr,float(np.linalg.norm(ctr-p1)),nu


def z_lower_sphere_filter_11(center,radius,x,y,tol=1e-9):
    dx,dy=float(x)-float(center[0]),float(y)-float(center[1])
    rad=radius*radius-dx*dx-dy*dy
    if rad<-tol: return None,rad
    return float(center[2])-float(np.sqrt(max(0.0,rad))),rad


def choose_lower_branch_support_center_filter_11(p1,p2,p3,sr,cc,nu,cr):
    if cr>sr+SPHERE_SUPPORT_TOL_11: return None,[]
    off=float(np.sqrt(max(0.0,sr**2-cr**2)))
    recs=[]
    for idx,c in enumerate([cc+off*nu, cc-off*nu]):
        residuals,flags=[],[]
        for p in [p1,p2,p3]:
            zl,_=z_lower_sphere_filter_11(c,sr,p[0],p[1],tol=SPHERE_SUPPORT_TOL_11)
            if zl is None: residuals.append(np.inf); flags.append(False)
            else:
                res=abs(float(zl)-float(p[2]))
                residuals.append(float(res))
                flags.append(float(p[2])<=float(c[2])+SPHERE_SUPPORT_TOL_11
                              and res<=SPHERE_VERTEX_RESIDUAL_TOL_11)
        recs.append({"center_index":idx,"center":c,
                     "all_vertices_on_lower_branch":all(flags),
                     "max_vertex_residual":float(max(residuals)),
                     "mean_vertex_residual":float(np.mean(residuals))})
    recs.sort(key=lambda r:(0 if r["all_vertices_on_lower_branch"] else 1,
                             r["max_vertex_residual"],-float(r["center"][2])))
    return (recs[0] if recs else None),recs


def analyze_triangle_sphere_support_filter_11(tri_data,sphere_radius,sample_divisions=14):
    e=decorate_triangle_type_filter_11(tri_data)
    lbl=triangle_labels_filter_11(e); lf=format_labels_filter_11(lbl)
    p1,p2,p3=triangle_points_xyz_filter_11(e)
    axy=triangle_area_xy_filter_11(e); sh=triangle_shape_metrics_filter_11(e)
    gs=float(1000*sh["shape_quality"])
    res={"labels":lbl,"labels_fmt":lf,"triangle_type":e["triangle_type"],
         "area_xy":float(axy),"shape_metrics":sh,"sphere_exists":False,
         "lower_branch_valid":False,"physical_valid":False,"support_center":None,
         "circumcenter":None,"circumradius":None,"radius_margin":None,
         "sample_valid_ratio":0.0,"below_ground_ratio":1.0,
         "z_min":None,"z_mean":None,"z_max":None,
         "score":-1e9,"geometric_score":gs,"status":"not_evaluated","center_candidates":[]}
    if axy<=XY_AREA_TOL_11:
        res.update(status="degenerate_xy",score=-1e8+gs); return res
    cc,cr,nu=circumcenter_3d_filter_11(p1,p2,p3)
    if cc is None:
        res.update(status="degenerate_3d",score=-1e8+gs); return res
    res.update(circumcenter=cc,circumradius=float(cr),radius_margin=float(sphere_radius-cr))
    if cr>sphere_radius+SPHERE_SUPPORT_TOL_11:
        res.update(status="circumradius_greater_than_S",score=-1e6+gs); return res
    res["sphere_exists"]=True
    chosen,cands=choose_lower_branch_support_center_filter_11(p1,p2,p3,sphere_radius,cc,nu,cr)
    res["center_candidates"]=cands
    if chosen is None:
        res.update(status="no_center_candidate",score=-5e5+gs); return res
    ctr=chosen["center"]
    res.update(support_center=ctr,
               lower_branch_valid=bool(chosen["all_vertices_on_lower_branch"]),
               max_vertex_residual=float(chosen["max_vertex_residual"]),
               mean_vertex_residual=float(chosen["mean_vertex_residual"]))
    samps=sample_points_triangle_interior_filter_11(e,divisions=sample_divisions)
    zv,inv,bel=[],0,0
    for p in samps:
        zl,_=z_lower_sphere_filter_11(ctr,sphere_radius,p["x"],p["y"],tol=SPHERE_SUPPORT_TOL_11)
        if zl is None: inv+=1
        else:
            zv.append(float(zl))
            if zl<-SPHERE_SUPPORT_TOL_11: bel+=1
    tot,val=len(samps),len(zv)
    vr=val/tot if tot>0 else 0.0
    if val==0: br=1.0; zm=zmn=zmx=None
    else:
        br=bel/val; zm=float(np.min(zv)); zmn=float(np.mean(zv)); zmx=float(np.max(zv))
    res.update(sample_valid_ratio=float(vr),below_ground_ratio=float(br),
               z_min=zm,z_mean=zmn,z_max=zmx,
               invalid_sample_count=int(inv),valid_sample_count=int(val),
               total_sample_count=int(tot),below_ground_count=int(bel))
    Sn=max(float(sphere_radius),1.0)
    sc=(1000 if res["sphere_exists"] else -1000)+(2000 if res["lower_branch_valid"] else -500)
    sc+=250*vr-300*br+80*(0 if zmn is None else zmn/Sn)+80*(0 if zm is None else zm/Sn)
    sc+=20*max(0.0,float(sphere_radius-cr)/Sn)+20*sh["shape_quality"]
    res["score"]=float(sc)
    res["physical_valid"]=bool(res["sphere_exists"] and res["lower_branch_valid"] and vr>0)
    if not res["lower_branch_valid"]: res["status"]="sphere_exists_but_not_lower_branch"
    elif br>0.50: res["status"]="valid_but_mostly_below_ground"
    else: res["status"]="valid_lower_sphere_support"
    return res


# =========================================================
# 4) RESTRICCIÓN CONTRA FIJAS MMQ / NNM
# =========================================================

def candidate_overlaps_fixed_surface_filter_11(candidate_tri, fixed_triangles):
    logs=[]
    for ft in fixed_triangles:
        ov=triangle_pair_overlap_samples_filter_11(
            candidate_tri,ft,
            divisions=FIXED_OVERLAP_SAMPLE_DIVISIONS_11,
            min_common_points=FIXED_OVERLAP_MIN_POINTS_11,
            min_overlap_ratio=FIXED_OVERLAP_MIN_RATIO_11)
        if ov["overlaps"]:
            logs.append({"candidate":format_labels_filter_11(triangle_labels_filter_11(candidate_tri)),
                         "candidate_type":decorate_triangle_type_filter_11(candidate_tri)["triangle_type"],
                         "fixed":format_labels_filter_11(triangle_labels_filter_11(ft)),
                         "fixed_type":decorate_triangle_type_filter_11(ft)["triangle_type"],
                         "overlap_ratio":ov["overlap_ratio"],
                         "common_candidate_in_fixed":ov["common_a_in_b"],
                         "common_fixed_in_candidate":ov["common_b_in_a"]})
    return len(logs)>0, logs


# =========================================================
# 5) PROTECCIÓN DE SEGMENTOS M-N SIN RESPALDO N-N-M
# =========================================================

def get_mn_edges_from_nnm_filter_11(triangles):
    """
    Devuelve el conjunto de mn_keys (tuple sorted [M_label, N_label])
    que aparecen como arista en algún triángulo N-N-M.
    Un par (M,N) está protegido por N-N-M si ambos nodos son vértices
    de alguna N-N-M (y por tanto M-N es una arista de esa N-N-M).
    """
    edges = set()
    for tri in triangles:
        e = decorate_triangle_type_filter_11(tri)
        if e["triangle_type"] != "N-N-M":
            continue
        fams = get_nodes_by_family_filter_11(e)
        for m in fams["M"]:
            for n in fams["N"]:
                edges.add(tuple(sorted([str(m["label"]), str(n["label"])])))
    return edges


def segment_cosine_xy_filter_11(m_xy, n_xy, g1_xy, g2_xy):
    """Coseno absoluto entre el segmento M-N y la guarda g1-g2 en planta XY."""
    v_mn = np.asarray(n_xy,dtype=float) - np.asarray(m_xy,dtype=float)
    v_g  = np.asarray(g2_xy,dtype=float) - np.asarray(g1_xy,dtype=float)
    nm, ng = float(np.linalg.norm(v_mn)), float(np.linalg.norm(v_g))
    if nm <= XY_GEOM_TOL_11 or ng <= XY_GEOM_TOL_11:
        return None
    return float(abs(np.dot(v_mn, v_g) / (nm * ng)))


def count_perpendicular_guards_for_mn_filter_11(m_node, n_node, guard_segments):
    """Cuenta guardas perpendiculares al segmento M-N en XY."""
    if not guard_segments:
        return {"count":0,"labels":[],"cos_values":[]}
    m_xy = node_xy_filter_11(m_node)
    n_xy = node_xy_filter_11(n_node)
    labels, cos_values = [], []
    for g in guard_segments:
        p1 = np.asarray(g.get("p1",[]),dtype=float)
        p2 = np.asarray(g.get("p2",[]),dtype=float)
        if p1.size < 2 or p2.size < 2:
            continue
        cos_val = segment_cosine_xy_filter_11(m_xy, n_xy, p1[:2], p2[:2])
        if cos_val is None:
            continue
        if cos_val <= PROTECTED_MN_PERP_COS_TOL_11:
            labels.append(tuple(g.get("labels",(g.get("label_a","?"),g.get("label_b","?")))))
            cos_values.append(float(cos_val))
    return {"count":len(labels),"labels":labels,"cos_values":cos_values}


def build_protected_mn_requirements_filter_11(candidate_entries, fixed_entries, guard_segments):
    """
    Construye requisitos de conservación para segmentos M-N sin respaldo N-N-M.

    Regla: para cada par (M_label, N_label) tal que:
      - el segmento M-N es perpendicular a ≥ PROTECTED_MN_MIN_PERP_GUARDS_11 guardas
      - el par (M,N) NO aparece como arista en ningún triángulo N-N-M fijo
    se exige que al menos una M-M-N conservada tenga ese par como arista.

    Si M1-N y M2-N cumplen independientemente, son dos requisitos separados.
    """
    if not ENABLE_PROTECTED_MN_WITHOUT_NNM_11:
        return {}, {"enabled":False,"mn_edges_in_nnm":set(),"mn_keys_with_requirements":set()}

    fixed_triangles = [tri for _, tri in fixed_entries]
    mn_edges_in_nnm = get_mn_edges_from_nnm_filter_11(fixed_triangles)

    requirements = {}

    for idx, tri in candidate_entries:
        e = decorate_triangle_type_filter_11(tri)
        if e["triangle_type"] != "M-M-N":
            continue
        fams = get_nodes_by_family_filter_11(e)
        m_nodes, n_nodes = fams["M"], fams["N"]
        if len(m_nodes) != 2 or len(n_nodes) != 1:
            continue
        n_node = n_nodes[0]

        for m_node in m_nodes:
            mn_key = tuple(sorted([str(m_node["label"]), str(n_node["label"])]))

            # Ya protegido por una N-N-M → no necesita requisito
            if mn_key in mn_edges_in_nnm:
                continue

            perp = count_perpendicular_guards_for_mn_filter_11(m_node, n_node, guard_segments)
            if perp["count"] < PROTECTED_MN_MIN_PERP_GUARDS_11:
                continue

            if mn_key not in requirements:
                requirements[mn_key] = {
                    "requirement_key": mn_key,
                    "requirement_type": "protected_MN_segment_without_NNM",
                    "m_label": str(m_node["label"]),
                    "n_label": str(n_node["label"]),
                    "mn_key": mn_key,
                    "perpendicular_guard_count": int(perp["count"]),
                    "perpendicular_guard_labels": list(perp["labels"]),
                    "candidate_indices": set(),
                    "candidate_indices_in_component": [],
                    "reason": (
                        f"Segmento {mn_key[0]}-{mn_key[1]} perpendicular a "
                        f"{perp['count']} guardas sin respaldo N-N-M. "
                        "Debe conservarse en al menos una M-M-N."
                    ),
                }
            requirements[mn_key]["candidate_indices"].add(idx)

    debug = {
        "enabled": True,
        "mn_edges_in_nnm": set(mn_edges_in_nnm),
        "mn_keys_with_requirements": set(requirements.keys()),
    }
    return requirements, debug


def protected_requirements_for_component_filter_11(protected_requirements, component_indices):
    """Filtra requisitos al subconjunto con candidatos dentro del componente."""
    if not protected_requirements:
        return {}
    comp_set = set(component_indices)
    out = {}
    for key, req in protected_requirements.items():
        in_comp = sorted(req["candidate_indices"] & comp_set)
        if not in_comp:
            continue
        r = dict(req)
        r["candidate_indices_in_component"] = in_comp
        out[key] = r
    return out


def protected_requirements_satisfied_filter_11(subset_indices, protected_requirements):
    """Verifica que cada segmento M-N protegido tenga al menos una M-M-N seleccionada."""
    if not protected_requirements:
        return True, 0, 0, []
    sel = set(subset_indices)
    missing, satisfied = [], 0
    for req in protected_requirements.values():
        cands = set(req.get("candidate_indices_in_component",[]))
        if not cands:
            continue
        if sel & cands:
            satisfied += 1
        else:
            missing.append(req)
    total = satisfied + len(missing)
    return len(missing)==0, satisfied, total, missing


def triangle_is_only_candidate_for_any_protected_mn_filter_11(idx, protected_requirements):
    """True si idx es el único candidato (global) que satisface algún requisito M-N."""
    if not protected_requirements:
        return False
    for req in protected_requirements.values():
        if req["candidate_indices"] == {idx}:
            return True
    return False


# =========================================================
# 6) REDUCCIÓN DE MMN ALTERNATIVAS CON LA MISMA BASE M-M
# =========================================================

def reduce_mmn_same_mm_alternatives_filter_11(candidate_entries, analyses_by_idx,
                                               protected_requirements=None):
    if not ENABLE_MMN_SAME_MM_ALTERNATIVE_REDUCTION_11:
        return candidate_entries, set(), []

    by_mm = defaultdict(list)
    for idx, tri in candidate_entries:
        e = decorate_triangle_type_filter_11(tri)
        if e["triangle_type"] != "M-M-N":
            continue
        k = get_mmn_mm_key_filter_11(e)
        if k is not None:
            by_mm[k].append((idx, e))

    removed, logs = set(), []

    for mm_key, entries in by_mm.items():
        if len(entries) <= 1:
            continue

        adj = {idx: set() for idx,_ in entries}
        for ai,(ia,ta) in enumerate(entries):
            for bi,(ib,tb) in enumerate(entries[ai+1:],ai+1):
                ov = triangle_pair_overlap_samples_filter_11(
                    ta,tb,
                    divisions=PAIR_OVERLAP_SAMPLE_DIVISIONS_11,
                    min_common_points=PAIR_MIN_COMMON_POINTS_11,
                    min_overlap_ratio=MMN_ALTERNATIVE_MIN_OVERLAP_RATIO_11)
                if ov["overlaps"]:
                    adj[ia].add(ib); adj[ib].add(ia)

        visited = set()
        for start,_ in entries:
            if start in visited: continue
            stack=[start]; comp=[]
            visited.add(start)
            while stack:
                cur=stack.pop(); comp.append(cur)
                for nb in adj[cur]:
                    if nb not in visited:
                        visited.add(nb); stack.append(nb)
            if len(comp)<=1: continue

            by_i = {i:t for i,t in entries}
            ranked = []
            for i in comp:
                t=by_i[i]; an=analyses_by_idx.get(i,{})
                ranked.append({"idx":i,"labels":format_labels_filter_11(triangle_labels_filter_11(t)),
                                "physical_valid":bool(an.get("physical_valid",False)),
                                "score":float(an.get("score",-1e9)),
                                "geometric_score":float(an.get("geometric_score",0.0)),
                                "area":float(triangle_area_xy_filter_11(t))})
            ranked.sort(key=lambda r:(0 if r["physical_valid"] else 1,
                                      -r["score"],-r["geometric_score"],r["area"],r["idx"]))

            # No eliminar si es el único candidato global para algún segmento M-N protegido
            non_removable = {
                r["idx"] for r in ranked
                if triangle_is_only_candidate_for_any_protected_mn_filter_11(
                    r["idx"], protected_requirements)
            }

            removable = [r for r in ranked if r["idx"] not in non_removable]
            chosen = (removable[0] if removable else ranked[0])

            for r in ranked:
                if r["idx"] != chosen["idx"] and r["idx"] not in non_removable:
                    removed.add(r["idx"])

            logs.append({"mm_key":mm_key,"component_indices":sorted(comp),
                         "chosen_idx":chosen["idx"],"chosen_labels":chosen["labels"],
                         "removed_indices":sorted([r["idx"] for r in ranked if r["idx"] in removed]),
                         "protected_not_removed":sorted(non_removable),
                         "reason":"M-M-N alternativas misma base M-M reducidas a una (salvo respaldos únicos de M-N protegido).",
                         "ranking":ranked})

    reduced = [(idx,tri) for idx,tri in candidate_entries if idx not in removed]
    return reduced, removed, logs


# =========================================================
# 7) COMPONENTES DE SOLAPAMIENTO
# =========================================================

def build_mlike_overlap_components_filter_11(candidate_entries):
    adj = {idx: set() for idx,_ in candidate_entries}
    pair_logs = []
    for ai,(ia,ta) in enumerate(candidate_entries):
        for _,(ib,tb) in enumerate(candidate_entries[ai+1:]):
            ov = triangle_pair_overlap_samples_filter_11(
                ta,tb,
                divisions=PAIR_OVERLAP_SAMPLE_DIVISIONS_11,
                min_common_points=PAIR_MIN_COMMON_POINTS_11,
                min_overlap_ratio=PAIR_MIN_OVERLAP_RATIO_11)
            if ov["overlaps"]:
                adj[ia].add(ib); adj[ib].add(ia)
                pair_logs.append({"idx_a":ia,"idx_b":ib,
                                   "labels_a":triangle_labels_filter_11(ta),
                                   "labels_b":triangle_labels_filter_11(tb),
                                   "type_a":decorate_triangle_type_filter_11(ta)["triangle_type"],
                                   "type_b":decorate_triangle_type_filter_11(tb)["triangle_type"],
                                   "overlap_ratio":ov["overlap_ratio"]})
    comps, visited = [], set()
    for idx,_ in candidate_entries:
        if idx in visited: continue
        stack=[idx]; comp=[]
        visited.add(idx)
        while stack:
            cur=stack.pop(); comp.append(cur)
            for nb in adj[cur]:
                if nb not in visited:
                    visited.add(nb); stack.append(nb)
        comps.append(sorted(comp))
    return comps, adj, pair_logs


# =========================================================
# 8) EXCEPCIONES DE SOLAPE MMM (three_guard_chain / four_guard_rectangle)
# =========================================================

def _edge_key(a, b):
    return tuple(sorted([str(a), str(b)]))


def _guard_edges_from_inputs(guard_wire_inputs):
    edges = set()
    if not guard_wire_inputs:
        return edges
    for gw in guard_wire_inputs:
        try:
            if isinstance(gw, dict):
                if "label_a" in gw: a,b=str(gw["label_a"]),str(gw["label_b"])
                elif "labels" in gw: a,b=str(gw["labels"][0]),str(gw["labels"][1])
                else: a,b=f"M{int(gw['i'])}",f"M{int(gw['j'])}"
            else:
                a0,b0=gw[0],gw[1]
                a,b=(str(a0),str(b0)) if isinstance(a0,str) else (f"M{int(a0)}",f"M{int(b0)}")
            edges.add(_edge_key(a,b))
        except Exception: continue
    return edges


def _mast_node_by_label(tri_nodes, triangles, masts):
    d = {}
    for n in (tri_nodes or []):
        if isinstance(n,dict) and node_family_filter_11(n)=="M":
            d[str(n.get("label",""))]=n
    for tri in (triangles or []):
        for n in tri.get("nodes",[]):
            if isinstance(n,dict) and node_family_filter_11(n)=="M":
                d[str(n.get("label",""))]=n
    for i,m in enumerate(masts or []):
        lbl=f"M{i}"
        if lbl not in d:
            try: d[lbl]={"label":lbl,"type":"mast_top","x":float(m.x),"y":float(m.y),"z":float(m.h)}
            except Exception: pass
    return d


def _vec_xy(a, b, nbl):
    if a not in nbl or b not in nbl: return None,None
    A=np.array([float(nbl[a]["x"]),float(nbl[a]["y"])],dtype=float)
    B=np.array([float(nbl[b]["x"]),float(nbl[b]["y"])],dtype=float)
    v=B-A; L=float(np.linalg.norm(v))
    return (v,L) if L>XY_GEOM_TOL_11 else (None,None)


def _parallel(ea, eb, nbl, req_equal=False):
    va,La=_vec_xy(ea[0],ea[1],nbl)
    vb,Lb=_vec_xy(eb[0],eb[1],nbl)
    if va is None or vb is None: return False
    cross=abs(va[0]*vb[1]-va[1]*vb[0])/max(La*Lb,XY_GEOM_TOL_11)
    dot=abs(float(np.dot(va,vb)))/max(La*Lb,XY_GEOM_TOL_11)
    ok=cross<=GUARD_PARALLEL_CROSS_TOL_11 and abs(1-dot)<=GUARD_PARALLEL_CROSS_TOL_11
    if not ok: return False
    if req_equal: return abs(La-Lb)/max(La,Lb,XY_GEOM_TOL_11)<=GUARD_LENGTH_REL_TOL_11
    return True


def _perp(ea, eb, nbl):
    va,La=_vec_xy(ea[0],ea[1],nbl)
    vb,Lb=_vec_xy(eb[0],eb[1],nbl)
    if va is None or vb is None: return False
    return abs(float(np.dot(va,vb)))/max(La*Lb,XY_GEOM_TOL_11)<=GUARD_PERP_DOT_TOL_11


def _path_order(labels4, edges_sub):
    adj={l:[] for l in labels4}
    for a,b in edges_sub: adj[a].append(b); adj[b].append(a)
    if sorted(len(adj[l]) for l in labels4)!=[1,1,2,2]: return None
    start=[l for l in labels4 if len(adj[l])==1][0]
    order=[start]; prev=None; cur=start
    for _ in range(3):
        nxt=[nb for nb in adj[cur] if nb!=prev]
        if len(nxt)!=1: return None
        order.append(nxt[0]); prev,cur=cur,nxt[0]
    return order if len(set(order))==4 else None


def _cycle_order(labels4, edges_sub):
    adj={l:[] for l in labels4}
    for a,b in edges_sub: adj[a].append(b); adj[b].append(a)
    if any(len(adj[l])!=2 for l in labels4): return None
    start=labels4[0]; order=[start]; prev=None; cur=start
    for _ in range(3):
        nxt=[nb for nb in adj[cur] if nb!=prev]
        if not nxt: return None
        order.append(nxt[0]); prev,cur=cur,nxt[0]
    if len(set(order))!=4 or start not in adj[order[-1]]: return None
    return order


def detect_allowed_mmm_overlap_quad_records_filter_11(tri_nodes=None,triangles=None,
                                                       guard_wire_inputs=None,masts=None):
    nbl = _mast_node_by_label(tri_nodes, triangles, masts)
    guard_edges = _guard_edges_from_inputs(guard_wire_inputs)
    mast_labels = sorted(nbl.keys())
    records, seen = [], set()

    for labels4 in combinations(mast_labels, 4):
        ls4 = set(labels4)
        sub = [e for e in guard_edges if e[0] in ls4 and e[1] in ls4]

        # CASO A: three_guard_chain
        if ALLOW_MMM_OVERLAP_THREE_GUARD_CHAIN_11 and len(sub)==3:
            order = _path_order(list(labels4), sub)
            if order:
                e0=_edge_key(order[0],order[1])
                e1=_edge_key(order[1],order[2])
                e2=_edge_key(order[2],order[3])
                if (_parallel(e0,e2,nbl,req_equal=THREE_GUARD_REQUIRE_END_LENGTH_EQUAL_11)
                        and _perp(e0,e1,nbl) and _perp(e1,e2,nbl)):
                    key=("three_guard_chain",tuple(sorted(labels4)))
                    if key not in seen:
                        seen.add(key)
                        records.append({"case_type":"three_guard_chain",
                                        "quad_key":tuple(sorted(labels4)),
                                        "ordered_labels":list(order),
                                        "guard_edges":[e0,e1,e2],
                                        "reason":"Solape MMM permitido: tres guardas (2 paralelas + 1 perpendicular)."})

        # CASO B: four_guard_rectangle
        if ALLOW_MMM_OVERLAP_FOUR_GUARD_RECTANGLE_11 and len(sub)==4:
            order = _cycle_order(list(labels4), sub)
            if order:
                e01=_edge_key(order[0],order[1]); e12=_edge_key(order[1],order[2])
                e23=_edge_key(order[2],order[3]); e30=_edge_key(order[3],order[0])
                if (_parallel(e01,e23,nbl,req_equal=True)
                        and _parallel(e12,e30,nbl,req_equal=True)
                        and _perp(e01,e12,nbl) and _perp(e12,e23,nbl)
                        and _perp(e23,e30,nbl) and _perp(e30,e01,nbl)):
                    key=("four_guard_rectangle",tuple(sorted(labels4)))
                    if key not in seen:
                        seen.add(key)
                        records.append({"case_type":"four_guard_rectangle",
                                        "quad_key":tuple(sorted(labels4)),
                                        "ordered_labels":list(order),
                                        "guard_edges":[e01,e12,e23,e30],
                                        "reason":"Solape MMM permitido: cuatro guardas en cuadrado/rectángulo."})
    return records


def _mmm_mast_labels(tri, by_idx_decorated):
    e = by_idx_decorated if isinstance(by_idx_decorated, dict) else by_idx_decorated
    if e.get("triangle_type") != "M-M-M": return None
    lbls=[str(n["label"]) for n in e.get("nodes",[]) if node_family_filter_11(n)=="M"]
    return frozenset(lbls) if len(lbls)==3 else None


def build_allowed_mmm_overlap_context_for_component_filter_11(
        component_indices, decorated_triangles_by_idx,
        allowed_quad_records, pair_logs=None):
    """
    Construye el contexto de solape permitido para un componente.
    Usa pair_logs (ya calculados) en lugar de re-muestrear solapamientos.
    Precomputa idx_to_group para O(1) lookup en evaluate_subset.
    """
    # Set de pares solapados conocidos (de pair_logs)
    known_overlapping = set()
    for log in (pair_logs or []):
        known_overlapping.add((log["idx_a"],log["idx_b"]))
        known_overlapping.add((log["idx_b"],log["idx_a"]))

    comp_set = set(component_indices)
    forced_groups, group_records = [], []

    for qrec in (allowed_quad_records or []):
        quad_set = set(qrec.get("quad_key",[]))
        cands = [idx for idx in component_indices
                 if (lbs := _mmm_mast_labels(None, decorated_triangles_by_idx[idx]))
                 is not None and lbs <= quad_set]
        if len(cands) < 2: continue

        # Verificar solapamiento usando pair_logs (sin re-muestrear)
        has_overlap = any(
            (cands[i],cands[j]) in known_overlapping
            for i in range(len(cands))
            for j in range(i+1,len(cands))
        )
        if not has_overlap: continue

        fg = frozenset(cands)
        forced_groups.append(fg)
        group_records.append({**qrec,
                               "candidate_indices":sorted(cands),
                               "component_indices":sorted(comp_set)})

    # Precomputar idx → group_id para lookup O(1)
    idx_to_group = {}
    for gid, grp in enumerate(forced_groups):
        for idx in grp:
            idx_to_group[idx] = gid

    return {"forced_groups":forced_groups,"group_records":group_records,
            "idx_to_group":idx_to_group}


def forced_mmm_groups_satisfied_filter_11(subset_indices, allowed_overlap_context):
    sel = set(subset_indices)
    missing = []
    for grp in (allowed_overlap_context or {}).get("forced_groups",[]):
        if not set(grp) <= sel:
            missing.append(sorted(set(grp)-sel))
    return len(missing)==0, missing


# =========================================================
# 9) SOLVER DE CAPA LIMPIA (CON CACHÉ Y OVERLAP VECTORIZADO)
# =========================================================

def build_reference_samples_for_component_filter_11(component_indices,
                                                      decorated_triangles_by_idx,
                                                      divisions=26, decimals=7):
    seen = {}
    for idx in component_indices:
        tri = decorated_triangles_by_idx[idx]
        for p in sample_points_triangle_interior_filter_11(tri, divisions=divisions):
            k=(round(float(p["x"]),decimals),round(float(p["y"]),decimals))
            if k not in seen: seen[k]={"x":float(p["x"]),"y":float(p["y"])}
    return list(seen.values())


def coverage_matrix_for_component_filter_11(component_indices,
                                             decorated_triangles_by_idx, samples):
    if not component_indices or not samples:
        return np.zeros((0,0),dtype=bool)
    M=np.zeros((len(component_indices),len(samples)),dtype=bool)
    for row,idx in enumerate(component_indices):
        tri=decorated_triangles_by_idx[idx]
        n1,n2,n3=tri["nodes"]
        for col,p in enumerate(samples):
            M[row,col]=point_in_triangle_xy_filter_11(p["x"],p["y"],n1,n2,n3,tol=XY_GEOM_TOL_11)
    return M


def make_evaluator_with_cache_filter_11(component_indices, coverage_matrix,
                                         analyses_by_idx, decorated_triangles_by_idx,
                                         mode, reachable_mask, cov_thr, ovl_thr,
                                         protected_requirements, allowed_overlap_context):
    """
    Devuelve un evaluador con caché por frozenset(positions).
    Compartir el evaluador entre greedy y local_search reutiliza cálculos.
    """
    _cache = {}

    def _evaluate(positions):
        key = frozenset(positions)
        if key in _cache:
            return _cache[key]
        result = _evaluate_subset(positions)
        _cache[key] = result
        return result

    def _evaluate_subset(positions):
        subset_indices = [component_indices[p] for p in positions]

        if reachable_mask is not None and reachable_mask.any():
            total_points = int(reachable_mask.sum())
        else:
            total_points = int(coverage_matrix.shape[1])

        # Satisfacción de segmentos M-N protegidos
        prot_ok, prot_sat, prot_tot, prot_miss = protected_requirements_satisfied_filter_11(
            subset_indices, protected_requirements)

        # Satisfacción de grupos MMM obligatorios
        mmm_ok, mmm_miss = forced_mmm_groups_satisfied_filter_11(
            subset_indices, allowed_overlap_context)

        empty = {
            "subset_indices":subset_indices,"_positions":list(positions),
            "coverage_ratio":0.0,"covered_points":0,"total_points":total_points,
            "internal_overlap_ratio":1.0,"overlap_points":0,"raw_overlap_points":0,
            "allowed_mmm_overlap_points":0,"allowed_mmm_overlap_ratio":0.0,
            "avg_score":-1e18,"min_score":-1e18,"area_weighted_score":-1e18,
            "n_selected":len(subset_indices),"all_physical_valid":False,
            "protected_n_satisfied":prot_ok,"protected_n_satisfied_count":prot_sat,
            "protected_n_total_count":prot_tot,"protected_n_missing":prot_miss,
            "allowed_mmm_overlap_groups_satisfied":mmm_ok,
            "allowed_mmm_overlap_missing_groups":mmm_miss,
            "allowed_mmm_overlap_group_records":(allowed_overlap_context or {}).get("group_records",[]),
            "valid_clean":False,"mode":mode,
        }
        if total_points <= 0 or not positions:
            return empty

        sel_mat_full = coverage_matrix[list(positions), :]
        sel_mat = sel_mat_full[:,reachable_mask] if (reachable_mask is not None
                                                     and reachable_mask.any()) else sel_mat_full
        counts = sel_mat.sum(axis=0)
        covered_points  = int(np.count_nonzero(counts >= 1))
        raw_overlap     = int(np.count_nonzero(counts >= 2))

        # Clasificación vectorizada del solape: permitido vs prohibido
        disallowed = raw_overlap
        allowed_ov = 0
        forced_groups = (allowed_overlap_context or {}).get("forced_groups", [])
        idx_to_group  = (allowed_overlap_context or {}).get("idx_to_group", {})

        if raw_overlap > 0 and forced_groups:
            positions_arr = list(positions)
            disallowed = 0
            for col in np.where(counts >= 2)[0]:
                rows = np.where(sel_mat[:, col])[0]
                indices = [component_indices[positions_arr[int(r)]] for r in rows]
                gids = {idx_to_group.get(i) for i in indices}
                if len(gids) == 1 and None not in gids:
                    allowed_ov += 1
                else:
                    disallowed += 1

        coverage_ratio  = covered_points / total_points
        overlap_ratio   = disallowed / total_points
        allowed_ratio   = allowed_ov / total_points

        scores, areas, phys = [], [], []
        for idx in subset_indices:
            an = analyses_by_idx.get(idx, {})
            area = max(float(triangle_area_xy_filter_11(decorated_triangles_by_idx[idx])),
                       XY_AREA_TOL_11)
            sc = float(an.get("score",-1e9) if mode=="physical"
                       else an.get("geometric_score",0.0))
            scores.append(sc); areas.append(area)
            phys.append(bool(an.get("physical_valid",False)))

        if scores:
            sa=np.array(scores,dtype=float); aa=np.array(areas,dtype=float)
            aws=float(np.sum(sa*aa)/np.sum(aa))
            avs=float(np.mean(sa)); mis=float(np.min(sa))
        else:
            aws=avs=mis=-1e18

        all_phys = all(phys)
        mode_ok  = all_phys if mode=="physical" else True

        valid_clean = (
            total_points >= MIN_GROUP_SAMPLE_POINTS_11
            and coverage_ratio >= cov_thr
            and overlap_ratio  <= ovl_thr
            and mode_ok
            and prot_ok
            and mmm_ok
        )
        return {
            "subset_indices":subset_indices,"_positions":list(positions),
            "coverage_ratio":float(coverage_ratio),"covered_points":covered_points,
            "total_points":total_points,"internal_overlap_ratio":float(overlap_ratio),
            "overlap_points":int(disallowed),"raw_overlap_points":int(raw_overlap),
            "allowed_mmm_overlap_points":int(allowed_ov),
            "allowed_mmm_overlap_ratio":float(allowed_ratio),
            "avg_score":avs,"min_score":mis,"area_weighted_score":aws,
            "n_selected":len(subset_indices),"all_physical_valid":bool(all_phys),
            "protected_n_satisfied":prot_ok,"protected_n_satisfied_count":prot_sat,
            "protected_n_total_count":prot_tot,"protected_n_missing":prot_miss,
            "allowed_mmm_overlap_groups_satisfied":mmm_ok,
            "allowed_mmm_overlap_missing_groups":mmm_miss,
            "allowed_mmm_overlap_group_records":(allowed_overlap_context or {}).get("group_records",[]),
            "valid_clean":bool(valid_clean),"mode":mode,
        }

    return _evaluate


def better_subset_key_filter_11(sol):
    pt = int(sol.get("protected_n_total_count",0))
    pr = (int(sol.get("protected_n_satisfied_count",0))/max(pt,1)) if pt>0 else 1.0
    return (
        1 if sol.get("valid_clean",False) else 0,
        float(pr),
        float(sol.get("coverage_ratio",0.0)),
        -float(sol.get("internal_overlap_ratio",1.0)),
        float(sol.get("area_weighted_score",-1e18)),
        float(sol.get("avg_score",-1e18)),
        -int(sol.get("n_selected",10**9)),
    )


def local_search_swap_filter_11(initial_positions, allowed_positions, evaluate):
    """
    Búsqueda local: swap, adición pura, eliminación pura.
    Recibe el evaluador (con caché) directamente.
    """
    ovl_thr = GROUP_MAX_INTERNAL_OVERLAP_RATIO_11
    current = list(initial_positions)
    best    = evaluate(current)
    improved = True
    it = 0

    while improved and it < LOCAL_SEARCH_MAX_ITER_11:
        improved = False; it += 1
        outside = [p for p in allowed_positions if p not in current]

        for p_out in list(current):
            for p_in in outside:
                trial = sorted((set(current)-{p_out})|{p_in})
                sol   = evaluate(trial)
                if better_subset_key_filter_11(sol) > better_subset_key_filter_11(best):
                    current,best,improved = trial,sol,True; break
            if improved: break

        if not improved:
            for p_in in outside:
                trial = sorted(set(current)|{p_in})
                sol   = evaluate(trial)
                if (better_subset_key_filter_11(sol) > better_subset_key_filter_11(best)
                        and sol.get("internal_overlap_ratio",1.0) <= ovl_thr):
                    current,best,improved = trial,sol,True; break

        if not improved and len(current) > 1:
            for p_out in list(current):
                trial = sorted(set(current)-{p_out})
                sol   = evaluate(trial)
                if better_subset_key_filter_11(sol) > better_subset_key_filter_11(best):
                    current,best,improved = trial,sol,True; break

    best["method"] = best.get("method","") + "_local_search"
    return best


def _greedy_phase(allowed_positions, evaluate, ovl_thr, score_fn):
    order = sorted(allowed_positions, key=score_fn, reverse=True)
    selected = []
    empty = evaluate([])
    for pos in order:
        trial = sorted(set(selected)|{pos})
        sol_t = evaluate(trial)
        sol_c = evaluate(selected) if selected else empty
        if (better_subset_key_filter_11(sol_t) > better_subset_key_filter_11(sol_c)
                and sol_t.get("internal_overlap_ratio",1.0) <= ovl_thr):
            selected = trial
    return selected


def greedy_best_subset_for_component_filter_11(component_indices, coverage_matrix,
                                                analyses_by_idx, decorated_triangles_by_idx,
                                                mode, reachable_mask, cov_thr, ovl_thr,
                                                protected_requirements, allowed_overlap_context):
    allowed = [pos for pos,idx in enumerate(component_indices)
               if not (mode=="physical"
                       and not analyses_by_idx.get(idx,{}).get("physical_valid",False))]

    evaluate = make_evaluator_with_cache_filter_11(
        component_indices, coverage_matrix, analyses_by_idx, decorated_triangles_by_idx,
        mode, reachable_mask, cov_thr, ovl_thr, protected_requirements, allowed_overlap_context)

    if not allowed:
        sol = evaluate([]); sol.update(method=f"greedy_no_allowed_{mode}",n_options_evaluated=0)
        return sol

    def score_fn(pos):
        an=analyses_by_idx.get(component_indices[pos],{})
        return float(an.get("score",-1e9) if mode=="physical" else an.get("geometric_score",0.0))

    selected = _greedy_phase(allowed, evaluate, ovl_thr, score_fn)
    best = local_search_swap_filter_11(selected, allowed, evaluate)
    best["method"] = f"greedy_{mode}_with_local_search"
    best["n_options_evaluated"] = len(allowed)
    return best


def exact_best_subset_for_component_filter_11(component_indices, coverage_matrix,
                                               analyses_by_idx, decorated_triangles_by_idx,
                                               mode, reachable_mask, cov_thr, ovl_thr,
                                               protected_requirements, allowed_overlap_context):
    allowed = [pos for pos,idx in enumerate(component_indices)
               if not (mode=="physical"
                       and not analyses_by_idx.get(idx,{}).get("physical_valid",False))]

    evaluate = make_evaluator_with_cache_filter_11(
        component_indices, coverage_matrix, analyses_by_idx, decorated_triangles_by_idx,
        mode, reachable_mask, cov_thr, ovl_thr, protected_requirements, allowed_overlap_context)

    if not allowed:
        sol = evaluate([]); sol.update(method=f"exact_no_allowed_{mode}",n_options_evaluated=0)
        return sol

    if len(allowed) > MAX_EXACT_GROUP_SIZE_11:
        return greedy_best_subset_for_component_filter_11(
            component_indices, coverage_matrix, analyses_by_idx, decorated_triangles_by_idx,
            mode, reachable_mask, cov_thr, ovl_thr, protected_requirements, allowed_overlap_context)

    best, n_opts = None, 0
    m = len(allowed)
    for mask in range(1, 1<<m):
        positions = [allowed[k] for k in range(m) if mask&(1<<k)]
        sol = evaluate(positions); n_opts += 1
        if best is None or better_subset_key_filter_11(sol)>better_subset_key_filter_11(best):
            best = sol

    # Refinar con búsqueda local si no es limpia
    if best and not best.get("valid_clean",False):
        refined = local_search_swap_filter_11(best.get("_positions",[]), allowed, evaluate)
        if better_subset_key_filter_11(refined)>better_subset_key_filter_11(best):
            best = refined

    best["method"] = f"exact_enumeration_{mode}"
    best["n_options_evaluated"] = int(n_opts)
    return best


def solve_component_clean_layer_filter_11(component_indices, decorated_triangles_by_idx,
                                           analyses_by_idx, protected_requirements=None,
                                           allowed_overlap_context=None, pair_logs=None):
    samples = build_reference_samples_for_component_filter_11(
        component_indices, decorated_triangles_by_idx, divisions=COMPETITION_SAMPLE_DIVISIONS_11)
    M = coverage_matrix_for_component_filter_11(
        component_indices, decorated_triangles_by_idx, samples)

    all_pos  = list(range(len(component_indices)))
    phys_pos = [p for p,idx in enumerate(component_indices)
                if analyses_by_idx.get(idx,{}).get("physical_valid",False)]

    rm_geo = M[all_pos,:].any(axis=0)  if all_pos  else np.zeros(M.shape[1],dtype=bool)
    rm_phy = M[phys_pos,:].any(axis=0) if phys_pos else np.zeros(M.shape[1],dtype=bool)

    best_overall = None

    def _upd(sol):
        nonlocal best_overall
        if best_overall is None or better_subset_key_filter_11(sol)>better_subset_key_filter_11(best_overall):
            best_overall = sol

    for d_cov, d_ovl in RELAXATION_STEPS_11:
        ct = max(0.0, GROUP_COVERAGE_THRESHOLD_11-d_cov)
        ot = min(1.0, GROUP_MAX_INTERNAL_OVERLAP_RATIO_11+d_ovl)
        tag = f"_relax_{int(d_cov*100)}pct" if d_cov>0 else ""

        # rm_geo como referencia de cobertura: el método físico debe cubrir el área
        # completa del componente, no solo el área de los triángulos físicamente válidos.
        # rm_phy solo controla qué triángulos son elegibles (dentro del evaluador),
        # no qué área se exige cubrir.
        sol_phy = exact_best_subset_for_component_filter_11(
            component_indices, M, analyses_by_idx, decorated_triangles_by_idx,
            "physical", rm_geo, ct, ot, protected_requirements, allowed_overlap_context)
        sol_phy["reference_samples"] = samples
        _upd(sol_phy)
        if sol_phy.get("valid_clean",False):
            sol_phy["selected_strategy"]=f"physical_sphere_support{tag}"; return sol_phy

        if ENABLE_GEOMETRIC_FALLBACK_11:
            sol_geo = exact_best_subset_for_component_filter_11(
                component_indices, M, analyses_by_idx, decorated_triangles_by_idx,
                "geometric", rm_geo, ct, ot, protected_requirements, allowed_overlap_context)
            sol_geo["reference_samples"] = samples
            _upd(sol_geo)
            if sol_geo.get("valid_clean",False):
                sol_geo["selected_strategy"]=f"geometric_fallback{tag}"; return sol_geo

    if best_overall is None:
        best_overall={"subset_indices":component_indices,"_positions":all_pos,
                      "valid_clean":False,"coverage_ratio":0.0,
                      "internal_overlap_ratio":1.0,"reference_samples":samples}
    best_overall["selected_strategy"]="best_effort_no_clean_solution"
    return best_overall


# =========================================================
# 10) FUNCIÓN PRINCIPAL
# =========================================================

def build_active_tri_nodes_after_filter_11(tri_nodes_input, triangles):
    nbl = {}
    for n in tri_nodes_input: nbl[str(n["label"])]=n
    for tri in triangles:
        for n in tri.get("nodes",[]): nbl[str(n["label"])]=n
    active = {str(n["label"]) for tri in triangles for n in tri.get("nodes",[])}
    return [n for lbl,n in nbl.items() if node_family_filter_11(n)=="M" or lbl in active]


def filter_mmm_mmn_by_sphere_support_competition_11(
        triangles, tri_nodes, sphere_radius,
        sample_divisions_sphere=14, sample_divisions_competition=26,
        coverage_threshold=0.985, max_internal_overlap_ratio=0.015,
        score_margin=0.0, min_group_sample_points=8):

    globals()["GROUP_COVERAGE_THRESHOLD_11"]         = float(coverage_threshold)
    globals()["GROUP_MAX_INTERNAL_OVERLAP_RATIO_11"] = float(max_internal_overlap_ratio)
    globals()["MIN_GROUP_SAMPLE_POINTS_11"]           = int(min_group_sample_points)

    decorated = [decorate_triangle_type_filter_11(t) for t in triangles]
    by_idx    = {i:t for i,t in enumerate(decorated)}

    fixed_entries, candidate_initial, direct_kept = [], [], []
    for i,t in enumerate(decorated):
        tt=t["triangle_type"]
        if fixed_surface_type_filter_11(tt):
            fixed_entries.append((i,t))
        elif candidate_can_compete_filter_11(tt):
            candidate_initial.append((i,t))
        else:
            tk=dict(t); tk["kept_reason_filter11"]=f"{tt} conservado directamente."
            direct_kept.append((i,tk))

    fixed_triangles=[t for _,t in fixed_entries]

    # --- Paso 1: eliminar candidatos que invaden MMQ/NNM ---
    fixed_ov_removed, fixed_ov_log, cand_after_fixed = [], [], []
    for i,t in candidate_initial:
        overlaps,logs=candidate_overlaps_fixed_surface_filter_11(t,fixed_triangles)
        if overlaps:
            tr=dict(t)
            tr["removed_reason"]=f"{t['triangle_type']} eliminado: invade M-M-Q o N-N-M."
            tr["fixed_overlap_records_11"]=logs
            fixed_ov_removed.append(tr)
            fixed_ov_log.extend([{**rec,"candidate_idx":i} for rec in logs])
        else:
            cand_after_fixed.append((i,t))

    # --- Segmentos M-N protegidos ---
    guard_segs = globals().get("guard_segments_filter_11",None)
    if guard_segs is None:
        guard_segs = guard_wire_segments_from_inputs_filter_11(
            masts=globals().get("masts",[]),
            guard_wire_inputs=globals().get("guard_wire_inputs_filter_11",
                               globals().get("guard_wire_inputs",None)))

    prot_reqs, prot_debug = build_protected_mn_requirements_filter_11(
        cand_after_fixed, fixed_entries, guard_segs)

    # --- Análisis de soporte de esfera ---
    analyses = {i: analyze_triangle_sphere_support_filter_11(t, sphere_radius,
                                                              sample_divisions=sample_divisions_sphere)
                for i,t in cand_after_fixed}

    # --- Paso 2: reducir M-M-N alternativas misma base M-M ---
    cand_entries, removed_alt, alt_log = reduce_mmn_same_mm_alternatives_filter_11(
        cand_after_fixed, analyses, protected_requirements=prot_reqs)

    alt_removed = []
    for i,t in cand_after_fixed:
        if i in removed_alt:
            tr=dict(t)
            tr["removed_reason"]="M-M-N alternativa eliminada (misma base M-M)."
            tr["sphere_support_analysis_11"]=analyses.get(i)
            alt_removed.append(tr)

    # --- Paso 3: componentes de solapamiento ---
    components, adjacency, pair_logs = build_mlike_overlap_components_filter_11(cand_entries)

    # --- Patrones MMM de solape permitido ---
    allowed_quad_records = detect_allowed_mmm_overlap_quad_records_filter_11(
        tri_nodes=tri_nodes, triangles=decorated,
        guard_wire_inputs=globals().get("guard_wire_inputs_filter_11",
                          globals().get("guard_wire_inputs",None)),
        masts=globals().get("masts",None))

    selected_idx = set(); removed_idx = set()
    comp_log = []; unresolved = []; comp_solutions = {}

    for comp_id, comp_indices in enumerate(components):
        comp_prot = protected_requirements_for_component_filter_11(prot_reqs, comp_indices)

        ov_ctx = build_allowed_mmm_overlap_context_for_component_filter_11(
            comp_indices, by_idx, allowed_quad_records, pair_logs=pair_logs)

        sol = solve_component_clean_layer_filter_11(
            comp_indices, by_idx, analyses,
            protected_requirements=comp_prot,
            allowed_overlap_context=ov_ctx,
            pair_logs=pair_logs)
        comp_solutions[comp_id] = sol

        comp_set    = set(comp_indices)
        selected_set= set(sol.get("subset_indices", comp_indices))

        if sol.get("valid_clean",False):
            selected_idx.update(selected_set)
            removed_idx.update(comp_set-selected_set)
            decision="clean_subset_selected"
        else:
            if STRICT_CLEAN_LAYER_REQUIRED_11:
                raise RuntimeError(
                    f"Filtro 11 sin solución limpia en componente {comp_id}.\n"
                    f"Cobertura: {100*sol.get('coverage_ratio',0):.2f}%  "
                    f"Solape: {100*sol.get('internal_overlap_ratio',1):.2f}%")
            selected_idx.update(selected_set)
            removed_idx.update(comp_set-selected_set)
            decision=f"best_effort_{sol.get('selected_strategy','unknown')}"
            unresolved.append(comp_id)

        sel_competitors=[{"idx":i,"labels":triangle_labels_filter_11(by_idx[i]),
                          "type":by_idx[i]["triangle_type"],
                          "score":float(analyses.get(i,{}).get("score",-1e9)),
                          "geometric_score":float(analyses.get(i,{}).get("geometric_score",0.0))}
                         for i in sorted(selected_set)]

        for idx in comp_indices:
            t=by_idx[idx]; an=analyses.get(idx,{})
            comp_log.append({
                "component_id":int(comp_id),"component_size":int(len(comp_indices)),
                "component_decision":decision,"candidate_idx":idx,
                "candidate_labels":triangle_labels_filter_11(t),
                "candidate_type":t["triangle_type"],
                "candidate_score":float(an.get("score",-1e9)),
                "candidate_physical_valid":bool(an.get("physical_valid",False)),
                "selected_indices":sorted(selected_set),
                "coverage_ratio":float(sol.get("coverage_ratio",0.0)),
                "internal_overlap_ratio":float(sol.get("internal_overlap_ratio",1.0)),
                "raw_overlap_points":int(sol.get("raw_overlap_points",0)),
                "allowed_mmm_overlap_points":int(sol.get("allowed_mmm_overlap_points",0)),
                "valid_clean_solution":bool(sol.get("valid_clean",False)),
                "protected_n_satisfied":bool(sol.get("protected_n_satisfied",True)),
                "protected_n_missing":sol.get("protected_n_missing",[]),
                "selected_strategy":sol.get("selected_strategy",""),
                "method":sol.get("method","unknown"),
                "covering_competitors":sel_competitors,
                "removed":bool(idx in removed_idx),
            })

    # --- Listas finales ---
    kept = []
    for _,t in fixed_entries:
        tk=dict(t); tk["kept_reason_filter11"]=f"{t['triangle_type']} superficie fija."
        kept.append(tk)
    kept.extend([t for _,t in direct_kept])

    removed_competition = []
    for idx,tri in cand_entries:
        te=dict(tri); te["sphere_support_analysis_11"]=analyses.get(idx)
        related=[r for r in comp_log if r["candidate_idx"]==idx]
        te["sphere_competition_records_11"]=related
        strategy=related[0].get("selected_strategy","") if related else ""
        if idx in removed_idx:
            te["removed_reason"]=f"{tri['triangle_type']} eliminado por competencia de capa limpia."
            removed_competition.append(te)
        else:
            if "geometric_fallback" in strategy:
                te["kept_reason_filter11"]=f"{tri['triangle_type']} conservado por fallback geométrico."
            elif related and related[0].get("valid_clean_solution",False):
                te["kept_reason_filter11"]=f"{tri['triangle_type']} conservado por solución limpia."
            else:
                te["kept_reason_filter11"]=f"{tri['triangle_type']} conservado (mejor intento)."
            kept.append(te)

    removed_all = fixed_ov_removed + alt_removed + removed_competition
    tri_nodes_after = build_active_tri_nodes_after_filter_11(tri_nodes, kept)

    globals()["fixed_overlap_log_11"]                  = fixed_ov_log
    globals()["removed_triangles_fixed_overlap_11"]    = fixed_ov_removed
    globals()["removed_triangles_mmn_alternatives_11"] = alt_removed
    globals()["mmn_alternative_reduction_log_11"]      = alt_log
    globals()["mlike_overlap_components_11"]           = components
    globals()["mlike_overlap_pair_logs_11"]            = pair_logs
    globals()["mlike_unresolved_components_11"]        = unresolved
    globals()["component_solutions_filter11_11"]       = comp_solutions
    globals()["clean_layer_solution_log_11"]           = comp_log
    globals()["protected_mn_requirements_11"]          = prot_reqs
    globals()["protected_mn_debug_11"]                 = prot_debug
    globals()["allowed_mmm_overlap_quad_records_11"]   = allowed_quad_records

    return kept, removed_all, tri_nodes_after, analyses, comp_log


# =========================================================
# 11) GRÁFICA
# =========================================================

def guard_wire_segments_from_inputs_filter_11(masts, guard_wire_inputs=None):
    segs=[]
    if not guard_wire_inputs: return segs
    for k,gw in enumerate(guard_wire_inputs):
        try:
            if isinstance(gw,dict): i,j=int(gw["i"]),int(gw["j"])
            else: i,j=int(gw[0]),int(gw[1])
            mi,mj=masts[i],masts[j]
            p1=np.array([mi.x,mi.y,mi.h],dtype=float)
            p2=np.array([mj.x,mj.y,mj.h],dtype=float)
            segs.append({"guard_idx":k,"label_a":f"M{i}","label_b":f"M{j}",
                         "labels":(f"M{i}",f"M{j}"),"p1":p1,"p2":p2})
        except Exception: continue
    return segs


def triangle_color_filter_11(t):
    return {"M-M-M":"gray","M-M-Q":"red","N-N-M":"green","M-M-N":"purple"}.get(
        normalize_triangle_type_filter_11(t),"black")


def plot_guard_segments_filter_11(fig, segs):
    if not segs: return
    xs,ys,zs,ts=[],[],[],[]
    for g in segs:
        p1,p2=g["p1"],g["p2"]; h=f"Guarda {g['label_a']}-{g['label_b']}"
        xs+=[p1[0],p2[0],None]; ys+=[p1[1],p2[1],None]
        zs+=[p1[2],p2[2],None]; ts+=[h,h,None]
    fig.add_trace(go.Scatter3d(x=xs,y=ys,z=zs,mode="lines",
        line=dict(color="darkgreen",width=GUARD_LINE_WIDTH_11),
        name="Guardas",hoverinfo="text",text=ts,showlegend=True))


def add_triangle_edges_grouped_by_type_filter_11(fig, triangles):
    type_order=["M-M-M","M-M-N","M-M-Q","N-N-M"]
    grouped={t:{"x":[],"y":[],"z":[],"text":[]} for t in type_order}
    other={"x":[],"y":[],"z":[],"text":[]}
    ordered=[]
    for t in type_order:
        ordered+=[tri for tri in triangles if decorate_triangle_type_filter_11(tri)["triangle_type"]==t]
    ordered+=[tri for tri in triangles if decorate_triangle_type_filter_11(tri)["triangle_type"] not in type_order]
    for tri_data in ordered:
        tri=decorate_triangle_type_filter_11(tri_data); t=tri["triangle_type"]
        n1,n2,n3=tri["nodes"]
        lbl=format_labels_filter_11(triangle_labels_filter_11(tri))
        tgt=grouped.get(t,other)
        for a,b in [(n1,n2),(n2,n3),(n3,n1)]:
            tgt["x"]+=[a["x"],b["x"],None]; tgt["y"]+=[a["y"],b["y"],None]
            tgt["z"]+=[a["z"],b["z"],None]
            h=(f"Tipo:{t}<br>{lbl}<br>{a.get('label','')}-{b.get('label','')}<br>"
               f"{tri.get('kept_reason_filter11','')}")
            tgt["text"]+=[h,h,None]
    names={"M-M-M":"MMM","M-M-N":"MMN","M-M-Q":"MMQ fijos","N-N-M":"NNM fijos"}
    for t in type_order:
        d=grouped[t]
        if d["x"]:
            fig.add_trace(go.Scatter3d(x=d["x"],y=d["y"],z=d["z"],mode="lines",
                line=dict(color=triangle_color_filter_11(t),width=TRIANGLE_LINE_WIDTH_11),
                name=names.get(t,t),hoverinfo="text",text=d["text"],showlegend=True))
    if other["x"]:
        fig.add_trace(go.Scatter3d(x=other["x"],y=other["y"],z=other["z"],mode="lines",
            line=dict(color="black",width=TRIANGLE_LINE_WIDTH_11),
            name="Otros",hoverinfo="text",text=other["text"],showlegend=True))


def add_removed_triangles_grouped_filter_11(fig, removed):
    if not removed: return
    xs,ys,zs,ts=[],[],[],[]
    for tri_data in removed:
        tri=decorate_triangle_type_filter_11(tri_data); n1,n2,n3=tri["nodes"]
        lbl=format_labels_filter_11(triangle_labels_filter_11(tri))
        xl=[n1["x"],n2["x"],n3["x"],n1["x"],None]; yl=[n1["y"],n2["y"],n3["y"],n1["y"],None]
        zl=[n1["z"],n2["z"],n3["z"],n1["z"],None]
        h=f"Eliminado<br>{lbl}<br>{tri.get('removed_reason','')}"
        xs+=xl; ys+=yl; zs+=zl; ts+=[h]*len(xl)
    fig.add_trace(go.Scatter3d(x=xs,y=ys,z=zs,mode="lines",
        line=dict(color="magenta",width=TRIANGLE_LINE_WIDTH_11,dash="dash"),
        name="MMM/MMN eliminados",hoverinfo="text",text=ts,showlegend=True))


def add_sphere_centers_filter_11(fig, analyses_by_idx, triangles_by_idx, removed_indices=None):
    removed_indices=removed_indices or set()
    xs,ys,zs,ts=[],[],[],[]
    for idx,an in analyses_by_idx.items():
        ctr=an.get("support_center")
        if ctr is None or idx not in triangles_by_idx: continue
        tri=decorate_triangle_type_filter_11(triangles_by_idx[idx])
        lbl=format_labels_filter_11(triangle_labels_filter_11(tri))
        st="eliminado" if idx in removed_indices else "conservado"
        xs.append(float(ctr[0])); ys.append(float(ctr[1])); zs.append(float(ctr[2]))
        ts.append(f"Centro esfera {lbl}<br>{tri['triangle_type']}<br>{st}<br>score={an.get('score')}")
    if xs:
        fig.add_trace(go.Scatter3d(x=xs,y=ys,z=zs,mode="markers",
            marker=dict(size=5,color="black",symbol="x"),
            name="Centros esfera",hoverinfo="text",text=ts,showlegend=True,visible="legendonly"))


def add_q_nodes_filter_11(fig,tri_nodes):
    q=[n for n in tri_nodes if node_family_filter_11(n)=="Q"]
    if q:
        fig.add_trace(go.Scatter3d(x=[n["x"] for n in q],y=[n["y"] for n in q],
            z=[n["z"] for n in q],mode="markers+text",marker=dict(size=6,color="orange"),
            text=[n["label"] for n in q],textposition="top center",
            name="Q activos",hoverinfo="text",showlegend=True))


def add_n_nodes_filter_11(fig,tri_nodes):
    nds=[n for n in tri_nodes if node_family_filter_11(n)=="N"]
    if nds:
        fig.add_trace(go.Scatter3d(x=[n["x"] for n in nds],y=[n["y"] for n in nds],
            z=[n["z"] for n in nds],mode="markers+text",
            marker=dict(size=9,color="cyan",symbol="diamond"),
            text=[n["label"] for n in nds],textposition="top center",
            name="N activos",hoverinfo="text",showlegend=True))


def add_masts_filter_11(fig,tri_nodes):
    ms=[n for n in tri_nodes if node_family_filter_11(n)=="M"]
    xl,yl,zl,tl=[],[],[],[]
    for n in ms:
        h=f"Mástil {n['label']}"
        xl+=[n["x"],n["x"],None]; yl+=[n["y"],n["y"],None]
        zl+=[0.0,n["z"],None]; tl+=[h,h,None]
    if xl:
        fig.add_trace(go.Scatter3d(x=xl,y=yl,z=zl,mode="lines",
            line=dict(color="blue",width=MAST_LINE_WIDTH_11),
            name="Mástiles",hoverinfo="text",text=tl,showlegend=True))
    if ms:
        fig.add_trace(go.Scatter3d(x=[n["x"] for n in ms],y=[n["y"] for n in ms],
            z=[n["z"] for n in ms],mode="markers+text",marker=dict(size=5,color="black"),
            text=[n["label"] for n in ms],textposition="top center",
            name="Puntas mástil",hoverinfo="text",showlegend=True))


def add_single_mast_reference_filter_11(fig,masts,results,sphere_radius):
    if results is None or "effective_radius" not in globals(): return
    for i,mast in enumerate(masts):
        try:
            ai=effective_radius(mast.h,sphere_radius)
            for th1,th2 in results[i]["useful_intervals"]:
                theta=np.linspace(th1,th2,80); r=np.linspace(0,ai,20)
                TH,RR=np.meshgrid(theta,r,indexing="xy")
                fig.add_trace(go.Surface(x=mast.x+RR*np.cos(TH),y=mast.y+RR*np.sin(TH),
                    z=np.zeros_like(RR),showscale=False,opacity=0.10,
                    hoverinfo="skip",showlegend=False))
        except Exception: pass


def add_ground_filter_11(fig,tri_nodes):
    if tri_nodes:
        xy=np.array([[n["x"],n["y"]] for n in tri_nodes],dtype=float)
        xmn,ymn=xy.min(axis=0)-5; xmx,ymx=xy.max(axis=0)+5
    else: xmn,ymn,xmx,ymx=-5,-5,5,5
    Xg,Yg=np.meshgrid(np.linspace(xmn,xmx,2),np.linspace(ymn,ymx,2))
    fig.add_trace(go.Surface(x=Xg,y=Yg,z=np.zeros_like(Xg),
        opacity=0.08,showscale=False,hoverinfo="skip",showlegend=False))


def plot_triangles_after_filter_11(tri_nodes,kept_triangles,removed_triangles,masts,results,
                                    sphere_radius,guard_segments,analyses_by_idx,competition_log,
                                    triangles_by_idx,removed_indices,
                                    show_single_mast_reference=True,
                                    show_removed_triangles=False,show_sphere_centers=True):
    fig=go.Figure()
    plot_guard_segments_filter_11(fig,guard_segments)
    add_triangle_edges_grouped_by_type_filter_11(fig,kept_triangles)
    if show_removed_triangles:
        add_removed_triangles_grouped_filter_11(fig,removed_triangles)
    if show_sphere_centers:
        add_sphere_centers_filter_11(fig,analyses_by_idx,triangles_by_idx,removed_indices)
    add_q_nodes_filter_11(fig,tri_nodes)
    add_n_nodes_filter_11(fig,tri_nodes)
    add_masts_filter_11(fig,tri_nodes)
    if show_single_mast_reference:
        add_single_mast_reference_filter_11(fig,masts,results,sphere_radius)
    add_ground_filter_11(fig,tri_nodes)
    fig.update_layout(
        title="Filtro 11 v3 — Capa limpia M-like (MMM/MMN)",
        scene=dict(xaxis_title="X",yaxis_title="Y",zaxis_title="Z",aspectmode="data"),
        height=900,
        legend=dict(title="Elementos",itemclick="toggle",itemdoubleclick="toggleothers"))
    fig.show()
    return fig


