# 2) UTILIDADES GENERALES
# =========================================================

def node_family_3B(node):
    raw_type = str(node.get("type", "")).strip()
    label = str(node.get("label", "")).strip()

    if raw_type in ["M", "mast", "mast_top"] or label.startswith("M"):
        return "M"
    if raw_type == "N" or raw_type.startswith("auxiliary_N") or label.startswith("N"):
        return "N"
    if raw_type == "Q" or label.startswith("Q"):
        return "Q"

    return raw_type


def classify_triangle_type_3B(tri):
    fams = [node_family_3B(n) for n in tri["nodes"]]
    nM = fams.count("M")
    nN = fams.count("N")
    nQ = fams.count("Q")

    if nM == 3:
        return "M-M-M"
    if nM == 2 and nQ == 1:
        return "M-M-Q"
    if nN == 2 and nM == 1:
        return "N-N-M"
    if nM == 2 and nN == 1:
        return "M-M-N"
    if nM == 1 and nQ == 2:
        return "M-Q-Q"
    if nQ == 3:
        return "Q-Q-Q"
    if nM == 1 and nN == 1 and nQ == 1:
        return "M-N-Q"
    if nN == 3:
        return "N-N-N"
    if nN == 2 and nQ == 1:
        return "N-N-Q"

    return "Otro"


def edge_key_3B(a, b):
    return tuple(sorted([str(a), str(b)]))


if "edge_key" not in globals():
    def edge_key(a, b):
        return edge_key_3B(a, b)


def node_point_3B(n):
    return np.array([float(n["x"]), float(n["y"]), float(n["z"])], dtype=float)


def node_xy_3B(n):
    return np.array([float(n["x"]), float(n["y"])], dtype=float)


def curve_to_array_3B(curve):
    if curve is None:
        return None

    if isinstance(curve, tuple) and len(curve) == 3:
        x, y, z = curve
        C = np.column_stack([x, y, z]).astype(float)
    else:
        C = np.asarray(curve, dtype=float)

    if C.ndim != 2 or C.shape[1] != 3 or len(C) < 2:
        return None

    C[:, 2] = np.maximum(C[:, 2], 0.0)
    return C


def resample_curve_xyz_3B(curve_xyz, npts=180):
    C = curve_to_array_3B(curve_xyz)

    if C is None:
        return None
    if len(C) < 2:
        return C

    d = np.linalg.norm(np.diff(C, axis=0), axis=1)
    s_old = np.concatenate([[0.0], np.cumsum(d)])

    if s_old[-1] < 1e-12:
        return np.repeat(C[:1], npts, axis=0)

    s_old = s_old / s_old[-1]
    s_new = np.linspace(0.0, 1.0, npts)

    out = np.column_stack([
        np.interp(s_new, s_old, C[:, 0]),
        np.interp(s_new, s_old, C[:, 1]),
        np.interp(s_new, s_old, C[:, 2]),
    ])

    out[:, 2] = np.maximum(out[:, 2], 0.0)
    return out


def orient_curve_xyz_3B(curve_xyz, start_node, end_node):
    C = curve_to_array_3B(curve_xyz)

    if C is None:
        return None

    p_start = node_point_3B(start_node)
    p_end = node_point_3B(end_node)

    d_normal = np.linalg.norm(C[0] - p_start) + np.linalg.norm(C[-1] - p_end)
    d_flip = np.linalg.norm(C[-1] - p_start) + np.linalg.norm(C[0] - p_end)

    if d_flip < d_normal:
        C = C[::-1].copy()

    C[:, 2] = np.maximum(C[:, 2], 0.0)
    return C


_base_crest_func_3B = globals().get(
    "base_crest_between_two_nodes_3A",
    globals().get(
        "base_crest_between_two_masts_3A",
        globals().get("base_crest_between_two_masts", None)
    )
)

if _base_crest_func_3B is None:
    raise NameError(
        "No se encontró función base de crestas desde FASE 3A. "
        "Ejecuta FASE 3A corregida antes de FASE 3B."
    )


def base_crest_between_nodes_3B(n1, n2, sphere_radius, npts=220):
    out = _base_crest_func_3B(
        n1=n1,
        n2=n2,
        sphere_radius=sphere_radius,
        npts=npts
    )

    if isinstance(out, tuple) and len(out) == 3:
        curve = out[0]
        kind = out[1]
        chord_len = out[2]
    else:
        curve = out
        kind = "base_crest"
        chord_len = float(np.linalg.norm(node_point_3B(n2) - node_point_3B(n1)))

    C = curve_to_array_3B(curve)

    if C is None:
        return None, kind, chord_len

    C = resample_curve_xyz_3B(C, npts=npts)
    C = orient_curve_xyz_3B(C, n1, n2)

    return C, kind, chord_len


def format_labels_3B(labels):
    if isinstance(labels, (tuple, list)):
        return "-".join(str(x) for x in labels)
    return str(labels)


