# 3) GUARDAS
# =========================================================

def guard_wire_labels_3B(w):
    if isinstance(w, dict):
        if "label_i" in w and "label_j" in w:
            a = str(w["label_i"])
            b = str(w["label_j"])
        elif "i" in w and "j" in w:
            a = f"M{int(w['i'])}"
            b = f"M{int(w['j'])}"
        elif "labels" in w:
            a = str(w["labels"][0])
            b = str(w["labels"][1])
        else:
            raise ValueError(f"Formato de guarda no reconocido: {w}")
    else:
        a = f"M{int(w[0])}" if not str(w[0]).startswith("M") else str(w[0])
        b = f"M{int(w[1])}" if not str(w[1]).startswith("M") else str(w[1])

    return edge_key(a, b)


def node_by_label_from_masts_3B(mast_nodes):
    return {str(n["label"]): n for n in mast_nodes}


def node_by_label_from_all_nodes_3B(tri_nodes, mast_nodes=None):
    out = {}

    if mast_nodes is not None:
        for n in mast_nodes:
            out[str(n["label"])] = n

    for n in tri_nodes:
        out[str(n["label"])] = n

    return out


def guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes):
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    out = []

    if guard_wire_inputs is None:
        return out

    for w in guard_wire_inputs:
        a, b = guard_wire_labels_3B(w)
        if a in node_by_label and b in node_by_label:
            out.append(edge_key(a, b))

    return sorted(set(out))


def edge_has_guard_wire_3B(label1, label2, guard_wire_inputs, mast_nodes=None):
    key = edge_key(label1, label2)

    if mast_nodes is None:
        mast_nodes = resultado_crestas_base["mast_nodes"]

    for e in guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes):
        if edge_key(*e) == key:
            return True

    return False


def get_guard_neighbors_3B(label, guard_wire_inputs, mast_nodes):
    neigh = []

    for a, b in guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes):
        if label == a:
            neigh.append(b)
        elif label == b:
            neigh.append(a)

    return neigh


def is_common_tetra_edge_3B(label1, label2, common_tetra_edges=None):
    if common_tetra_edges is None:
        return True

    normalized = {edge_key(a, b) for a, b in common_tetra_edges}
    return edge_key(label1, label2) in normalized


def parse_host_guard_key_3B(value):
    if value is None:
        return None

    if isinstance(value, dict):
        if "label_i" in value and "label_j" in value:
            return edge_key(str(value["label_i"]), str(value["label_j"]))
        if "i" in value and "j" in value:
            return edge_key(f"M{int(value['i'])}", f"M{int(value['j'])}")
        if "labels" in value and len(value["labels"]) >= 2:
            return edge_key(str(value["labels"][0]), str(value["labels"][1]))

    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return edge_key(str(value[0]), str(value[1]))

    txt = str(value).replace("_", "-").replace(",", "-").replace(" ", "")
    parts = [p for p in txt.split("-") if p]

    if len(parts) == 2:
        a, b = parts

        if not a.startswith("M") and a.isdigit():
            a = f"M{a}"
        if not b.startswith("M") and b.isdigit():
            b = f"M{b}"

        if a.startswith("M") and b.startswith("M"):
            return edge_key(a, b)

    return None


# =========================================================
# 4) GEOMETRÍA AUXILIAR
# =========================================================

def orient2d_3B(a, b, c):
    return (
        (b[0] - a[0]) * (c[1] - a[1])
        -
        (b[1] - a[1]) * (c[0] - a[0])
    )


def segments_cross_xy_3B(a, b, c, d, tol=1e-9):
    a = np.asarray(a, dtype=float)[:2]
    b = np.asarray(b, dtype=float)[:2]
    c = np.asarray(c, dtype=float)[:2]
    d = np.asarray(d, dtype=float)[:2]

    o1 = orient2d_3B(a, b, c)
    o2 = orient2d_3B(a, b, d)
    o3 = orient2d_3B(c, d, a)
    o4 = orient2d_3B(c, d, b)

    return (o1 * o2 < -tol) and (o3 * o4 < -tol)


def point_on_segment_xy_3B(P, A, B, tol=1e-7):
    P = np.asarray(P, dtype=float)[:2]
    A = np.asarray(A, dtype=float)[:2]
    B = np.asarray(B, dtype=float)[:2]

    AB = B - A
    den = float(np.dot(AB, AB))

    if den < 1e-12:
        return np.linalg.norm(P - A) <= tol

    t = float(np.dot(P - A, AB) / den)

    if t < -tol or t > 1.0 + tol:
        return False

    Q = A + np.clip(t, 0.0, 1.0) * AB
    return float(np.linalg.norm(P - Q)) <= tol


def point_parameter_on_segment_xy_3B(P, A, B):
    P = np.asarray(P, dtype=float)[:2]
    A = np.asarray(A, dtype=float)[:2]
    B = np.asarray(B, dtype=float)[:2]

    AB = B - A
    den = float(np.dot(AB, AB))

    if den <= 1e-15:
        return None

    return float(np.dot(P - A, AB) / den)


def point_distance_to_segment_by_lambda_xy_3B(P, A, B, lam):
    P = np.asarray(P, dtype=float)[:2]
    A = np.asarray(A, dtype=float)[:2]
    B = np.asarray(B, dtype=float)[:2]

    Q = A + float(lam) * (B - A)
    return float(np.linalg.norm(P - Q))


def point_in_polygon_xy_3B(point_xy, polygon_xy, include_boundary=False, tol=1e-9):
    x, y = point_xy
    poly = np.asarray(polygon_xy, dtype=float)
    n = len(poly)

    for i in range(n):
        if point_on_segment_xy_3B(point_xy, poly[i], poly[(i + 1) % n], tol=1e-7):
            return bool(include_boundary)

    inside = False

    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]

        cond = ((y1 > y) != (y2 > y))

        if cond:
            x_inter = x1 + (y - y1) * (x2 - x1) / (y2 - y1 + 1e-15)

            if x_inter > x + tol:
                inside = not inside

    return inside


def polygon_area_xy_3B(poly):
    poly = np.asarray(poly, dtype=float)

    x = poly[:, 0]
    y = poly[:, 1]

    return 0.5 * float(
        abs(
            np.dot(x, np.roll(y, -1))
            -
            np.dot(y, np.roll(x, -1))
        )
    )


def xy_dist_3B(n1, n2):
    return float(np.linalg.norm(node_xy_3B(n1) - node_xy_3B(n2)))


def closest_point_on_segment_xy_3B(P, A, B):
    P = np.asarray(P, dtype=float)
    A = np.asarray(A, dtype=float)
    B = np.asarray(B, dtype=float)

    AB = B - A
    den = float(np.dot(AB, AB))

    if den < 1e-12:
        return A, 0.0, float(np.linalg.norm(P - A))

    t = float(np.dot(P - A, AB) / den)
    t = float(np.clip(t, 0.0, 1.0))
    Q = A + t * AB

    return Q, t, float(np.linalg.norm(P - Q))


def closest_point_on_segment_3d_3B(P, A, B):
    P = np.asarray(P, dtype=float)
    A = np.asarray(A, dtype=float)
    B = np.asarray(B, dtype=float)

    AB = B - A
    den = float(np.dot(AB, AB))

    if den < 1e-12:
        return A.copy(), 0.0

    t = float(np.dot(P - A, AB) / den)
    t = float(np.clip(t, 0.0, 1.0))

    return A + t * AB, t


def distance_point_to_segment_3d_3B(P, A, B):
    Q, t = closest_point_on_segment_3d_3B(P, A, B)
    return float(np.linalg.norm(np.asarray(P, dtype=float) - Q)), Q, t


def edge_vector_xy_3B(edge, node_by_label):
    return node_xy_3B(node_by_label[edge[1]]) - node_xy_3B(node_by_label[edge[0]])


def are_guard_edges_parallel_xy_3B(edge1, edge2, node_by_label, tol=PARALLEL_TOL_3B):
    v1 = edge_vector_xy_3B(edge1, node_by_label)
    v2 = edge_vector_xy_3B(edge2, node_by_label)

    n1 = np.linalg.norm(v1)
    n2 = np.linalg.norm(v2)

    if n1 <= tol or n2 <= tol:
        return False

    cross = abs(v1[0] * v2[1] - v1[1] * v2[0])
    return cross <= tol * max(1.0, n1 * n2)


def projection_overlap_length_3B(edge1, edge2, node_by_label):
    v = edge_vector_xy_3B(edge1, node_by_label)
    L = float(np.linalg.norm(v))

    if L <= 1e-12:
        return 0.0

    u = v / L

    vals_1 = [
        float(np.dot(node_xy_3B(node_by_label[edge1[0]]), u)),
        float(np.dot(node_xy_3B(node_by_label[edge1[1]]), u)),
    ]

    vals_2 = [
        float(np.dot(node_xy_3B(node_by_label[edge2[0]]), u)),
        float(np.dot(node_xy_3B(node_by_label[edge2[1]]), u)),
    ]

    a1, b1 = min(vals_1), max(vals_1)
    a2, b2 = min(vals_2), max(vals_2)

    return max(0.0, min(b1, b2) - max(a1, a2))


# =========================================================
# 5) REGISTRO Y PRIORIDADES
# =========================================================

def registry_priority_3B(source):
    priorities = {
        "direct_guard_wire": 100,
        "direct_guard_wire_segment_MN": 100,
        "direct_guard_wire_fragment_NN": 100,
        "four_guard_closed": 90,
        "three_guard_chain": 70,
        "shared_guard_plus_k": 60,
        "shared_guard_free_edge_omitted": 60,
        # OG2SM debe quedar por debajo de guardas independientes.
        # Así, si Subcaso 1/2 necesita recuperar una cresta, puede hacerlo.
        "one_guard_two_support_masts": 45,
        "independent_guard_lines": 50,
        "independent_guard_lines_subcase2": 50,
        "independent_guard_lines_subcase3": 0,
        "base_normal_L_le_2S": 0,
        "base_long_L_gt_2S": 0,
        "base_failed": -1,
    }
    return priorities.get(source, 0)


def registry_edge_is_base_3B(registry, label1, label2):
    key = edge_key(label1, label2)
    if key not in registry:
        return False
    item = registry[key]
    if item.get("omit", False) or item.get("curve", None) is None:
        return False
    return item.get("source", "") in {
        "base_normal_L_le_2S", "base_long_L_gt_2S", "base_failed",
    }


def is_edge_in_registry_3B(registry, label1, label2):
    return edge_key(label1, label2) in registry


def override_registry_edge_3B(registry, label1, label2, curve, kind, source, info=None, log=None, replace_existing=True):
    key = edge_key(label1, label2)
    if key not in registry:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_edge_not_in_registry"})
        return False
    item = registry[key]
    if item.get("source") in {"direct_guard_wire", "direct_guard_wire_segment_MN", "direct_guard_wire_fragment_NN"}:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_direct_guard_or_guard_fragment", "old_source": item.get("source")})
        return False
    if item.get("omit", False):
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_edge_omitted", "old_source": item.get("source")})
        return False
    if not replace_existing:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_replace_disabled", "old_source": item.get("source")})
        return False
    old_source = item.get("source")
    old_priority = item.get("priority", registry_priority_3B(old_source))
    new_priority = registry_priority_3B(source)
    if new_priority < old_priority:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_lower_priority", "old_source": old_source, "old_priority": old_priority, "new_priority": new_priority})
        return False
    C = curve_to_array_3B(curve)
    if C is None:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_invalid_curve"})
        return False
    nodes = item.get("nodes", None)
    if nodes is None or len(nodes) != 2:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_missing_edge_nodes"})
        return False
    n1, n2 = nodes
    C = resample_curve_xyz_3B(C, npts=max(80, len(C)))
    C = orient_curve_xyz_3B(C, n1, n2)
    registry[key] = {
        **item,
        "edge": key,
        "nodes": (n1, n2),
        "curve": C,
        "kind": kind,
        "source": source,
        "priority": new_priority,
        "replaceable": True,
        "omit": False,
        "info": info if info is not None else {"case_type": source},
        "overwritten_from": old_source,
    }
    if log is not None:
        log.append({"edge": key, "source": source, "status": "replaced", "old_source": old_source})
    return True


def omit_registry_edge_3B(registry, label1, label2, kind, source, info=None, log=None):
    key = edge_key(label1, label2)
    if key not in registry:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_omit_edge_not_in_registry"})
        return False
    item = registry[key]
    if item.get("source") in {"direct_guard_wire", "direct_guard_wire_segment_MN", "direct_guard_wire_fragment_NN"}:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_omit_direct_guard_or_fragment", "old_source": item.get("source")})
        return False
    old_source = item.get("source")
    old_priority = item.get("priority", registry_priority_3B(old_source))
    new_priority = registry_priority_3B(source)
    if new_priority < old_priority:
        if log is not None:
            log.append({"edge": key, "source": source, "status": "skip_omit_lower_priority", "old_source": old_source})
        return False
    registry[key] = {
        **item,
        "curve": None,
        "kind": kind,
        "source": source,
        "priority": new_priority,
        "replaceable": False,
        "omit": True,
        "info": info if info is not None else {"case_type": source, "omit": True},
        "overwritten_from": old_source,
    }
    if log is not None:
        log.append({"edge": key, "source": source, "status": "omitted", "old_source": old_source})
    return True


# =========================================================
# 6) ESFERAS DE SOPORTE Y CRESTAS ESPECIALES
# =========================================================

def tangent_points_from_point_to_circle_2d_3B(P, C, R, tol=1e-8):
    P = np.asarray(P, dtype=float)
    C = np.asarray(C, dtype=float)
    v = P - C
    D = np.linalg.norm(v)
    if D < R - tol:
        return []
    if abs(D - R) <= tol:
        return [P.copy()]
    e = v / D
    p = np.array([-e[1], e[0]])
    a = R**2 / D
    b = R * np.sqrt(max(D**2 - R**2, 0.0)) / D
    return [C + a * e + b * p, C + a * e - b * p]


def choose_inner_tangent_point_2d_3B(P, C, R, side):
    tangents = tangent_points_from_point_to_circle_2d_3B(P, C, R)
    if not tangents:
        return None
    if side == "left":
        candidates = [T for T in tangents if T[0] >= P[0] - 1e-9]
    elif side == "right":
        candidates = [T for T in tangents if T[0] <= P[0] + 1e-9]
    else:
        candidates = tangents
    if not candidates:
        candidates = tangents
    return min(candidates, key=lambda T: T[1])


def lower_support_crest_from_sphere_between_points_3B(n1, n2, O, R, npts=240):
    P1 = node_point_3B(n1)
    P2 = node_point_3B(n2)
    O = np.asarray(O, dtype=float)
    e1 = P2 - P1
    L = np.linalg.norm(e1)
    if L < 1e-12:
        return None
    e1 = e1 / L
    O_proj = P1 + np.dot(O - P1, e1) * e1
    e2 = O - O_proj
    if np.linalg.norm(e2) < 1e-9:
        aux = np.array([0.0, 0.0, 1.0])
        e2 = aux - np.dot(aux, e1) * e1
    if np.linalg.norm(e2) < 1e-9:
        aux = np.array([0.0, 1.0, 0.0])
        e2 = aux - np.dot(aux, e1) * e1
    if np.linalg.norm(e2) < 1e-9:
        return None
    e2 = e2 / np.linalg.norm(e2)

    def to_local(P):
        rel = P - P1
        return np.array([np.dot(rel, e1), np.dot(rel, e2)])

    def to_global(u, w):
        return P1 + u * e1 + w * e2

    A = to_local(P1)
    B = to_local(P2)
    C = to_local(O)
    T_A = choose_inner_tangent_point_2d_3B(A, C, R, side="left")
    T_B = choose_inner_tangent_point_2d_3B(B, C, R, side="right")
    if T_A is None or T_B is None:
        return None
    if T_A[0] > T_B[0]:
        T_A, T_B = T_B, T_A
    n_line = max(50, npts // 4)
    u_left = np.linspace(A[0], T_A[0], n_line)
    w_left = np.linspace(A[1], T_A[1], n_line)
    u_arc = np.linspace(T_A[0], T_B[0], npts)
    inside = R**2 - (u_arc - C[0])**2
    inside = np.maximum(inside, 0.0)
    w_arc = C[1] - np.sqrt(inside)
    u_right = np.linspace(T_B[0], B[0], n_line)
    w_right = np.linspace(T_B[1], B[1], n_line)
    u = np.concatenate([u_left, u_arc[1:], u_right[1:]])
    w = np.concatenate([w_left, w_arc[1:], w_right[1:]])
    pts = np.array([to_global(ui, wi) for ui, wi in zip(u, w)])
    pts[:, 2] = np.maximum(pts[:, 2], 0.0)
    pts[0, :] = P1
    pts[-1, :] = P2
    return pts


def solve_support_sphere_below_contacts_3B(seg1, seg2, point, R):
    A1, B1 = [np.asarray(p, dtype=float) for p in seg1]
    A2, B2 = [np.asarray(p, dtype=float) for p in seg2]
    P = np.asarray(point, dtype=float)
    centroid = (0.5 * (A1 + B1) + 0.5 * (A2 + B2) + P) / 3.0
    seeds = []
    for dz in [0.25 * R, 0.5 * R, R, 1.5 * R, 2.0 * R]:
        seeds.append(centroid + np.array([0.0, 0.0, dz]))
    for sx in [-R, 0.0, R]:
        for sy in [-R, 0.0, R]:
            for dz in [0.5 * R, R, 1.5 * R]:
                seeds.append(centroid + np.array([sx, sy, dz]))

    def residual(O):
        d1, _, _ = distance_point_to_segment_3d_3B(O, A1, B1)
        d2, _, _ = distance_point_to_segment_3d_3B(O, A2, B2)
        d3 = np.linalg.norm(O - P)
        return np.array([d1 - R, d2 - R, d3 - R])

    best = None
    for seed in seeds:
        sol = least_squares(residual, x0=seed, xtol=1e-11, ftol=1e-11, gtol=1e-11, max_nfev=5000)
        O = sol.x
        err = np.linalg.norm(residual(O))
        d1, Q1, t1 = distance_point_to_segment_3d_3B(O, A1, B1)
        d2, Q2, t2 = distance_point_to_segment_3d_3B(O, A2, B2)
        if not (-1e-6 <= t1 <= 1.0 + 1e-6 and -1e-6 <= t2 <= 1.0 + 1e-6):
            continue
        if not (Q1[2] < O[2] - 1e-6 and Q2[2] < O[2] - 1e-6 and P[2] < O[2] - 1e-6):
            continue
        if not (O[2] > max(Q1[2], Q2[2], P[2])):
            continue
        if err > 1e-5:
            continue
        cand = {"O": O, "Q1": Q1, "Q2": Q2, "Q3": P, "t1": t1, "t2": t2, "err": err, "score": O[2]}
        if best is None or cand["score"] < best["score"]:
            best = cand
    return best


def solve_support_sphere_below_three_segments_3B(seg1, seg2, seg3, R):
    A1, B1 = [np.asarray(p, dtype=float) for p in seg1]
    A2, B2 = [np.asarray(p, dtype=float) for p in seg2]
    A3, B3 = [np.asarray(p, dtype=float) for p in seg3]
    centroid = (0.5 * (A1 + B1) + 0.5 * (A2 + B2) + 0.5 * (A3 + B3)) / 3.0
    seeds = []
    for dz in [0.25 * R, 0.5 * R, R, 1.5 * R, 2.0 * R, 2.5 * R]:
        seeds.append(centroid + np.array([0.0, 0.0, dz]))
    for sx in [-R, 0.0, R]:
        for sy in [-R, 0.0, R]:
            for dz in [0.5 * R, R, 1.5 * R, 2.0 * R]:
                seeds.append(centroid + np.array([sx, sy, dz]))

    def residual(O):
        d1, _, _ = distance_point_to_segment_3d_3B(O, A1, B1)
        d2, _, _ = distance_point_to_segment_3d_3B(O, A2, B2)
        d3, _, _ = distance_point_to_segment_3d_3B(O, A3, B3)
        return np.array([d1 - R, d2 - R, d3 - R])

    best = None
    for seed in seeds:
        sol = least_squares(residual, x0=seed, xtol=1e-11, ftol=1e-11, gtol=1e-11, max_nfev=5000)
        O = sol.x
        err = np.linalg.norm(residual(O))
        d1, Q1, t1 = distance_point_to_segment_3d_3B(O, A1, B1)
        d2, Q2, t2 = distance_point_to_segment_3d_3B(O, A2, B2)
        d3, Q3, t3 = distance_point_to_segment_3d_3B(O, A3, B3)
        if not (-1e-6 <= t1 <= 1.0 + 1e-6 and -1e-6 <= t2 <= 1.0 + 1e-6 and -1e-6 <= t3 <= 1.0 + 1e-6):
            continue
        if not (Q1[2] < O[2] - 1e-6 and Q2[2] < O[2] - 1e-6 and Q3[2] < O[2] - 1e-6):
            continue
        if not (O[2] > max(Q1[2], Q2[2], Q3[2])):
            continue
        if err > 1e-5:
            continue
        cand = {"O": O, "Q1": Q1, "Q2": Q2, "Q3": Q3, "t1": t1, "t2": t2, "t3": t3, "err": err, "score": O[2]}
        if best is None or cand["score"] < best["score"]:
            best = cand
    return best


def solve_support_sphere_below_one_segment_two_points_3B(seg, point1, point2, R):
    A, B = [np.asarray(p, dtype=float) for p in seg]
    P1 = np.asarray(point1, dtype=float)
    P2 = np.asarray(point2, dtype=float)
    centroid = (0.5 * (A + B) + P1 + P2) / 3.0
    seeds = []
    for dz in [0.25 * R, 0.5 * R, R, 1.5 * R, 2.0 * R, 2.5 * R]:
        seeds.append(centroid + np.array([0.0, 0.0, dz]))
    for sx in [-R, 0.0, R]:
        for sy in [-R, 0.0, R]:
            for dz in [0.5 * R, R, 1.5 * R, 2.0 * R]:
                seeds.append(centroid + np.array([sx, sy, dz]))

    def residual(O):
        d_seg, _, _ = distance_point_to_segment_3d_3B(O, A, B)
        return np.array([d_seg - R, np.linalg.norm(O - P1) - R, np.linalg.norm(O - P2) - R])

    best = None
    for seed in seeds:
        sol = least_squares(residual, x0=seed, xtol=1e-11, ftol=1e-11, gtol=1e-11, max_nfev=5000)
        O = sol.x
        err = np.linalg.norm(residual(O))
        d_seg, Q_seg, t_seg = distance_point_to_segment_3d_3B(O, A, B)
        if not (-1e-6 <= t_seg <= 1.0 + 1e-6):
            continue
        if not (Q_seg[2] < O[2] - 1e-6 and P1[2] < O[2] - 1e-6 and P2[2] < O[2] - 1e-6):
            continue
        if not (O[2] > max(Q_seg[2], P1[2], P2[2])):
            continue
        if err > 1e-5:
            continue
        cand = {"O": O, "Q1": Q_seg, "Q2": P1, "Q3": P2, "t_segment": t_seg, "err": err, "score": O[2]}
        if best is None or cand["score"] < best["score"]:
            best = cand
    return best


