def build_real_triangle_edges_3B(triangles):
    edges = {}
    for tri_idx, tri in enumerate(triangles):
        nodes = tri["nodes"]
        tri_type = tri.get("triangle_type", classify_triangle_type_3B(tri))
        for a, b in [(0, 1), (1, 2), (2, 0)]:
            n1 = nodes[a]
            n2 = nodes[b]
            key = edge_key(n1["label"], n2["label"])
            fam_pair = tuple(sorted([node_family_3B(n1), node_family_3B(n2)]))
            edges.setdefault(key, {"edge": key, "nodes": (n1, n2), "families": fam_pair, "triangles": []})
            edges[key]["triangles"].append({"tri_idx": tri_idx, "triangle_type": tri_type, "labels": tri.get("labels", None)})
    return edges


# =========================================================
# 8) CASO 1 — CUADRILÁTERO CERRADO DE 4 GUARDAS
# =========================================================

def find_four_guard_closed_cycles_3B(mast_nodes, guard_wire_inputs):
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    labels = list(node_by_label.keys())
    adj = {label: set() for label in labels}
    for a, b in guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes):
        adj[a].add(b)
        adj[b].add(a)

    def canonical_cycle(cyc):
        cyc = list(cyc)
        n = len(cyc)
        rots = []
        for k in range(n):
            rots.append(tuple(cyc[k:] + cyc[:k]))
        rev = list(reversed(cyc))
        for k in range(n):
            rots.append(tuple(rev[k:] + rev[:k]))
        return min(rots)

    cycles = []
    for A in labels:
        for B in adj[A]:
            for C in adj[B]:
                if C in [A, B]:
                    continue
                for D in adj[C]:
                    if D in [A, B, C]:
                        continue
                    if A not in adj[D]:
                        continue
                    labels_cycle = [A, B, C, D]
                    cycles.append({"canonical": canonical_cycle(labels_cycle), "labels": labels_cycle, "A": node_by_label[A], "B": node_by_label[B], "C": node_by_label[C], "D": node_by_label[D]})
    unique = {c["canonical"]: c for c in cycles}
    return list(unique.values())


def build_four_guard_cycle_edges_3B(cycle_labels):
    A, B, C, D = cycle_labels
    return [(A, B), (B, C), (C, D), (D, A)]


def segment_from_edge_labels_3B(edge, node_by_label):
    a, b = edge
    return node_point_3B(node_by_label[a]), node_point_3B(node_by_label[b])


def solve_valid_spheres_for_four_guard_cycle_3B(cycle_labels, node_by_label, sphere_radius):
    polygon_edges = build_four_guard_cycle_edges_3B(cycle_labels)
    polygon_xy = np.asarray([node_xy_3B(node_by_label[l]) for l in cycle_labels], dtype=float)
    valid = []
    for e1, e2, e3 in combinations(polygon_edges, 3):
        sol = solve_support_sphere_below_three_segments_3B(
            seg1=segment_from_edge_labels_3B(e1, node_by_label),
            seg2=segment_from_edge_labels_3B(e2, node_by_label),
            seg3=segment_from_edge_labels_3B(e3, node_by_label),
            R=sphere_radius,
        )
        if sol is None:
            continue
        if not point_in_polygon_xy_3B(sol["O"][:2], polygon_xy, include_boundary=False):
            continue
        valid.append({"sphere": sol, "support_edges": (e1, e2, e3)})
    return valid


def best_crest_for_edge_from_spheres_3B(n1, n2, valid_spheres, sphere_radius):
    best = None
    for idx, item in enumerate(valid_spheres):
        crest = lower_support_crest_from_sphere_between_points_3B(n1, n2, item["sphere"]["O"], sphere_radius, npts=260)
        if crest is None:
            continue
        score = float(np.nanmin(crest[:, 2]))
        cand = {"crest": crest, "score": score, "sphere_index": idx, "sphere_item": item}
        if best is None or cand["score"] > best["score"]:
            best = cand
    return best


def apply_four_guard_closed_overrides_3B(registry, mast_nodes, guard_wire_inputs, sphere_radius, common_tetra_edges, log):
    if not ENABLE_FOUR_GUARD_CLOSED_CASE:
        return set()
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    cycles = find_four_guard_closed_cycles_3B(mast_nodes, guard_wire_inputs)
    closed_cycle_sets = set()
    for cyc in cycles:
        labels = cyc["labels"]
        closed_cycle_sets.add(frozenset(labels))
        A, B, C, D = cyc["A"], cyc["B"], cyc["C"], cyc["D"]
        edge_AC = edge_key(A["label"], C["label"])
        edge_BD = edge_key(B["label"], D["label"])
        AC_allowed = edge_AC in registry and is_common_tetra_edge_3B(A["label"], C["label"], common_tetra_edges)
        BD_allowed = edge_BD in registry and is_common_tetra_edge_3B(B["label"], D["label"], common_tetra_edges)
        if not AC_allowed and not BD_allowed:
            continue
        valid_spheres = solve_valid_spheres_for_four_guard_cycle_3B(labels, node_by_label, sphere_radius)
        if not valid_spheres:
            continue
        case_base = {"cycle_labels": labels, "valid_spheres": valid_spheres}
        if AC_allowed:
            best = best_crest_for_edge_from_spheres_3B(A, C, valid_spheres, sphere_radius)
            if best is not None:
                override_registry_edge_3B(registry, A["label"], C["label"], best["crest"], "Cresta especial inferior por cuadrilátero cerrado de guardas", "four_guard_closed", {"case_type": "four_guard_closed", "case": case_base, "role": "diagonal_AC", "sphere": best["sphere_item"]}, log)
        if BD_allowed:
            best = best_crest_for_edge_from_spheres_3B(B, D, valid_spheres, sphere_radius)
            if best is not None:
                override_registry_edge_3B(registry, B["label"], D["label"], best["crest"], "Cresta especial inferior por cuadrilátero cerrado de guardas", "four_guard_closed", {"case_type": "four_guard_closed", "case": case_base, "role": "diagonal_BD", "sphere": best["sphere_item"]}, log)
    return closed_cycle_sets


# =========================================================
# 9) CASO 2 — TRES GUARDAS CONSECUTIVAS
# =========================================================

def find_three_guard_chains_3B(mast_nodes, guard_wire_inputs):
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    labels = list(node_by_label.keys())
    chains = []
    for A in labels:
        for B in get_guard_neighbors_3B(A, guard_wire_inputs, mast_nodes):
            for C in get_guard_neighbors_3B(B, guard_wire_inputs, mast_nodes):
                if C in [A, B]:
                    continue
                for D in get_guard_neighbors_3B(C, guard_wire_inputs, mast_nodes):
                    if D in [A, B, C]:
                        continue
                    ch = [A, B, C, D]
                    can = min(tuple(ch), tuple(reversed(ch)))
                    chains.append({"canonical": can, "labels": ch, "A": node_by_label[A], "B": node_by_label[B], "C": node_by_label[C], "D": node_by_label[D]})
    unique = {c["canonical"]: c for c in chains}
    return list(unique.values())


def apply_three_guard_chain_overrides_3B(registry, mast_nodes, guard_wire_inputs, sphere_radius, common_tetra_edges, closed_cycle_sets, log):
    if not ENABLE_THREE_GUARD_CHAIN_CASE:
        return
    chains = find_three_guard_chains_3B(mast_nodes, guard_wire_inputs)
    for ch in chains:
        if frozenset(ch["labels"]) in closed_cycle_sets:
            log.append({"edge": None, "source": "three_guard_chain", "status": "skip_chain_inside_four_guard_cycle", "labels": ch["labels"]})
            continue
        A, B, C, D = ch["A"], ch["B"], ch["C"], ch["D"]
        edge_AC = edge_key(A["label"], C["label"])
        edge_BD = edge_key(B["label"], D["label"])
        AC_allowed = edge_AC in registry and is_common_tetra_edge_3B(A["label"], C["label"], common_tetra_edges)
        BD_allowed = edge_BD in registry and is_common_tetra_edge_3B(B["label"], D["label"], common_tetra_edges)
        if not AC_allowed and not BD_allowed:
            continue
        sol = solve_support_sphere_below_three_segments_3B(
            seg1=(node_point_3B(A), node_point_3B(B)),
            seg2=(node_point_3B(B), node_point_3B(C)),
            seg3=(node_point_3B(C), node_point_3B(D)),
            R=sphere_radius,
        )
        if sol is None:
            continue
        case = {"chain_labels": ch["labels"], "sphere": sol}
        if AC_allowed:
            crest = lower_support_crest_from_sphere_between_points_3B(A, C, sol["O"], sphere_radius, npts=240)
            if crest is not None:
                override_registry_edge_3B(registry, A["label"], C["label"], crest, "Cresta especial inferior por tres guardas consecutivas", "three_guard_chain", {"case_type": "three_guard_chain", "case": case, "role": "diagonal_AC"}, log)
        if BD_allowed:
            crest = lower_support_crest_from_sphere_between_points_3B(B, D, sol["O"], sphere_radius, npts=240)
            if crest is not None:
                override_registry_edge_3B(registry, B["label"], D["label"], crest, "Cresta especial inferior por tres guardas consecutivas", "three_guard_chain", {"case_type": "three_guard_chain", "case": case, "role": "diagonal_BD"}, log)


# =========================================================
# 10) CASO 4 — UNA GUARDA + DOS MÁSTILES DE APOYO
#     Versión NO exclusiva
# =========================================================

def no_intermediate_mast_between_3B(K1, K2, mast_nodes, tol_xy=1e-7):
    A = node_xy_3B(K1)
    B = node_xy_3B(K2)
    for mast in mast_nodes:
        if mast["label"] in {K1["label"], K2["label"]}:
            continue
        _, lam, dist = closest_point_on_segment_xy_3B(node_xy_3B(mast), A, B)
        if dist <= tol_xy and tol_xy < lam < 1.0 - tol_xy:
            return False, mast
    return True, None


def og2sm_candidate_geometry_valid_3B(A, B, K1, K2):
    return segments_cross_xy_3B(node_point_3B(A), node_point_3B(K2), node_point_3B(B), node_point_3B(K1))


def og2sm_registry_edge_status_3B(registry, label1, label2):
    key = edge_key(label1, label2)
    if key not in registry:
        return {"edge": key, "exists": False, "source": None, "omit": None, "is_base": False}
    item = registry[key]
    source = item.get("source", None)
    return {"edge": key, "exists": True, "source": source, "omit": bool(item.get("omit", False)), "is_base": registry_edge_is_base_3B(registry, label1, label2)}


def og2sm_support_context_3B(registry, A_label, B_label, K1_label, K2_label):
    support_edges = [edge_key(A_label, K1_label), edge_key(K1_label, K2_label), edge_key(K2_label, B_label)]
    support_status = [og2sm_registry_edge_status_3B(registry, e[0], e[1]) for e in support_edges]
    return support_edges, support_status


def og2sm_opposite_edge_parallel_3B(A, B, K1, K2, node_by_label):
    return are_guard_edges_parallel_xy_3B(edge_key(A["label"], B["label"]), edge_key(K1["label"], K2["label"]), node_by_label)


def og2sm_no_external_mast_inside_quad_3B(A, B, K1, K2, mast_nodes):
    poly = np.array([node_xy_3B(A), node_xy_3B(B), node_xy_3B(K2), node_xy_3B(K1)], dtype=float)
    if polygon_area_xy_3B(poly) <= 1e-9:
        return False, None
    allowed = {A["label"], B["label"], K1["label"], K2["label"]}
    for mast in mast_nodes:
        if mast["label"] in allowed:
            continue
        if point_in_polygon_xy_3B(node_xy_3B(mast), poly, include_boundary=False):
            return False, mast
    return True, None


def og2sm_diagonal_is_replaceable_3B(registry, label1, label2, common_tetra_edges=None):
    """
    Regla protegida para OG2SM.

    Para evitar que el caso "una guarda + dos mástiles de apoyo" afecte
    crestas de otros casos especiales —especialmente guardas independientes
    Subcaso 1 y Subcaso 2—, OG2SM SOLO puede reemplazar crestas base
    generadas en FASE 3A.

    No reemplaza:
      - cables de guarda directos;
      - fragmentos de guarda M-N / N-N;
      - cuadriláteros cerrados;
      - tres guardas consecutivas;
      - shared_guard_plus_k;
      - guardas independientes Subcaso 1 o Subcaso 2;
      - cualquier otra fuente especial.

    Nota:
      common_tetra_edges se conserva en la firma por compatibilidad,
      pero aquí no se usa como filtro obligatorio.
    """
    key = edge_key(label1, label2)

    if key not in registry:
        return False

    item = registry[key]
    source = item.get("source", "")

    if item.get("omit", False):
        return False

    if item.get("curve", None) is None:
        return False

    # Nunca reemplazar guardas directas ni fragmentos de guarda.
    if source in {
        "direct_guard_wire",
        "direct_guard_wire_segment_MN",
        "direct_guard_wire_fragment_NN",
    }:
        return False

    # ÚNICA condición positiva: debe ser cresta base de FASE 3A.
    if source in {
        "base_normal_L_le_2S",
        "base_long_L_gt_2S",
        "base_failed",
    }:
        return True

    # Todo caso especial queda protegido.
    return False

def guard_edge_participates_in_other_guard_cases_3B(guard_edge, guard_wire_inputs, mast_nodes):
    a, b = edge_key(*guard_edge)
    neigh_a = set(get_guard_neighbors_3B(a, guard_wire_inputs, mast_nodes))
    neigh_b = set(get_guard_neighbors_3B(b, guard_wire_inputs, mast_nodes))
    return {
        "guard_edge": edge_key(a, b),
        "neighbors_a": sorted(neigh_a),
        "neighbors_b": sorted(neigh_b),
        "belongs_to_chain_or_shared_context": bool(neigh_a or neigh_b),
        "non_exclusive": True,
    }




def og2sm_support_masts_guard_participation_3B(
    K1_label,
    K2_label,
    guard_edges,
    main_guard_edge=None
):
    """
    Restricción adicional para el caso una guarda + dos mástiles de apoyo.

    Los apoyos K1/K2 pueden hacer parte de cables de guarda, pero el conjunto
    formado por ambos apoyos SOLO puede participar en un (1) cable de guarda
    adicional.

    Interpretación:
      - Se cuenta cualquier guarda que tenga como extremo a K1 o K2.
      - Se excluye la guarda principal A-B que está actuando como soporte
        del caso OG2SM, aunque en la práctica K1/K2 ya no deberían pertenecer
        a A-B porque se toman como apoyos externos.
      - Si K1-K2 es una guarda directa, cuenta como un único cable.
      - Si K1 pertenece a una guarda y K2 pertenece a otra distinta, cuenta
        como dos cables y el caso se descarta.
    """
    K1_label = str(K1_label)
    K2_label = str(K2_label)
    support_set = {K1_label, K2_label}

    main_key = None
    if main_guard_edge is not None:
        main_key = edge_key(*main_guard_edge)

    participating = []

    for edge in guard_edges:
        ekey = edge_key(*edge)

        if main_key is not None and ekey == main_key:
            continue

        if support_set.intersection(set(ekey)):
            participating.append(ekey)

    # Deduplicar conservando orden estable.
    participating_unique = sorted(set(participating))

    return {
        "support_labels": tuple(sorted([K1_label, K2_label])),
        "main_guard_edge": main_key,
        "participating_guard_edges": participating_unique,
        "n_support_guard_edges": len(participating_unique),
        "max_allowed_support_guard_edges": 1,
        "ok": len(participating_unique) <= 1,
    }



def og2sm_sphere_support_on_guard_central_third_3B(
    sphere_solution,
    t_min=OG2SM_GUARD_SUPPORT_T_MIN_3B,
    t_max=OG2SM_GUARD_SUPPORT_T_MAX_3B,
    tol=OG2SM_GUARD_SUPPORT_T_TOL_3B
):
    """
    Valida la nueva restricción de OG2SM:

    La esfera debe apoyarse sobre la guarda principal A-B dentro del tercio
    central del cable. La solución de la esfera devuelve t_segment, que ubica
    el punto de contacto Q1 sobre el segmento A-B:

        t_segment = 0   -> extremo A
        t_segment = 1   -> extremo B

    El caso solo aplica si:

        1/3 <= t_segment <= 2/3

    con una tolerancia pequeña para evitar rechazos numéricos en el borde.
    """
    if sphere_solution is None:
        return False, {
            "status": "sphere_solution_none",
            "t_segment": None,
            "t_min": float(t_min),
            "t_max": float(t_max),
            "tol": float(tol),
            "ok": False,
        }

    t_raw = sphere_solution.get("t_segment", None)

    if t_raw is None:
        return False, {
            "status": "missing_t_segment",
            "t_segment": None,
            "t_min": float(t_min),
            "t_max": float(t_max),
            "tol": float(tol),
            "ok": False,
        }

    t = float(t_raw)
    ok = (float(t_min) - float(tol)) <= t <= (float(t_max) + float(tol))

    return bool(ok), {
        "status": "support_in_central_third" if ok else "support_outside_central_third",
        "t_segment": t,
        "t_min": float(t_min),
        "t_max": float(t_max),
        "tol": float(tol),
        "ok": bool(ok),
        "contact_point_on_guard": sphere_solution.get("Q1", None),
    }

def apply_one_guard_two_support_masts_overrides_3B(registry, mast_nodes, guard_wire_inputs, sphere_radius, common_tetra_edges, log):
    if not ENABLE_ONE_GUARD_TWO_SUPPORT_CASE:
        return []
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    guard_edges = guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes)
    labels = sorted(node_by_label.keys())
    applied_records = []
    used_diag_sets = set()
    for guard_edge in guard_edges:
        gA, gB = guard_edge
        guard_context = guard_edge_participates_in_other_guard_cases_3B(guard_edge, guard_wire_inputs, mast_nodes)
        support_labels = [lab for lab in labels if lab not in {gA, gB}]
        for K1_label, K2_label in combinations(support_labels, 2):
            candidates = []
            for A_label, B_label in [(gA, gB), (gB, gA)]:
                for k1, k2 in [(K1_label, K2_label), (K2_label, K1_label)]:
                    A = node_by_label[A_label]
                    B = node_by_label[B_label]
                    K1 = node_by_label[k1]
                    K2 = node_by_label[k2]

                    support_guard_participation = og2sm_support_masts_guard_participation_3B(
                        K1_label=k1,
                        K2_label=k2,
                        guard_edges=guard_edges,
                        main_guard_edge=edge_key(A_label, B_label),
                    )

                    if not support_guard_participation["ok"]:
                        if log is not None:
                            log.append({
                                "edge": edge_key(A_label, B_label),
                                "source": "one_guard_two_support_masts",
                                "status": "skip_og2sm_support_masts_in_more_than_one_guard",
                                "guard_edge": edge_key(A_label, B_label),
                                "K1": k1,
                                "K2": k2,
                                "support_guard_participation": support_guard_participation,
                                "guard_context": guard_context,
                            })
                        continue

                    ok_mid, middle = no_intermediate_mast_between_3B(K1, K2, mast_nodes)
                    if not ok_mid:
                        if log is not None:
                            log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "skip_og2sm_intermediate_mast_between_supports", "guard_edge": edge_key(A_label, B_label), "K1": k1, "K2": k2, "middle_mast": middle["label"] if middle else None, "guard_context": guard_context})
                        continue
                    # Cambio puntual solicitado:
                    # En OG2SM ya NO se descarta el caso por falta de paralelismo
                    # entre la guarda A-B y el segmento K1-K2. El paralelismo queda
                    # como diagnóstico, pero se mantienen todas las demás restricciones:
                    #   - K1-K2 sin mástil intermedio,
                    #   - diagonales cruzadas,
                    #   - cuadrilátero sin mástiles externos,
                    #   - diagonales reemplazables SOLO si son crestas base de FASE 3A,
                    #   - esfera de apoyo resuelta.
                    og2sm_parallel_ok = og2sm_opposite_edge_parallel_3B(A, B, K1, K2, node_by_label)
                    if log is not None and not og2sm_parallel_ok:
                        log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "warn_og2sm_opposite_edge_not_parallel_but_not_skipped", "guard_edge": edge_key(A_label, B_label), "support_edge": edge_key(k1, k2), "guard_context": guard_context})
                    if not og2sm_candidate_geometry_valid_3B(A, B, K1, K2):
                        if log is not None:
                            log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "skip_og2sm_diagonals_do_not_cross", "guard_edge": edge_key(A_label, B_label), "K1": k1, "K2": k2, "guard_context": guard_context})
                        continue
                    ok_empty, inside_mast = og2sm_no_external_mast_inside_quad_3B(A, B, K1, K2, mast_nodes)
                    if not ok_empty:
                        if log is not None:
                            log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "skip_og2sm_external_mast_inside_quad", "guard_edge": edge_key(A_label, B_label), "K1": k1, "K2": k2, "inside_mast": inside_mast["label"] if inside_mast else None, "guard_context": guard_context})
                        continue
                    support_edges, support_status = og2sm_support_context_3B(registry, A_label, B_label, k1, k2)
                    d1 = edge_key(A_label, k2)
                    d2 = edge_key(B_label, k1)
                    d1_ok = og2sm_diagonal_is_replaceable_3B(registry, A_label, k2, common_tetra_edges)
                    d2_ok = og2sm_diagonal_is_replaceable_3B(registry, B_label, k1, common_tetra_edges)
                    if not d1_ok and not d2_ok:
                        if log is not None:
                            log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "skip_og2sm_no_replaceable_diagonals", "guard_edge": edge_key(A_label, B_label), "K1": k1, "K2": k2, "diagonal_1": d1, "diagonal_2": d2, "d1_ok": d1_ok, "d2_ok": d2_ok, "diag1_status": og2sm_registry_edge_status_3B(registry, d1[0], d1[1]), "diag2_status": og2sm_registry_edge_status_3B(registry, d2[0], d2[1]), "support_status": support_status, "guard_context": guard_context})
                        continue
                    sol = solve_support_sphere_below_one_segment_two_points_3B(seg=(node_point_3B(A), node_point_3B(B)), point1=node_point_3B(K1), point2=node_point_3B(K2), R=sphere_radius)
                    if sol is None:
                        if log is not None:
                            log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "skip_og2sm_sphere_not_solved", "guard_edge": edge_key(A_label, B_label), "K1": k1, "K2": k2, "diagonal_1": d1, "diagonal_2": d2, "d1_ok": d1_ok, "d2_ok": d2_ok, "diag1_status": og2sm_registry_edge_status_3B(registry, d1[0], d1[1]), "diag2_status": og2sm_registry_edge_status_3B(registry, d2[0], d2[1]), "support_status": support_status, "guard_context": guard_context})
                        continue

                    support_central_third_ok, support_central_third_info = (
                        og2sm_sphere_support_on_guard_central_third_3B(sol)
                    )

                    if not support_central_third_ok:
                        if log is not None:
                            log.append({"edge": edge_key(A_label, B_label), "source": "one_guard_two_support_masts", "status": "skip_og2sm_support_point_outside_guard_central_third", "guard_edge": edge_key(A_label, B_label), "K1": k1, "K2": k2, "diagonal_1": d1, "diagonal_2": d2, "d1_ok": d1_ok, "d2_ok": d2_ok, "diag1_status": og2sm_registry_edge_status_3B(registry, d1[0], d1[1]), "diag2_status": og2sm_registry_edge_status_3B(registry, d2[0], d2[1]), "support_status": support_status, "support_guard_participation": support_guard_participation, "support_central_third_info": support_central_third_info, "guard_context": guard_context})
                        continue

                    candidates.append({"guard_edge": edge_key(*guard_edge), "guard_edge_oriented": (A_label, B_label), "A": A, "B": B, "K1": K1, "K2": K2, "support_edges_context": support_edges, "support_status": support_status, "support_guard_participation": support_guard_participation, "support_central_third_info": support_central_third_info, "diagonal_1": d1, "diagonal_2": d2, "d1_ok": d1_ok, "d2_ok": d2_ok, "sphere": sol, "score": sol["O"][2], "no_N_used": True, "support_edges_are_context_only": True, "guard_context": guard_context})
            if not candidates:
                continue
            candidates.sort(key=lambda c: c["score"])
            case = candidates[0]
            diag_set = tuple(sorted([case["diagonal_1"], case["diagonal_2"]]))
            if diag_set in used_diag_sets:
                continue
            used_diag_sets.add(diag_set)
            applied = []
            if case["d1_ok"]:
                crest = lower_support_crest_from_sphere_between_points_3B(case["A"], case["K2"], case["sphere"]["O"], sphere_radius, npts=240)
                if crest is not None:
                    ok = override_registry_edge_3B(registry, case["A"]["label"], case["K2"]["label"], crest, "Cresta especial por una guarda y dos mástiles de apoyo", "one_guard_two_support_masts", {"case_type": "one_guard_two_support_masts", "case": case, "role": "A_to_K2", "no_N_used": True, "support_edges_are_context_only": True, "guard_can_belong_to_other_cases": True, "support_guard_participation": case.get("support_guard_participation"), "support_central_third_info": case.get("support_central_third_info")}, log)
                    if ok:
                        applied.append(case["diagonal_1"])
            if case["d2_ok"]:
                crest = lower_support_crest_from_sphere_between_points_3B(case["B"], case["K1"], case["sphere"]["O"], sphere_radius, npts=240)
                if crest is not None:
                    ok = override_registry_edge_3B(registry, case["B"]["label"], case["K1"]["label"], crest, "Cresta especial por una guarda y dos mástiles de apoyo", "one_guard_two_support_masts", {"case_type": "one_guard_two_support_masts", "case": case, "role": "B_to_K1", "no_N_used": True, "support_edges_are_context_only": True, "guard_can_belong_to_other_cases": True, "support_guard_participation": case.get("support_guard_participation"), "support_central_third_info": case.get("support_central_third_info")}, log)
                    if ok:
                        applied.append(case["diagonal_2"])
            if applied:
                applied_records.append({"guard_edge": case["guard_edge"], "guard_edge_oriented": case["guard_edge_oriented"], "K1": case["K1"]["label"], "K2": case["K2"]["label"], "applied_diagonals": applied, "sphere": case["sphere"], "support_edges_context": case["support_edges_context"], "support_status": case["support_status"], "support_guard_participation": case.get("support_guard_participation"), "support_central_third_info": case.get("support_central_third_info"), "no_N_used": True, "support_edges_are_context_only": True, "guard_can_belong_to_other_cases": True, "guard_context": case["guard_context"]})
    return applied_records


# =========================================================
# 11) CASO 3 — DOS GUARDAS PERPENDICULARES CON MÁSTIL COMÚN + K
# =========================================================
#
# Geometría esperada:
#
#      free1
#        |
#        |
#      shared -------- free2
#                  \
#                    \
#                       K
#
# Condiciones consolidadas:
#   1) Deben existir dos guardas directas que compartan un mástil.
#   2) Las dos guardas deben formar aproximadamente 90° en planta XY.
#   3) K debe ser un cuarto mástil distinto.
#   4) K debe estar en la zona diagonal/opuesta definida por las dos guardas:
#          dot(K-shared, free1-shared) > 0
#          dot(K-shared, free2-shared) > 0
#   5) La arista shared-K debe existir como cresta base de FASE 3A
#      o haber sido reemplazada previamente desde una cresta base por OG2SM.
#      No se crean aristas nuevas.
#   6) Debe resolverse una esfera de radio S apoyada en:
#          guarda shared-free1 + guarda shared-free2 + punta K.
#   7) La cresta visible creada/reemplazada es shared-K.
#   8) La arista free1-free2 se omite solo si existe y sigue siendo base.
# =========================================================

def make_guard_pair_key_3B(edge1, edge2):
    return tuple(sorted([edge_key(*edge1), edge_key(*edge2)]))


SHARED_GUARD_PERP_ANGLE_TOL_DEG_3B = 3.0
SHARED_GUARD_DIAGONAL_ZONE_TOL_3B = 1e-9


def build_blocked_shared_guard_pair_keys_3B(mast_nodes, guard_wire_inputs):
    """
    Se conserva como diagnóstico/compatibilidad, pero el caso shared+K
    corregido NO descarta automáticamente un par por aparecer en cadenas o ciclos.
    Esto permite que los casos grandes compartan guardas cuando geométricamente
    corresponde.
    """
    blocked = set()

    for ch in find_three_guard_chains_3B(mast_nodes, guard_wire_inputs):
        A, B, C, D = ch["labels"]
        blocked.add(make_guard_pair_key_3B(edge_key(A, B), edge_key(B, C)))
        blocked.add(make_guard_pair_key_3B(edge_key(B, C), edge_key(C, D)))

    for cyc in find_four_guard_closed_cycles_3B(mast_nodes, guard_wire_inputs):
        A, B, C, D = cyc["labels"]
        contour = [edge_key(A, B), edge_key(B, C), edge_key(C, D), edge_key(D, A)]

        for i in range(len(contour)):
            blocked.add(make_guard_pair_key_3B(contour[i], contour[(i + 1) % len(contour)]))

    return blocked


def shared_guard_angle_info_3B(shared, free1, free2):
    """
    Calcula diagnóstico angular entre las dos guardas que comparten mástil.
    """
    P0 = node_xy_3B(shared)
    P1 = node_xy_3B(free1)
    P2 = node_xy_3B(free2)

    v1 = P1 - P0
    v2 = P2 - P0

    n1 = float(np.linalg.norm(v1))
    n2 = float(np.linalg.norm(v2))

    if n1 <= 1e-12 or n2 <= 1e-12:
        return {
            "valid": False,
            "angle_deg": None,
            "dot_abs": None,
            "reason": "zero_length_guard",
        }

    u1 = v1 / n1
    u2 = v2 / n2

    dot = float(np.dot(u1, u2))
    dot_abs = abs(dot)
    dot_abs_clip = max(-1.0, min(1.0, dot_abs))
    angle_deg = float(np.degrees(np.arccos(dot_abs_clip)))

    # Para perpendicularidad: |dot| ≈ 0.
    dot_tol = float(np.sin(np.radians(SHARED_GUARD_PERP_ANGLE_TOL_DEG_3B)))

    return {
        "valid": True,
        "angle_deg": angle_deg,
        "dot": dot,
        "dot_abs": dot_abs,
        "dot_tol": dot_tol,
        "is_perpendicular": bool(dot_abs <= dot_tol),
        "length_1": n1,
        "length_2": n2,
    }


def shared_guards_are_perpendicular_3B(shared, free1, free2):
    info = shared_guard_angle_info_3B(shared, free1, free2)
    return bool(info.get("valid", False) and info.get("is_perpendicular", False)), info


def k_in_diagonal_zone_3B(shared, free1, free2, K, tol=SHARED_GUARD_DIAGONAL_ZONE_TOL_3B):
    """
    Verifica que K esté en la zona diagonal/opuesta definida por las dos guardas.

    Desde el mástil común shared:
      - K debe avanzar en la dirección de free1.
      - K debe avanzar en la dirección de free2.

    Esto evita activar el caso con mástiles ubicados detrás de una de las guardas.
    """
    P0 = node_xy_3B(shared)
    P1 = node_xy_3B(free1)
    P2 = node_xy_3B(free2)
    PK = node_xy_3B(K)

    v1 = P1 - P0
    v2 = P2 - P0
    vk = PK - P0

    n1 = float(np.linalg.norm(v1))
    n2 = float(np.linalg.norm(v2))
    nk = float(np.linalg.norm(vk))

    if n1 <= 1e-12 or n2 <= 1e-12 or nk <= 1e-12:
        return False, {
            "valid": False,
            "reason": "zero_length_vector",
            "proj_1": None,
            "proj_2": None,
        }

    u1 = v1 / n1
    u2 = v2 / n2

    proj_1 = float(np.dot(vk, u1))
    proj_2 = float(np.dot(vk, u2))

    ok = (proj_1 > tol) and (proj_2 > tol)

    return bool(ok), {
        "valid": True,
        "proj_1": proj_1,
        "proj_2": proj_2,
        "tol": tol,
        "ok": bool(ok),
        "shared": shared["label"],
        "free1": free1["label"],
        "free2": free2["label"],
        "K": K["label"],
    }


def shared_k_edge_is_base_replaceable_3B(registry, shared_label, k_label):
    """
    La cresta shared-K solo puede reemplazarse si viene de una cresta base
    de FASE 3A. Se permite también el caso en que OG2SM haya reemplazado antes
    esa misma arista, siempre que el origen previo haya sido base.

    No se pisan casos especiales de mayor prioridad ni cables de guarda.
    """
    key = edge_key(shared_label, k_label)

    if key not in registry:
        return False, {
            "edge": key,
            "exists": False,
            "reason": "shared_k_not_in_registry",
        }

    item = registry[key]
    source = item.get("source", "")
    overwritten_from = item.get("overwritten_from", None)

    if item.get("omit", False):
        return False, {
            "edge": key,
            "exists": True,
            "source": source,
            "overwritten_from": overwritten_from,
            "reason": "edge_omitted",
        }

    if item.get("curve", None) is None:
        return False, {
            "edge": key,
            "exists": True,
            "source": source,
            "overwritten_from": overwritten_from,
            "reason": "edge_without_curve",
        }

    protected_sources = {
        "direct_guard_wire",
        "direct_guard_wire_segment_MN",
        "direct_guard_wire_fragment_NN",
        "four_guard_closed",
        "three_guard_chain",
        "shared_guard_plus_k",
        "independent_guard_lines",
        "independent_guard_lines_subcase2",
        "shared_guard_free_edge_omitted",
    }

    if source in protected_sources:
        return False, {
            "edge": key,
            "exists": True,
            "source": source,
            "overwritten_from": overwritten_from,
            "reason": "protected_special_or_guard_source",
        }

    base_sources = {
        "base_normal_L_le_2S",
        "base_long_L_gt_2S",
        "base_failed",
    }

    if source in base_sources:
        return True, {
            "edge": key,
            "exists": True,
            "source": source,
            "overwritten_from": overwritten_from,
            "reason": "current_source_is_base",
        }

    # Caso especial: OG2SM pudo haber aplicado antes sobre la misma arista.
    # Shared+K tiene prioridad mayor, así que puede recuperarla si originalmente
    # era base. Esto evita que el orden one_guard -> shared bloquee el caso.
    if source == "one_guard_two_support_masts" and overwritten_from in base_sources:
        return True, {
            "edge": key,
            "exists": True,
            "source": source,
            "overwritten_from": overwritten_from,
            "reason": "current_source_is_og2sm_but_original_was_base",
        }

    return False, {
        "edge": key,
        "exists": True,
        "source": source,
        "overwritten_from": overwritten_from,
        "reason": "not_base_replaceable_for_shared_guard_plus_k",
    }


def free_edge_can_be_omitted_for_shared_guard_plus_k_3B(registry, free1_label, free2_label):
    """
    La arista entre extremos libres solo se omite si existe y sigue siendo base.
    No se omiten crestas especiales ni guardas directas.
    """
    key = edge_key(free1_label, free2_label)

    if key not in registry:
        return False, {
            "edge": key,
            "exists": False,
            "reason": "free_edge_not_in_registry",
        }

    item = registry[key]
    source = item.get("source", "")

    if item.get("omit", False):
        return False, {
            "edge": key,
            "exists": True,
            "source": source,
            "reason": "free_edge_already_omitted",
        }

    if registry_edge_is_base_3B(registry, free1_label, free2_label):
        return True, {
            "edge": key,
            "exists": True,
            "source": source,
            "reason": "free_edge_is_base",
        }

    return False, {
        "edge": key,
        "exists": True,
        "source": source,
        "reason": "free_edge_not_base_protected",
    }


def find_shared_guard_special_cases_3B(
    registry,
    mast_nodes,
    guard_wire_inputs,
    sphere_radius,
    common_tetra_edges=None,
    blocked_pair_keys=None,
    log=None
):
    """
    Busca casos shared+K partiendo directamente de pares de guardas
    perpendiculares con mástil común.
    """
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    guard_edges = guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes)

    candidates = []

    for edge1, edge2 in combinations(guard_edges, 2):
        common = sorted(set(edge1).intersection(set(edge2)))

        if len(common) != 1:
            continue

        shared_label = common[0]
        free1_label = edge1[0] if edge1[1] == shared_label else edge1[1]
        free2_label = edge2[0] if edge2[1] == shared_label else edge2[1]

        if shared_label not in node_by_label or free1_label not in node_by_label or free2_label not in node_by_label:
            continue

        shared = node_by_label[shared_label]
        free1 = node_by_label[free1_label]
        free2 = node_by_label[free2_label]

        guard_pair_key = make_guard_pair_key_3B(edge1, edge2)
        is_blocked_by_context = bool(blocked_pair_keys is not None and guard_pair_key in blocked_pair_keys)

        perp_ok, angle_info = shared_guards_are_perpendicular_3B(shared, free1, free2)

        if not perp_ok:
            if log is not None:
                log.append({
                    "edge": None,
                    "source": "shared_guard_plus_k",
                    "status": "skip_shared_guard_pair_not_perpendicular",
                    "guard_pair_key": guard_pair_key,
                    "shared": shared_label,
                    "free1": free1_label,
                    "free2": free2_label,
                    "angle_info": angle_info,
                })
            continue

        if is_blocked_by_context and log is not None:
            log.append({
                "edge": None,
                "source": "shared_guard_plus_k",
                "status": "warn_shared_guard_pair_in_chain_or_closed_cycle_but_not_skipped",
                "guard_pair_key": guard_pair_key,
                "shared": shared_label,
                "free1": free1_label,
                "free2": free2_label,
            })

        for K in mast_nodes:
            k_label = K["label"]

            if k_label in {shared_label, free1_label, free2_label}:
                continue

            in_zone, zone_info = k_in_diagonal_zone_3B(shared, free1, free2, K)

            if not in_zone:
                if log is not None:
                    log.append({
                        "edge": edge_key(shared_label, k_label),
                        "source": "shared_guard_plus_k",
                        "status": "skip_shared_guard_k_not_in_diagonal_zone",
                        "guard_pair_key": guard_pair_key,
                        "shared": shared_label,
                        "free1": free1_label,
                        "free2": free2_label,
                        "K": k_label,
                        "zone_info": zone_info,
                    })
                continue

            shared_k_ok, shared_k_status = shared_k_edge_is_base_replaceable_3B(
                registry,
                shared_label,
                k_label
            )

            if not shared_k_ok:
                if log is not None:
                    log.append({
                        "edge": edge_key(shared_label, k_label),
                        "source": "shared_guard_plus_k",
                        "status": "skip_shared_guard_k_edge_not_base_replaceable",
                        "guard_pair_key": guard_pair_key,
                        "shared": shared_label,
                        "free1": free1_label,
                        "free2": free2_label,
                        "K": k_label,
                        "shared_k_status": shared_k_status,
                    })
                continue

            sol = solve_support_sphere_below_contacts_3B(
                seg1=(node_point_3B(shared), node_point_3B(free1)),
                seg2=(node_point_3B(shared), node_point_3B(free2)),
                point=node_point_3B(K),
                R=sphere_radius,
            )

            if sol is None:
                if log is not None:
                    log.append({
                        "edge": edge_key(shared_label, k_label),
                        "source": "shared_guard_plus_k",
                        "status": "skip_shared_guard_sphere_not_solved",
                        "guard_pair_key": guard_pair_key,
                        "shared": shared_label,
                        "free1": free1_label,
                        "free2": free2_label,
                        "K": k_label,
                        "zone_info": zone_info,
                        "shared_k_status": shared_k_status,
                    })
                continue

            crest_shared_k = lower_support_crest_from_sphere_between_points_3B(
                shared,
                K,
                sol["O"],
                sphere_radius,
                npts=240
            )

            if crest_shared_k is None:
                if log is not None:
                    log.append({
                        "edge": edge_key(shared_label, k_label),
                        "source": "shared_guard_plus_k",
                        "status": "skip_shared_guard_crest_shared_k_not_built",
                        "guard_pair_key": guard_pair_key,
                        "shared": shared_label,
                        "free1": free1_label,
                        "free2": free2_label,
                        "K": k_label,
                    })
                continue

            crest_free = lower_support_crest_from_sphere_between_points_3B(
                free1,
                free2,
                sol["O"],
                sphere_radius,
                npts=240
            )

            candidates.append({
                "crest_free": crest_free,
                "crest_shared_k": crest_shared_k,
                "shared": shared,
                "free1": free1,
                "free2": free2,
                "other": K,
                "free_edge": edge_key(free1_label, free2_label),
                "shared_k_edge": edge_key(shared_label, k_label),
                "sphere": sol,
                "guard_pair_key": guard_pair_key,
                "source_guard_1": edge_key(*edge1),
                "source_guard_2": edge_key(*edge2),
                "angle_info": angle_info,
                "zone_info": zone_info,
                "shared_k_status": shared_k_status,
                "blocked_pair_key_context": is_blocked_by_context,
                "score": sol["O"][2],
            })

    # Si varias combinaciones producen la misma arista shared-K, conservar la esfera más baja.
    best_by_shared_k = {}

    for cand in candidates:
        key = cand["shared_k_edge"]

        if key not in best_by_shared_k or cand["score"] < best_by_shared_k[key]["score"]:
            best_by_shared_k[key] = cand

    return list(best_by_shared_k.values())


def find_shared_guard_special_case_for_edge_3B(
    n1,
    n2,
    mast_nodes,
    guard_wire_inputs,
    sphere_radius,
    common_tetra_edges=None,
    blocked_pair_keys=None
):
    """
    Compatibilidad con versiones antiguas.
    El nuevo flujo ya no busca desde la arista libre n1-n2;
    busca directamente pares de guardas perpendiculares con mástil común.
    """
    return None


def apply_shared_guard_plus_k_overrides_3B(
    registry,
    mast_nodes,
    guard_wire_inputs,
    sphere_radius,
    common_tetra_edges,
    log,
    blocked_pair_keys=None
):
    if not ENABLE_SHARED_GUARD_PLUS_K_CASE:
        return []

    cases = find_shared_guard_special_cases_3B(
        registry=registry,
        mast_nodes=mast_nodes,
        guard_wire_inputs=guard_wire_inputs,
        sphere_radius=sphere_radius,
        common_tetra_edges=common_tetra_edges,
        blocked_pair_keys=blocked_pair_keys,
        log=log,
    )

    applied_records = []

    for case in sorted(cases, key=lambda c: (c["score"], c["shared_k_edge"])):
        shared = case["shared"]
        K = case["other"]
        free1 = case["free1"]
        free2 = case["free2"]

        shared_a, shared_b = case["shared_k_edge"]
        free_a, free_b = case["free_edge"]

        ok = override_registry_edge_3B(
            registry=registry,
            label1=shared_a,
            label2=shared_b,
            curve=case["crest_shared_k"],
            kind="Cresta especial inferior por dos guardas perpendiculares con mástil común + K",
            source="shared_guard_plus_k",
            info={
                "case_type": "shared_guard_plus_k",
                "case": case,
                "role": "shared_to_k",
                "requires_perpendicular_guards": True,
                "requires_k_in_diagonal_zone": True,
                "requires_shared_k_base_from_phase_3A": True,
            },
            log=log,
        )

        if not ok:
            continue

        free_ok, free_status = free_edge_can_be_omitted_for_shared_guard_plus_k_3B(
            registry,
            free_a,
            free_b
        )

        free_action = "none"

        if free_ok:
            if SHOW_SHARED_FREE_EDGE and case.get("crest_free") is not None:
                free_replaced = override_registry_edge_3B(
                    registry=registry,
                    label1=free_a,
                    label2=free_b,
                    curve=case["crest_free"],
                    kind="Cresta especial inferior entre extremos libres de dos guardas con mástil común",
                    source="shared_guard_plus_k",
                    info={
                        "case_type": "shared_guard_plus_k",
                        "case": case,
                        "role": "free_edge",
                    },
                    log=log,
                )
                free_action = "replaced" if free_replaced else "replace_failed"
            else:
                free_omitted = omit_registry_edge_3B(
                    registry=registry,
                    label1=free_a,
                    label2=free_b,
                    kind="Cresta omitida entre extremos libres de dos guardas perpendiculares con mástil común",
                    source="shared_guard_free_edge_omitted",
                    info={
                        "case_type": "shared_guard_plus_k",
                        "case": case,
                        "role": "free_edge_omitted",
                        "omit": True,
                    },
                    log=log,
                )
                free_action = "omitted" if free_omitted else "omit_failed"
        else:
            if log is not None:
                log.append({
                    "edge": edge_key(free_a, free_b),
                    "source": "shared_guard_plus_k",
                    "status": "skip_shared_guard_free_edge_not_base_for_omit",
                    "free_status": free_status,
                    "shared_k_edge": case["shared_k_edge"],
                })
            free_action = "skipped_not_base"

        applied_records.append({
            "shared": shared["label"],
            "free1": free1["label"],
            "free2": free2["label"],
            "K": K["label"],
            "shared_k_edge": case["shared_k_edge"],
            "free_edge": case["free_edge"],
            "source_guard_1": case["source_guard_1"],
            "source_guard_2": case["source_guard_2"],
            "sphere": case["sphere"],
            "angle_info": case["angle_info"],
            "zone_info": case["zone_info"],
            "free_action": free_action,
            "blocked_pair_key_context": case.get("blocked_pair_key_context", False),
        })

        if log is not None:
            log.append({
                "edge": case["shared_k_edge"],
                "source": "shared_guard_plus_k",
                "status": "shared_guard_plus_k_applied_perpendicular_diagonal_zone",
                "shared": shared["label"],
                "free1": free1["label"],
                "free2": free2["label"],
                "K": K["label"],
                "source_guard_1": case["source_guard_1"],
                "source_guard_2": case["source_guard_2"],
                "free_action": free_action,
            })

    return applied_records


# =========================================================
# 12) GUARDAS INDEPENDIENTES — SUBCASOS 1, 2 Y 3
# =========================================================

def guard_edge_length_xy_3B(edge, node_by_label):
    A = node_xy_3B(node_by_label[edge[0]])
    B = node_xy_3B(node_by_label[edge[1]])
    return float(np.linalg.norm(B - A))


def projection_range_of_guard_edge_3B(edge, node_by_label, u):
    A = node_xy_3B(node_by_label[edge[0]])
    B = node_xy_3B(node_by_label[edge[1]])
    sA = float(np.dot(A, u))
    sB = float(np.dot(B, u))
    return min(sA, sB), max(sA, sB)


def independent_module_orientation_generic_3B(seg1, seg2):
    A = seg1["node_start"]
    B = seg1["node_end"]
    C = seg2["node_start"]
    D = seg2["node_end"]
    A_label, B_label, C_label, D_label = A["label"], B["label"], C["label"], D["label"]
    options = [
        {"orientation": "AC_BD_laterals", "guard_edge_1": edge_key(A_label, B_label), "guard_edge_2": edge_key(C_label, D_label), "A": A, "B": B, "C": C, "D": D, "lateral_1": edge_key(A_label, C_label), "lateral_2": edge_key(B_label, D_label), "diagonal_1": edge_key(A_label, D_label), "diagonal_2": edge_key(B_label, C_label), "diag_1_nodes": (A, D, B, C), "diag_2_nodes": (B, C, A, D), "polygon_labels": [A_label, B_label, D_label, C_label], "polygon_xy": np.array([node_xy_3B(A), node_xy_3B(B), node_xy_3B(D), node_xy_3B(C)]), "lateral_score": xy_dist_3B(A, C) + xy_dist_3B(B, D), "diagonal_score": xy_dist_3B(A, D) + xy_dist_3B(B, C), "laterals_cross": segments_cross_xy_3B(node_point_3B(A), node_point_3B(C), node_point_3B(B), node_point_3B(D))},
        {"orientation": "AD_BC_laterals", "guard_edge_1": edge_key(A_label, B_label), "guard_edge_2": edge_key(C_label, D_label), "A": A, "B": B, "C": C, "D": D, "lateral_1": edge_key(A_label, D_label), "lateral_2": edge_key(B_label, C_label), "diagonal_1": edge_key(A_label, C_label), "diagonal_2": edge_key(B_label, D_label), "diag_1_nodes": (A, C, B, D), "diag_2_nodes": (B, D, A, C), "polygon_labels": [A_label, B_label, C_label, D_label], "polygon_xy": np.array([node_xy_3B(A), node_xy_3B(B), node_xy_3B(C), node_xy_3B(D)]), "lateral_score": xy_dist_3B(A, D) + xy_dist_3B(B, C), "diagonal_score": xy_dist_3B(A, C) + xy_dist_3B(B, D), "laterals_cross": segments_cross_xy_3B(node_point_3B(A), node_point_3B(D), node_point_3B(B), node_point_3B(C))},
    ]
    valid = []
    for opt in options:
        area = polygon_area_xy_3B(opt["polygon_xy"])
        opt["polygon_area"] = area
        if area <= 1e-9:
            continue
        if opt["laterals_cross"]:
            continue
        valid.append(opt)
    if not valid:
        return None
    valid.sort(key=lambda o: (o["lateral_score"], o["diagonal_score"], -o["polygon_area"]))
    return valid[0]


def independent_module_orientation_3B(edge1, edge2, node_by_label):
    seg1 = {"node_start": node_by_label[edge1[0]], "node_end": node_by_label[edge1[1]], "edge": edge_key(*edge1)}
    seg2 = {"node_start": node_by_label[edge2[0]], "node_end": node_by_label[edge2[1]], "edge": edge_key(*edge2)}
    return independent_module_orientation_generic_3B(seg1, seg2)


def guard_segment_midpoint_xy_3B(edge, node_by_label):
    return 0.5 * (node_xy_3B(node_by_label[edge[0]]) + node_xy_3B(node_by_label[edge[1]]))


def module_contains_other_guard_3B(module, guard_edges, node_by_label):
    polygon_xy = module["polygon_xy"]
    current_edges = {edge_key(*module["guard_edge_1"]), edge_key(*module["guard_edge_2"])}
    for edge in guard_edges:
        ekey = edge_key(*edge)
        if ekey in current_edges:
            continue
        midpoint = guard_segment_midpoint_xy_3B(edge, node_by_label)
        if point_in_polygon_xy_3B(midpoint, polygon_xy, include_boundary=False):
            return True
    return False


def module_score_3B(module):
    return (float(module.get("lateral_score", np.inf)), float(module.get("diagonal_score", np.inf)), -float(module.get("polygon_area", 0.0)), str(module.get("guard_pair", "")))


def independent_case_1_pair_conditions_3B(edge1, edge2, node_by_label):
    if set(edge1).intersection(set(edge2)):
        return False, {"reason": "guardas_opuestas_comparten_mastil", "edge1": edge1, "edge2": edge2}
    if not are_guard_edges_parallel_xy_3B(edge1, edge2, node_by_label):
        return False, {"reason": "guardas_no_paralelas", "edge1": edge1, "edge2": edge2}
    L1 = guard_edge_length_xy_3B(edge1, node_by_label)
    L2 = guard_edge_length_xy_3B(edge2, node_by_label)
    length_tol = max(ALIGN_TOL_ABS_3B, LENGTH_TOL_REL_3B * max(1.0, abs(L1), abs(L2)))
    if abs(L1 - L2) > length_tol:
        return False, {"reason": "longitudes_diferentes", "edge1": edge1, "edge2": edge2, "L1": L1, "L2": L2, "length_tol": length_tol}
    v = edge_vector_xy_3B(edge1, node_by_label)
    Lv = float(np.linalg.norm(v))
    if Lv <= 1e-12:
        return False, {"reason": "guarda_con_longitud_nula", "edge1": edge1, "edge2": edge2}
    u = v / Lv
    r1 = projection_range_of_guard_edge_3B(edge1, node_by_label, u)
    r2 = projection_range_of_guard_edge_3B(edge2, node_by_label, u)
    same_range = abs(r1[0] - r2[0]) <= ALIGN_TOL_ABS_3B and abs(r1[1] - r2[1]) <= ALIGN_TOL_ABS_3B
    if not same_range:
        return False, {"reason": "no_tienen_mismo_rango_longitudinal", "edge1": edge1, "edge2": edge2, "range1": r1, "range2": r2, "align_tol": ALIGN_TOL_ABS_3B}
    module = independent_module_orientation_3B(edge1, edge2, node_by_label)
    if module is None:
        return False, {"reason": "no_forman_modulo_geometrico_valido", "edge1": edge1, "edge2": edge2}
    return True, {"reason": "subcaso_1_valido_par_local", "edge1": edge1, "edge2": edge2, "L1": L1, "L2": L2, "range1": r1, "range2": r2, "module": module, "mode": "local_pair_regular_grid"}


def detect_independent_guard_modules_regular_3B(mast_nodes, guard_wire_inputs, log=None):
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    guard_edges = guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes)
    candidates = []
    for edge1, edge2 in combinations(guard_edges, 2):
        pair_ok, pair_info = independent_case_1_pair_conditions_3B(edge1, edge2, node_by_label)
        if not pair_ok:
            if log is not None:
                log.append({"edge": None, "source": "independent_guard_lines", "status": "skip_subcase1_pair_not_regular", "guard_pair": make_guard_pair_key_3B(edge1, edge2), "reason": pair_info.get("reason"), "info": pair_info})
            continue
        module = pair_info["module"]
        module["guard_pair"] = make_guard_pair_key_3B(edge1, edge2)
        if module_contains_other_guard_3B(module, guard_edges, node_by_label):
            if log is not None:
                log.append({"edge": None, "source": "independent_guard_lines", "status": "skip_contains_other_guard", "guard_pair": module["guard_pair"], "reason": "otra_guarda_con_midpoint_dentro_del_modulo"})
            continue
        module["independent_subcase"] = INDEPENDENT_SUBCASE_1_PRELIMINAR
        module["independent_subcase_name"] = INDEPENDENT_SUBCASE_NAMES[INDEPENDENT_SUBCASE_1_PRELIMINAR]
        module["independent_subcase_info"] = {"case_1": pair_info, "mode": "local_pair_regular_grid", "allows_lateral_edges_as_guard_wires": True, "allows_adjacent_grid_modules": True, "allows_same_guard_in_multiple_modules": True}
        module["segment_1"] = {"edge": edge_key(*edge1), "node_start": node_by_label[edge1[0]], "node_end": node_by_label[edge1[1]], "source_guard": edge_key(*edge1), "interval_type": "M-M", "is_complete_guard": True}
        module["segment_2"] = {"edge": edge_key(*edge2), "node_start": node_by_label[edge2[0]], "node_end": node_by_label[edge2[1]], "source_guard": edge_key(*edge2), "interval_type": "M-M", "is_complete_guard": True}
        candidates.append(module)
    selected = []
    used_guard_pairs = set()
    for cand in sorted(candidates, key=module_score_3B):
        gp = cand.get("guard_pair")
        if gp in used_guard_pairs:
            continue
        cand["module_index"] = len(selected)
        selected.append(cand)
        used_guard_pairs.add(gp)
    for module in selected:
        if log is not None:
            log.append({"edge": None, "source": "independent_guard_lines", "status": "independent_subcase1_regular_selected", "module_index": module.get("module_index"), "guard_pair": module.get("guard_pair"), "subcase": module.get("independent_subcase"), "subcase_name": module.get("independent_subcase_name"), "mode": "local_pair_regular_grid"})
    return selected


# Subcaso 2

def node_lies_on_guard_xy_3B(node, guard_edge, node_by_label, tol=POINT_ON_GUARD_TOL_3B):
    a, b = guard_edge
    A = node_by_label[a]
    B = node_by_label[b]
    Pxy = node_xy_3B(node)
    Axy = node_xy_3B(A)
    Bxy = node_xy_3B(B)
    lam = point_parameter_on_segment_xy_3B(Pxy, Axy, Bxy)
    if lam is None:
        return False, None, None
    if lam < -tol or lam > 1.0 + tol:
        return False, lam, None
    dist = point_distance_to_segment_by_lambda_xy_3B(Pxy, Axy, Bxy, lam)
    if dist > tol:
        return False, lam, dist
    return True, float(np.clip(lam, 0.0, 1.0)), dist


def build_ordered_guard_points_3B(mast_nodes, tri_nodes, guard_wire_inputs, tol=POINT_ON_GUARD_TOL_3B):
    node_by_label = node_by_label_from_all_nodes_3B(tri_nodes, mast_nodes)
    guard_edges = guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes)
    records = {}
    for guard_edge in guard_edges:
        a, b = guard_edge
        if a not in node_by_label or b not in node_by_label:
            continue
        A = node_by_label[a]
        B = node_by_label[b]
        guard_key = edge_key(a, b)
        entries = [{"lambda": 0.0, "node": A, "label": A["label"], "role": "guard_endpoint_A"}, {"lambda": 1.0, "node": B, "label": B["label"], "role": "guard_endpoint_B"}]
        for n in tri_nodes:
            if node_family_3B(n) != "N":
                continue
            host_key = parse_host_guard_key_3B(n.get("host_guard", None))
            if host_key is not None and host_key != guard_key:
                continue
            ok, lam, dist = node_lies_on_guard_xy_3B(n, guard_edge, node_by_label, tol=tol)
            if not ok:
                continue
            if lam <= tol or lam >= 1.0 - tol:
                continue
            entries.append({"lambda": float(lam), "node": n, "label": n["label"], "role": "N_existing_on_guard", "distance_xy": dist})
        entries.sort(key=lambda e: e["lambda"])
        clean = []
        for e in entries:
            if clean and abs(e["lambda"] - clean[-1]["lambda"]) <= tol:
                prev = clean[-1]
                if str(prev["role"]).startswith("guard_endpoint"):
                    continue
                if str(e["role"]).startswith("guard_endpoint"):
                    clean[-1] = e
                continue
            clean.append(e)
        records[guard_key] = {"guard_edge": guard_key, "node_start": A, "node_end": B, "points": clean}
    return records


def interval_family_name_3B(n1, n2):
    f1 = node_family_3B(n1)
    f2 = node_family_3B(n2)
    fams = sorted([f1, f2])
    if fams == ["M", "M"]:
        return "M-M"
    if fams == ["M", "N"]:
        return "M-N"
    if fams == ["N", "N"]:
        return "N-N"
    return f"{f1}-{f2}"


def build_continuous_guard_intervals_3B(guard_record, min_length_xy=1e-9):
    points = guard_record["points"]
    intervals = []
    guard_A = guard_record["node_start"]
    guard_B = guard_record["node_end"]
    guard_vec_xy = node_xy_3B(guard_B) - node_xy_3B(guard_A)
    guard_len_xy = float(np.linalg.norm(guard_vec_xy))
    if guard_len_xy <= min_length_xy:
        return []
    for i in range(len(points) - 1):
        for j in range(i + 1, len(points)):
            p_i = points[i]
            p_j = points[j]
            n1 = p_i["node"]
            n2 = p_j["node"]
            lam1 = float(p_i["lambda"])
            lam2 = float(p_j["lambda"])
            length_xy = abs(lam2 - lam1) * guard_len_xy
            if length_xy <= min_length_xy:
                continue
            interval_type = interval_family_name_3B(n1, n2)
            intervals.append({"source_guard": guard_record["guard_edge"], "node_start": n1, "node_end": n2, "label_start": n1["label"], "label_end": n2["label"], "edge": edge_key(n1["label"], n2["label"]), "lambda_start": lam1, "lambda_end": lam2, "lambda_span": abs(lam2 - lam1), "length_xy": length_xy, "interval_type": interval_type, "is_complete_guard": (interval_type == "M-M" and abs(lam1) <= 1e-9 and abs(lam2 - 1.0) <= 1e-9), "n_internal_points": max(0, j - i - 1), "point_labels_span": [p["label"] for p in points[i:j + 1]]})
    return intervals


def segment_projection_range_3B(interval, u):
    p1 = node_xy_3B(interval["node_start"])
    p2 = node_xy_3B(interval["node_end"])
    s1 = float(np.dot(p1, u))
    s2 = float(np.dot(p2, u))
    return min(s1, s2), max(s1, s2)


def intervals_have_same_projection_range_3B(int1, int2, u, align_tol=ALIGN_TOL_ABS_3B):
    a1, b1 = segment_projection_range_3B(int1, u)
    a2, b2 = segment_projection_range_3B(int2, u)
    return abs(a1 - a2) <= align_tol and abs(b1 - b2) <= align_tol


def intervals_equal_length_3B(int1, int2, rel_tol=LENGTH_TOL_REL_3B, abs_tol=ALIGN_TOL_ABS_3B):
    L1 = float(int1["length_xy"])
    L2 = float(int2["length_xy"])
    return abs(L1 - L2) <= max(abs_tol, rel_tol * max(L1, L2, 1.0))


def interval_pair_has_N_3B(int1, int2):
    labels = [node_family_3B(int1["node_start"]), node_family_3B(int1["node_end"]), node_family_3B(int2["node_start"]), node_family_3B(int2["node_end"])]
    return "N" in labels


def orient_interval_same_direction_3B(interval, u):
    p1 = node_xy_3B(interval["node_start"])
    p2 = node_xy_3B(interval["node_end"])
    s1 = float(np.dot(p1, u))
    s2 = float(np.dot(p2, u))
    if s1 <= s2:
        return interval
    out = dict(interval)
    out["node_start"] = interval["node_end"]
    out["node_end"] = interval["node_start"]
    out["label_start"] = interval["label_end"]
    out["label_end"] = interval["label_start"]
    out["edge"] = edge_key(out["label_start"], out["label_end"])
    out["lambda_start"] = interval["lambda_end"]
    out["lambda_end"] = interval["lambda_start"]
    return out


def best_common_range_between_segmented_guards_3B(guard_record_1, guard_record_2, node_by_label, log=None):
    edge1 = guard_record_1["guard_edge"]
    edge2 = guard_record_2["guard_edge"]
    if set(edge1).intersection(set(edge2)):
        return None
    if not are_guard_edges_parallel_xy_3B(edge1, edge2, node_by_label):
        return None
    A1 = node_by_label[edge1[0]]
    B1 = node_by_label[edge1[1]]
    v = node_xy_3B(B1) - node_xy_3B(A1)
    L = float(np.linalg.norm(v))
    if L <= 1e-12:
        return None
    u = v / L
    intervals_1 = build_continuous_guard_intervals_3B(guard_record_1)
    intervals_2 = build_continuous_guard_intervals_3B(guard_record_2)
    best = None
    for int1 in intervals_1:
        for int2 in intervals_2:
            if not interval_pair_has_N_3B(int1, int2):
                continue
            if not intervals_equal_length_3B(int1, int2):
                continue
            if not intervals_have_same_projection_range_3B(int1, int2, u):
                continue
            int1o = orient_interval_same_direction_3B(int1, u)
            int2o = orient_interval_same_direction_3B(int2, u)
            module = independent_module_orientation_generic_3B(int1o, int2o)
            if module is None:
                continue
            length_score = min(float(int1o["length_xy"]), float(int2o["length_xy"]))
            cand = {"segment_1": int1o, "segment_2": int2o, "module": module, "length_score": length_score, "projection_range_1": segment_projection_range_3B(int1o, u), "projection_range_2": segment_projection_range_3B(int2o, u), "u": u, "guard_pair": make_guard_pair_key_3B(edge1, edge2)}
            if best is None:
                best = cand
                continue
            old_key = (best["length_score"], best["module"].get("polygon_area", 0.0), -best["module"].get("lateral_score", np.inf))
            new_key = (cand["length_score"], cand["module"].get("polygon_area", 0.0), -cand["module"].get("lateral_score", np.inf))
            if new_key > old_key:
                best = cand
    if best is None:
        if log is not None:
            log.append({"edge": None, "source": "independent_guard_lines_subcase2", "status": "skip_no_common_segmented_range", "guard_pair": make_guard_pair_key_3B(edge1, edge2)})
        return None
    module = best["module"]
    module["guard_pair"] = best["guard_pair"]
    module["segment_1"] = best["segment_1"]
    module["segment_2"] = best["segment_2"]
    module["length_score"] = best["length_score"]
    module["projection_range_1"] = best["projection_range_1"]
    module["projection_range_2"] = best["projection_range_2"]
    module["independent_subcase"] = INDEPENDENT_SUBCASE_2_MAX_COMMON_RANGE
    module["independent_subcase_name"] = INDEPENDENT_SUBCASE_NAMES[INDEPENDENT_SUBCASE_2_MAX_COMMON_RANGE]
    module["independent_subcase_info"] = {"mode": "max_common_range_from_continuous_guard_fragments", "segment_1_type": best["segment_1"]["interval_type"], "segment_2_type": best["segment_2"]["interval_type"], "segment_1_labels_span": best["segment_1"]["point_labels_span"], "segment_2_labels_span": best["segment_2"]["point_labels_span"], "length_xy": best["length_score"]}
    return module


def detect_independent_guard_modules_subcase2_3B(mast_nodes, tri_nodes, guard_wire_inputs, log=None):
    node_by_label = node_by_label_from_all_nodes_3B(tri_nodes, mast_nodes)
    guard_records = build_ordered_guard_points_3B(mast_nodes, tri_nodes, guard_wire_inputs, tol=POINT_ON_GUARD_TOL_3B)
    guard_edges = list(guard_records.keys())
    modules = []
    for edge1, edge2 in combinations(guard_edges, 2):
        if set(edge1).intersection(set(edge2)):
            continue
        module = best_common_range_between_segmented_guards_3B(guard_records[edge1], guard_records[edge2], node_by_label, log=log)
        if module is None:
            continue
        modules.append(module)
    selected = []
    used_guard_pairs = set()
    for module in sorted(modules, key=module_score_3B):
        gp = module.get("guard_pair")
        if gp in used_guard_pairs:
            continue
        module["module_index"] = len(selected)
        selected.append(module)
        used_guard_pairs.add(gp)
    for module in selected:
        if log is not None:
            s1 = module["segment_1"]
            s2 = module["segment_2"]
            log.append({"edge": None, "source": "independent_guard_lines_subcase2", "status": "independent_subcase2_max_common_range_selected", "module_index": module.get("module_index"), "guard_pair": module.get("guard_pair"), "segment_1": s1["edge"], "segment_2": s2["edge"], "segment_1_type": s1["interval_type"], "segment_2_type": s2["interval_type"], "segment_1_span": s1["point_labels_span"], "segment_2_span": s2["point_labels_span"], "length_xy": module.get("length_score")})
    return selected


def detect_independent_guard_exclusions_subcase3_3B(mast_nodes, tri_nodes, guard_wire_inputs, selected_modules, log=None):
    node_by_label = node_by_label_from_all_nodes_3B(tri_nodes, mast_nodes)
    guard_edges = guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes)
    selected_guard_pairs = {m.get("guard_pair") for m in selected_modules if m.get("guard_pair") is not None}
    exclusions = []
    for edge1, edge2 in combinations(guard_edges, 2):
        if set(edge1).intersection(set(edge2)):
            continue
        guard_pair = make_guard_pair_key_3B(edge1, edge2)
        if guard_pair in selected_guard_pairs:
            continue
        if not are_guard_edges_parallel_xy_3B(edge1, edge2, node_by_label):
            continue
        overlap_len = projection_overlap_length_3B(edge1, edge2, node_by_label)
        if overlap_len <= OVERLAP_TOL_3B:
            reason = "only_point_contact_or_no_longitudinal_overlap"
        else:
            reason = "parallel_overlap_exists_but_no_valid_regular_or_segmented_common_range"
        rec = {"guard_pair": guard_pair, "edge_1": edge_key(*edge1), "edge_2": edge_key(*edge2), "subcase": INDEPENDENT_SUBCASE_3_EXCLUSION, "subcase_name": INDEPENDENT_SUBCASE_NAMES[INDEPENDENT_SUBCASE_3_EXCLUSION], "reason": reason, "overlap_length_xy": overlap_len, "no_crests_created": True, "no_overrides_applied": True}
        exclusions.append(rec)
        if log is not None:
            log.append({"edge": None, "source": "independent_guard_lines_subcase3", "status": "excluded_parallel_without_useful_common_range", **rec})
    return exclusions


def build_imaginary_line_family_for_edge_3B(n1, n2, a, b, sphere_radius, npts=220):
    C1, _, _ = base_crest_between_nodes_3B(n1, b, sphere_radius, npts=npts)
    C2, _, _ = base_crest_between_nodes_3B(a, n2, sphere_radius, npts=npts)
    if C1 is None or C2 is None:
        return None
    C1 = orient_curve_xyz_3B(C1, n1, b)
    C2 = orient_curve_xyz_3B(C2, a, n2)
    C1 = resample_curve_xyz_3B(C1, npts=npts)
    C2 = resample_curve_xyz_3B(C2, npts=npts)
    return C1, C2


def build_crest_from_imaginary_lines_3B(n1, n2, C1, C2, npts=220):
    x = np.linspace(n1["x"], n2["x"], npts)
    y = np.linspace(n1["y"], n2["y"], npts)
    z = np.zeros(npts)
    for k in range(npts):
        P = np.array([x[k], y[k]], dtype=float)
        best_d = np.inf
        best_z = None
        for pA, pB in zip(C1, C2):
            _, t, d = closest_point_on_segment_xy_3B(P, pA[:2], pB[:2])
            if d < best_d:
                best_d = d
                best_z = (1.0 - t) * pA[2] + t * pB[2]
        z[k] = 0.0 if best_z is None else best_z
    z = np.maximum(z, 0.0)
    z[0] = n1["z"]
    z[-1] = n2["z"]
    return np.column_stack([x, y, z])


def apply_one_independent_diagonal_3B(registry, n1, n2, a, b, module_info, diagonal_role, sphere_radius, log):
    main_edge = edge_key(n1["label"], n2["label"])
    source = "independent_guard_lines_subcase2" if module_info.get("independent_subcase") == INDEPENDENT_SUBCASE_2_MAX_COMMON_RANGE else "independent_guard_lines"
    if main_edge not in registry:
        log.append({"edge": main_edge, "source": source, "status": "skip_independent_diagonal_not_in_registry", "module_index": module_info.get("module_index"), "diagonal_role": diagonal_role})
        return False
    item = registry[main_edge]
    if item.get("omit", False):
        log.append({"edge": main_edge, "source": source, "status": "skip_independent_diagonal_omitted", "old_source": item.get("source")})
        return False
    if item.get("source") in {"direct_guard_wire", "direct_guard_wire_segment_MN", "direct_guard_wire_fragment_NN"}:
        log.append({"edge": main_edge, "source": source, "status": "skip_independent_diagonal_guard", "old_source": item.get("source")})
        return False
    if registry_priority_3B(item.get("source")) > registry_priority_3B(source):
        log.append({"edge": main_edge, "source": source, "status": "skip_independent_diagonal_higher_priority", "old_source": item.get("source")})
        return False
    family = build_imaginary_line_family_for_edge_3B(n1, n2, a, b, sphere_radius, npts=220)
    if family is None:
        log.append({"edge": main_edge, "source": source, "status": "skip_invalid_imaginary_family"})
        return False
    C1, C2 = family
    crest = build_crest_from_imaginary_lines_3B(n1, n2, C1, C2, npts=220)
    return override_registry_edge_3B(registry, n1["label"], n2["label"], crest, f"Cresta especial por dos guardas independientes — {module_info.get('independent_subcase_name')}", source, {"case_type": "independent_guard_lines", "subcase": module_info.get("independent_subcase"), "subcase_name": module_info.get("independent_subcase_name"), "mode": "imaginary_lines", "module_index": module_info.get("module_index"), "diagonal_role": diagonal_role, "orientation": module_info.get("orientation"), "C1": C1, "C2": C2, "guard_pair": module_info.get("guard_pair"), "segment_1": module_info.get("segment_1"), "segment_2": module_info.get("segment_2"), "no_N_created": True, "no_triangles_created": True}, log)


def apply_independent_guard_overrides_3B(registry, mast_nodes, tri_nodes, guard_wire_inputs, sphere_radius, log):
    if not ENABLE_INDEPENDENT_GUARD_CASE:
        return [], []
    modules_subcase1 = detect_independent_guard_modules_regular_3B(mast_nodes, guard_wire_inputs, log=log)
    subcase1_guard_pairs = {m.get("guard_pair") for m in modules_subcase1 if m.get("guard_pair") is not None}
    modules_subcase2_raw = detect_independent_guard_modules_subcase2_3B(mast_nodes, tri_nodes, guard_wire_inputs, log=log)
    modules_subcase2 = []
    for m in modules_subcase2_raw:
        gp = m.get("guard_pair")
        if gp in subcase1_guard_pairs:
            if log is not None:
                log.append({"edge": None, "source": "independent_guard_lines_subcase2", "status": "skip_subcase2_because_subcase1_already_selected", "guard_pair": gp})
            continue
        modules_subcase2.append(m)
    all_modules = []
    all_modules.extend(modules_subcase1)
    all_modules.extend(modules_subcase2)
    for idx, module in enumerate(all_modules):
        module["module_index"] = idx
    exclusions_subcase3 = detect_independent_guard_exclusions_subcase3_3B(mast_nodes, tri_nodes, guard_wire_inputs, all_modules, log=log)
    for module_info in all_modules:
        n1, n2, a, b = module_info["diag_1_nodes"]
        apply_one_independent_diagonal_3B(registry, n1, n2, a, b, module_info, "diagonal_1", sphere_radius, log)
        n1, n2, a, b = module_info["diag_2_nodes"]
        apply_one_independent_diagonal_3B(registry, n1, n2, a, b, module_info, "diagonal_2", sphere_radius, log)
    return all_modules, exclusions_subcase3


# =========================================================
# 13) APLICAR OVERRIDES
# =========================================================

def apply_guard_overrides_to_registry_3B(base_registry_result, sphere_radius, guard_wire_inputs=None, triangles=None):
    final_result = copy.deepcopy(base_registry_result)
    registry = final_result["crest_registry"]
    mast_nodes = final_result["mast_nodes"]
    common_edges = final_result.get("common_tetra_edges", None)
    log = []
    real_edges = build_real_triangle_edges_3B(triangles or [])
    final_result["real_triangle_edges_3B"] = real_edges
    final_result["triangles_3B"] = triangles or []
    final_result["tri_nodes_3B"] = tri_nodes_3B

    closed_cycle_sets = apply_four_guard_closed_overrides_3B(registry, mast_nodes, guard_wire_inputs, sphere_radius, common_edges, log)
    final_result["four_guard_closed_cycle_sets"] = closed_cycle_sets

    apply_three_guard_chain_overrides_3B(registry, mast_nodes, guard_wire_inputs, sphere_radius, common_edges, closed_cycle_sets, log)

    one_guard_cases = apply_one_guard_two_support_masts_overrides_3B(registry, mast_nodes, guard_wire_inputs, sphere_radius, common_edges, log)
    final_result["one_guard_two_support_mast_cases"] = one_guard_cases

    blocked_pair_keys = build_blocked_shared_guard_pair_keys_3B(mast_nodes, guard_wire_inputs)
    final_result["blocked_shared_guard_pair_keys"] = blocked_pair_keys

    shared_guard_plus_k_cases = apply_shared_guard_plus_k_overrides_3B(
        registry,
        mast_nodes,
        guard_wire_inputs,
        sphere_radius,
        common_edges,
        log,
        blocked_pair_keys=blocked_pair_keys
    )

    final_result["shared_guard_plus_k_cases"] = shared_guard_plus_k_cases

    independent_modules, exclusions_subcase3 = apply_independent_guard_overrides_3B(registry, mast_nodes, tri_nodes_3B, guard_wire_inputs, sphere_radius, log)
    final_result["independent_guard_modules_auto"] = independent_modules
    final_result["excluded_independent_guard_pairs_subcase3"] = exclusions_subcase3
    final_result["crest_override_log"] = log
    return final_result


# =========================================================
# 14) GRÁFICA FINAL
