def registry_color_and_width_3B(item):
    source = item.get("source", "")
    kind = item.get("kind", "")
    edge_family = item.get("edge_family", "")
    if source == "direct_guard_wire":
        return "green", 9
    if source == "direct_guard_wire_segment_MN":
        return "limegreen", 8
    if source == "direct_guard_wire_fragment_NN":
        return "darkgreen", 8
    if source == "four_guard_closed":
        return "dodgerblue", 11
    if source == "three_guard_chain":
        return "deepskyblue", 10
    if source == "shared_guard_plus_k":
        return "cyan", 10
    if source == "shared_guard_free_edge_omitted":
        return "rgba(80,80,80,0.25)", 3
    if source == "one_guard_two_support_masts":
        return "magenta", 9
    if source == "independent_guard_lines":
        return "purple", 9
    if source == "independent_guard_lines_subcase2":
        return "darkviolet", 9
    if "larga" in kind or "suelo" in kind or "L>2S" in kind:
        return "red", 6
    if edge_family == "M-N":
        return "darkorange", 6
    if edge_family == "N-N":
        return "goldenrod", 6
    return "orange", 6


def triangle_border_style_3B(tri_type):
    if tri_type == "M-M-M":
        return "rgba(90,90,90,0.75)", 3
    if tri_type == "M-M-Q":
        return "rgba(255,0,0,0.85)", 3
    if tri_type == "N-N-M":
        return "rgba(0,150,0,0.90)", 3
    if tri_type == "M-M-N":
        return "rgba(128,0,180,0.95)", 3
    return "rgba(0,0,0,0.35)", 3


def add_guard_wire_references_to_fig_3B(fig, mast_nodes, guard_wire_inputs):
    node_by_label = node_by_label_from_masts_3B(mast_nodes)
    for k, (a, b) in enumerate(guard_edges_from_inputs_3B(guard_wire_inputs, mast_nodes)):
        A = node_by_label[a]
        B = node_by_label[b]
        fig.add_trace(go.Scatter3d(x=[A["x"], B["x"]], y=[A["y"], B["y"]], z=[A["z"], B["z"]], mode="lines", line=dict(width=5, color="darkgreen"), name="Guardas seleccionadas" if k == 0 else None, showlegend=(k == 0), hovertemplate=f"Guarda {a}-{b}<extra></extra>"))


def add_triangle_borders_to_fig_3B(fig, triangles):
    ordered = []
    for target in ["M-M-M", "M-M-Q", "N-N-M", "M-M-N", "OTHER"]:
        for tri in triangles:
            t = tri.get("triangle_type", classify_triangle_type_3B(tri))
            if target == "OTHER":
                if t not in ["M-M-M", "M-M-Q", "N-N-M", "M-M-N"]:
                    ordered.append(tri)
            elif t == target:
                ordered.append(tri)
    for tri in ordered:
        n1, n2, n3 = tri["nodes"]
        tri_type = tri.get("triangle_type", classify_triangle_type_3B(tri))
        color, width = triangle_border_style_3B(tri_type)
        labels = tri.get("labels", [n1["label"], n2["label"], n3["label"]])
        hover = f"{format_labels_3B(labels)} | {tri_type}"
        fig.add_trace(go.Scatter3d(x=[n1["x"], n2["x"], n3["x"], n1["x"]], y=[n1["y"], n2["y"], n3["y"], n1["y"]], z=[n1["z"], n2["z"], n3["z"], n1["z"]], mode="lines", line=dict(width=width, color=color), showlegend=False, hoverinfo="text", text=[hover] * 4))


def add_imaginary_lines_from_registry_3B(fig, registry):
    if not SHOW_IMAGINARY_LINES_3B:
        return
    showed_sub1 = False
    showed_sub2 = False
    showed_conn_sub1 = False
    showed_conn_sub2 = False
    for key, item in registry.items():
        source = item.get("source", "")
        if source not in {"independent_guard_lines", "independent_guard_lines_subcase2"}:
            continue
        info = item.get("info", {}) or {}
        C1 = curve_to_array_3B(info.get("C1", None))
        C2 = curve_to_array_3B(info.get("C2", None))
        if C1 is None or C2 is None:
            continue
        if source == "independent_guard_lines":
            color_aux = "rgba(128,0,128,0.42)"
            color_conn = "rgba(128,0,128,0.22)"
            legend_name = "Líneas imaginarias — Subcaso 1"
            connector_name = "Conectores imaginarios — Subcaso 1"
            show_legend_now = not showed_sub1
            showed_sub1 = True
        else:
            color_aux = "rgba(75,0,130,0.50)"
            color_conn = "rgba(75,0,130,0.25)"
            legend_name = "Líneas imaginarias — Subcaso 2"
            connector_name = "Conectores imaginarios — Subcaso 2"
            show_legend_now = not showed_sub2
            showed_sub2 = True
        fig.add_trace(go.Scatter3d(x=C1[:, 0], y=C1[:, 1], z=C1[:, 2], mode="lines", line=dict(width=3, color=color_aux), name=legend_name, showlegend=show_legend_now, hovertemplate=f"Línea imaginaria C1<br>source={source}<br>diagonal={key[0]}-{key[1]}<extra></extra>"))
        fig.add_trace(go.Scatter3d(x=C2[:, 0], y=C2[:, 1], z=C2[:, 2], mode="lines", line=dict(width=3, color=color_aux), name=None, showlegend=False, hovertemplate=f"Línea imaginaria C2<br>source={source}<br>diagonal={key[0]}-{key[1]}<extra></extra>"))
        if SHOW_IMAGINARY_CONNECTORS_3B:
            n = min(len(C1), len(C2))
            step = max(1, int(IMAGINARY_CONNECTOR_STEP_3B))
            for i in range(0, n, step):
                if source == "independent_guard_lines":
                    conn_show = not showed_conn_sub1
                    if conn_show:
                        showed_conn_sub1 = True
                else:
                    conn_show = not showed_conn_sub2
                    if conn_show:
                        showed_conn_sub2 = True
                fig.add_trace(go.Scatter3d(x=[C1[i, 0], C2[i, 0]], y=[C1[i, 1], C2[i, 1]], z=[C1[i, 2], C2[i, 2]], mode="lines", line=dict(width=2, color=color_conn), name=connector_name if conn_show else None, showlegend=conn_show, hovertemplate=f"Conector imaginario<br>source={source}<br>diagonal={key[0]}-{key[1]}<extra></extra>"))


def add_points_to_fig_3B(fig, tri_nodes):
    q_nodes = [n for n in tri_nodes if node_family_3B(n) == "Q"]
    n_nodes = [n for n in tri_nodes if node_family_3B(n) == "N"]
    m_nodes = [n for n in tri_nodes if node_family_3B(n) == "M"]
    for m in m_nodes:
        fig.add_trace(go.Scatter3d(x=[m["x"], m["x"]], y=[m["y"], m["y"]], z=[0.0, m["z"]], mode="lines", line=dict(color="blue", width=8), showlegend=False, hoverinfo="skip"))
        fig.add_trace(go.Scatter3d(x=[m["x"]], y=[m["y"]], z=[m["z"]], mode="markers+text", marker=dict(size=5, color="black"), text=[m["label"]], textposition="top center", showlegend=False))
    if q_nodes:
        fig.add_trace(go.Scatter3d(x=[n["x"] for n in q_nodes], y=[n["y"] for n in q_nodes], z=[n["z"] for n in q_nodes], mode="markers+text", marker=dict(size=6, color="orange"), text=[n["label"] for n in q_nodes], textposition="top center", name="Q activos"))
    if n_nodes:
        fig.add_trace(go.Scatter3d(x=[n["x"] for n in n_nodes], y=[n["y"] for n in n_nodes], z=[n["z"] for n in n_nodes], mode="markers+text", marker=dict(size=9, color="cyan", symbol="diamond"), text=[n["label"] for n in n_nodes], textposition="top center", name="N activos", hovertext=[f"{n['label']}<br>x={float(n['x']):.4f}<br>y={float(n['y']):.4f}<br>z={float(n['z']):.4f}<br>host_guard={n.get('host_guard','')}<br>lambda={n.get('lambda_on_guard', n.get('lambda',''))}" for n in n_nodes], hoverinfo="text"))


def add_ground_plane_to_fig_3B(fig, tri_nodes, sphere_radius):
    xy = np.array([[n["x"], n["y"]] for n in tri_nodes], dtype=float)
    if len(xy) == 0:
        return
    xmin, ymin = xy.min(axis=0) - sphere_radius - 5
    xmax, ymax = xy.max(axis=0) + sphere_radius + 5
    Xg, Yg = np.meshgrid(np.linspace(xmin, xmax, 2), np.linspace(ymin, ymax, 2))
    fig.add_trace(go.Surface(x=Xg, y=Yg, z=np.zeros_like(Xg), opacity=0.08, showscale=False, hoverinfo="skip", name="Suelo"))


def add_manual_legend_3B(fig):
    items = [("Cresta base normal", "orange", 6), ("Cresta larga al suelo", "red", 6), ("Cable de guarda directo", "green", 9), ("Cuadrilátero cerrado", "dodgerblue", 9), ("Tres guardas consecutivas", "deepskyblue", 9), ("Mástil común + K", "cyan", 9), ("Una guarda + dos apoyos", "magenta", 9), ("Independientes subcaso 1", "purple", 9), ("Independientes subcaso 2", "darkviolet", 9), ("NNM", "green", 4), ("MMN", "purple", 4)]
    for name, color, width in items:
        fig.add_trace(go.Scatter3d(x=[None], y=[None], z=[None], mode="lines", line=dict(color=color, width=width), name=name))
    if SHOW_IMAGINARY_LINES_3B:
        fig.add_trace(go.Scatter3d(x=[None], y=[None], z=[None], mode="lines", line=dict(color="rgba(128,0,128,0.42)", width=3), name="Líneas imaginarias"))
    fig.add_trace(go.Scatter3d(x=[None], y=[None], z=[None], mode="markers", marker=dict(color="cyan", size=9, symbol="diamond"), name="Puntos N"))


def plot_crest_registry_final_3B(tri_nodes, triangles, registry_result, sphere_radius, title="FASE 3B — Registro final de crestas"):
    fig = go.Figure()
    registry = registry_result["crest_registry"]
    mast_nodes = registry_result["mast_nodes"]
    add_guard_wire_references_to_fig_3B(fig, mast_nodes, guard_wire_inputs)
    add_triangle_borders_to_fig_3B(fig, triangles)
    add_imaginary_lines_from_registry_3B(fig, registry)
    for key, item in registry.items():
        if item.get("omit", False):
            continue
        C = item.get("curve", None)
        if C is None:
            continue
        C = curve_to_array_3B(C)
        if C is None:
            continue
        color, width = registry_color_and_width_3B(item)
        fig.add_trace(go.Scatter3d(x=C[:, 0], y=C[:, 1], z=C[:, 2], mode="lines", line=dict(width=width, color=color), name=f"{item.get('kind','Cresta')} {key[0]}-{key[1]}", hovertemplate=f"{key[0]}-{key[1]}<br>source={item.get('source')}<br>kind={item.get('kind')}<extra></extra>"))
    add_points_to_fig_3B(fig, tri_nodes)
    add_ground_plane_to_fig_3B(fig, tri_nodes, sphere_radius)
    add_manual_legend_3B(fig)
    fig.update_layout(title=title, scene=dict(xaxis_title="X", yaxis_title="Y", zaxis_title="Z", aspectmode="data"), height=900, showlegend=True)
    fig.show()
    return fig


