# =========================================================
# 2) UTILIDADES DE NODOS / TIPOS
# =========================================================

def is_interpolable_mmm_source(source):
    return source in MMM_INTERPOLABLE_SOURCES


def is_real_mast_node_18(node):
    if node is None or not isinstance(node, dict):
        return False

    node_type = str(node.get("type", ""))
    label = str(node.get("label", ""))

    return (
        node_type in {"mast_top", "M"}
        and not label.startswith("N_")
        and not label.startswith("N_S2")
        and not label.startswith("I_INT_18")
        and not label.startswith("L_LOW_18")
    )


def is_auxiliary_N_node_18(node):
    if node is None or not isinstance(node, dict):
        return False

    node_type = str(node.get("type", ""))
    label = str(node.get("label", ""))

    return (
        node_type in {"auxiliary_N_subcase_2", "N"}
        or label.startswith("N_")
        or label.startswith("N_S2")
    )


def is_intersection_I_node_18(node):
    if node is None or not isinstance(node, dict):
        return False

    node_type = str(node.get("type", ""))
    label = str(node.get("label", ""))

    return node_type == "I" or label.startswith("I_INT_18")


def is_low_L_node_18(node):
    if node is None or not isinstance(node, dict):
        return False

    node_type = str(node.get("type", ""))
    label = str(node.get("label", ""))

    return node_type == "L" or label.startswith("L_LOW_18")


def is_m_like_node(node):
    """
    En este prototipo:
      - M = mástil real.
      - N = punto auxiliar sobre guarda.
      - I = punto de intersección entre crestas, solo para subtetras.
      - L = punto bajo sobre una cresta exterior, solo para split P_low-I.
    """
    return (
        is_real_mast_node_18(node)
        or is_auxiliary_N_node_18(node)
        or is_intersection_I_node_18(node)
        or is_low_L_node_18(node)
    )


def classify_triangle_type_mlike(tri):
    nodes = tri.get("nodes", [])

    n_mast = sum(is_real_mast_node_18(n) for n in nodes)
    n_auxN = sum(is_auxiliary_N_node_18(n) for n in nodes)
    n_I = sum(is_intersection_I_node_18(n) for n in nodes)
    n_L = sum(is_low_L_node_18(n) for n in nodes)
    n_q = sum(str(n.get("type", "")) == "Q" for n in nodes)

    if len(nodes) != 3:
        return "Otro"

    if n_q > 0:
        return "Otro"

    if n_I > 0 or n_L > 0:
        return "subtetra_M_like"

    if n_mast == 3 and n_auxN == 0:
        return "M-M-M"

    if n_mast == 2 and n_auxN == 1:
        return "M-M-N"

    if n_mast == 1 and n_auxN == 2:
        return "N-N-M"

    return "Otro"


def get_mlike_nodes_from_triangle(tri):
    return [node for node in tri.get("nodes", []) if is_m_like_node(node)]


def classify_mmm_sources(source12, source13, source23):
    sources = [source12, source13, source23]

    if all(is_interpolable_mmm_source(src) for src in sources):
        return "INTERPOLABLE_MLIKE_SURFACE"

    return "UNSUPPORTED_MLIKE_SURFACE"


def classify_surface_model(source12, source13, source23):
    sources = [source12, source13, source23]
    source_set = set(sources)

    has_direct = any(src in DIRECT_GUARD_BOUNDARY_SOURCES_18 for src in sources)
    has_base = BASE_NORMAL_SOURCE_18 in source_set
    independent_sources_found = [
        src for src in sources
        if src in INDEPENDENT_GUARD_SOURCES_18
    ]

    if has_direct and has_base and len(independent_sources_found) == 1:
        return "INDEPENDENT_GUARD_REORDER"

    if all(is_interpolable_mmm_source(src) for src in sources):
        return "REGISTRY_BOUNDARY_INTERPOLATION"

    return "UNSUPPORTED"


# =========================================================
# 3) UTILIDADES PARA REGISTRO / CURVAS
# =========================================================

def local_edge_key(a, b):
    fn_edge_key = globals().get("edge_key", None)

    if callable(fn_edge_key):
        return fn_edge_key(a, b)

    return tuple(sorted([a, b]))


def local_node_point(n):
    return np.array([n["x"], n["y"], n["z"]], dtype=float)


def local_curve_to_array(curve):
    if curve is None:
        return None

    fn_curve_to_array = globals().get("curve_to_array", None)

    if callable(fn_curve_to_array):
        C = fn_curve_to_array(curve)
    else:
        if isinstance(curve, tuple) and len(curve) == 3:
            x, y, z = curve
            C = np.column_stack([x, y, z]).astype(float)
        else:
            C = np.asarray(curve, dtype=float)

    if C is None:
        return None

    C = np.asarray(C, dtype=float)

    if C.ndim != 2 or C.shape[1] != 3:
        return None

    if len(C) < 2:
        return None

    C[:, 2] = np.maximum(C[:, 2], 0.0)

    return C


def local_resample_curve_xyz(curve_xyz, npts=120):
    C = np.asarray(curve_xyz, dtype=float)

    if len(C) < 2:
        out = np.repeat(C[:1], npts, axis=0)
        out[:, 2] = np.maximum(out[:, 2], 0.0)
        return out

    d = np.linalg.norm(np.diff(C, axis=0), axis=1)
    s_old = np.concatenate([[0.0], np.cumsum(d)])

    if s_old[-1] < 1e-12:
        out = np.repeat(C[:1], npts, axis=0)
        out[:, 2] = np.maximum(out[:, 2], 0.0)
        return out

    s_old = s_old / s_old[-1]
    s_new = np.linspace(0.0, 1.0, npts)

    x = np.interp(s_new, s_old, C[:, 0])
    y = np.interp(s_new, s_old, C[:, 1])
    z = np.interp(s_new, s_old, C[:, 2])

    out = np.column_stack([x, y, z])
    out[:, 2] = np.maximum(out[:, 2], 0.0)

    return out


def local_orient_curve_xyz(curve_xyz, start_node, end_node):
    C = np.asarray(curve_xyz, dtype=float)

    p_start = local_node_point(start_node)
    p_end = local_node_point(end_node)

    d_normal = (
        np.linalg.norm(C[0] - p_start)
        + np.linalg.norm(C[-1] - p_end)
    )

    d_flip = (
        np.linalg.norm(C[-1] - p_start)
        + np.linalg.norm(C[0] - p_end)
    )

    if d_flip < d_normal:
        C = C[::-1].copy()

    C[:, 2] = np.maximum(C[:, 2], 0.0)

    return C


def get_crest_registry_from_result(registry_result):
    if registry_result is None:
        return None

    if isinstance(registry_result, dict) and "crest_registry" in registry_result:
        return registry_result["crest_registry"]

    return None


def source_effective_18(item):
    if item is None:
        return None

    source = item.get("source", "")

    if source in {
        "fase18_intersection_fragment",
        "fase6X_intersection_fragment",
        "fase18_low_outer_fragment",
    }:
        return item.get("parent_source", source)

    return source


# =========================================================
# 4) FRAGMENTOS VIRTUALES DE GUARDA PARA RELLENO
# =========================================================

def _normalize_host_guard_18(host_guard):
    if host_guard is None:
        return None

    if isinstance(host_guard, str):
        return None

    try:
        if len(host_guard) != 2:
            return None

        return local_edge_key(str(host_guard[0]), str(host_guard[1]))

    except Exception:
        return None


def _point_lambda_on_segment_xy_18(P, A, B):
    P = np.asarray(P, dtype=float)[:2]
    A = np.asarray(A, dtype=float)[:2]
    B = np.asarray(B, dtype=float)[:2]

    AB = B - A
    den = float(np.dot(AB, AB))

    if den <= 1e-12:
        return 0.0

    lam = float(np.dot(P - A, AB) / den)

    return float(np.clip(lam, 0.0, 1.0))


def _straight_curve_between_nodes_18(n1, n2, npts=80):
    P1 = local_node_point(n1)
    P2 = local_node_point(n2)

    t = np.linspace(0.0, 1.0, npts)

    C = (1.0 - t)[:, None] * P1[None, :] + t[:, None] * P2[None, :]
    C[:, 2] = np.maximum(C[:, 2], 0.0)

    return C


def get_special_fill_guard_fragments_from_result_18(registry_result):
    if registry_result is None or not isinstance(registry_result, dict):
        return {}

    fragments = registry_result.get("special_fill_guard_fragments_13B", {})

    if not isinstance(fragments, dict):
        return {}

    out = {}

    for key, item in fragments.items():

        if item is None or not isinstance(item, dict):
            continue

        try:
            if isinstance(key, tuple) and len(key) == 2:
                ekey = local_edge_key(key[0], key[1])
            elif "edge" in item:
                edge = item["edge"]
                ekey = local_edge_key(edge[0], edge[1])
            else:
                nodes = item.get("nodes", None)

                if nodes is None or len(nodes) != 2:
                    continue

                ekey = local_edge_key(nodes[0]["label"], nodes[1]["label"])

        except Exception:
            continue

        nodes = item.get("nodes", None)
        curve = item.get("curve", None)

        if nodes is None or len(nodes) != 2 or curve is None:
            continue

        out[ekey] = {
            **item,
            "edge": ekey,
            "nodes": list(nodes),
            "curve": curve,
            "kind": item.get("kind", "Fragmento virtual de guarda directa para relleno"),
            "source": item.get("source", "direct_guard_wire_fragment"),
            "omit": bool(item.get("omit", False)),
            "virtual": True,
        }

    return out


def get_special_fill_triangles_from_result_18(registry_result):
    if registry_result is None or not isinstance(registry_result, dict):
        return []

    tris = registry_result.get("special_fill_triangles_13B", [])

    if not isinstance(tris, list):
        return []

    out = []

    for tri in tris:

        if not isinstance(tri, dict):
            continue

        tri_type = classify_triangle_type_mlike(tri)

        if tri_type not in {"M-M-M", "M-M-N", "N-N-M"}:
            continue

        out.append(tri)

    return out


def build_virtual_guard_fragment_items_18(registry_result, npts=80):
    explicit_fragments = get_special_fill_guard_fragments_from_result_18(registry_result)

    registry = get_crest_registry_from_result(registry_result)

    if registry is None:
        return explicit_fragments

    direct_guards = {}
    n_nodes_by_host = {}

    for edge, item in registry.items():

        if item.get("omit", False):
            continue

        nodes = item.get("nodes", None)

        if nodes is not None and len(nodes) == 2:
            for node in nodes:
                if is_auxiliary_N_node_18(node):
                    host = _normalize_host_guard_18(node.get("host_guard", None))

                    if host is not None:
                        n_nodes_by_host.setdefault(host, {})[node["label"]] = node

        if (
            item.get("source", "") in {"direct_guard_wire"}
            and item.get("curve", None) is not None
        ):
            if nodes is None or len(nodes) != 2:
                continue

            n1, n2 = nodes

            if not (is_m_like_node(n1) and is_m_like_node(n2)):
                continue

            key = local_edge_key(n1["label"], n2["label"])
            direct_guards[key] = (n1, n2, item)

    for tri in get_special_fill_triangles_from_result_18(registry_result):
        for node in tri.get("nodes", []):
            if not is_auxiliary_N_node_18(node):
                continue

            host = _normalize_host_guard_18(node.get("host_guard", None))

            if host is not None:
                n_nodes_by_host.setdefault(host, {})[node["label"]] = node

    virtual = dict(explicit_fragments)

    for guard_key, (A, B, guard_item) in direct_guards.items():

        interior_nodes = list(n_nodes_by_host.get(guard_key, {}).values())

        if not interior_nodes:
            continue

        Axy = np.array([A["x"], A["y"]], dtype=float)
        Bxy = np.array([B["x"], B["y"]], dtype=float)

        entries = [(0.0, A, "endpoint_A")]

        for N in interior_nodes:
            lam = _point_lambda_on_segment_xy_18(
                P=np.array([N["x"], N["y"]], dtype=float),
                A=Axy,
                B=Bxy
            )

            if lam <= 1e-7 or lam >= 1.0 - 1e-7:
                continue

            entries.append((lam, N, "N"))

        entries.append((1.0, B, "endpoint_B"))
        entries.sort(key=lambda x: x[0])

        dedup = []

        for lam, node, role in entries:
            if dedup and abs(lam - dedup[-1][0]) <= 1e-7:
                if role == "N" and str(dedup[-1][2]).startswith("endpoint"):
                    continue

                dedup[-1] = (lam, node, role)

            else:
                dedup.append((lam, node, role))

        for (lam1, node1, role1), (lam2, node2, role2) in zip(dedup[:-1], dedup[1:]):

            if abs(lam2 - lam1) <= 1e-7:
                continue

            key = local_edge_key(node1["label"], node2["label"])

            if key == guard_key:
                continue

            if key in virtual:
                continue

            C = _straight_curve_between_nodes_18(node1, node2, npts=npts)

            virtual[key] = {
                "edge": key,
                "nodes": [node1, node2],
                "curve": C,
                "kind": "Fragmento virtual de cable de guarda para relleno",
                "source": "direct_guard_wire_fragment",
                "priority": guard_item.get("priority", 100),
                "replaceable": False,
                "omit": False,
                "virtual": True,
                "info": {
                    "case_type": "direct_guard_wire_fragment",
                    "host_guard": guard_key,
                    "lambda_1": float(lam1),
                    "lambda_2": float(lam2),
                },
            }

    return virtual


def get_virtual_guard_fragment_item_for_edge_18(registry_result, label1, label2):
    key = local_edge_key(label1, label2)

    return build_virtual_guard_fragment_items_18(registry_result).get(key, None)


def get_registry_item_for_edge(registry_result, label1, label2):
    registry = get_crest_registry_from_result(registry_result)

    key = local_edge_key(label1, label2)

    if registry is not None:
        item = registry.get(key, None)

        if item is not None:
            return item

    return get_virtual_guard_fragment_item_for_edge_18(
        registry_result,
        label1,
        label2
    )


def get_registry_source_for_edge(registry_result, label1, label2):
    item = get_registry_item_for_edge(registry_result, label1, label2)

    if item is None:
        return None, None

    if item.get("omit", False):
        return item.get("kind", "Frontera omitida"), item.get("source", "omitted")

    if item.get("curve", None) is None:
        return item.get("kind", "Frontera sin curva"), item.get("source", "curve_none")

    return item.get("kind", "Frontera M-like"), item.get("source", "")


def mm_edge_curve_from_registry(n1, n2, registry_result, npts=120):
    item = get_registry_item_for_edge(
        registry_result,
        n1["label"],
        n2["label"]
    )

    if item is None:
        print(f"No existe frontera M-like para {n1['label']}-{n2['label']}.")
        return None, None, None

    if item.get("omit", False):
        print(
            f"La frontera M-like {n1['label']}-{n2['label']} fue omitida. "
            f"source={item.get('source', '')}"
        )
        return None, item.get("kind", "Frontera omitida"), item.get("source", "omitted")

    C = local_curve_to_array(item.get("curve", None))

    if C is None:
        print(f"La frontera M-like {n1['label']}-{n2['label']} existe, pero no tiene curva válida.")
        return None, item.get("kind", "Frontera sin curva"), item.get("source", "curve_none")

    C = local_resample_curve_xyz(C, npts=npts)
    C = local_orient_curve_xyz(C, n1, n2)

    return C, item.get("kind", "Frontera M-like"), item.get("source", "")


def name_from_source_or_kind(kind, source):
    source_names = {
        "base_normal_L_le_2S": "Cresta base normal L≤2S",
        "base_long_L_gt_2S": "Cresta larga L>2S",
        "direct_guard_wire": "Cable de guarda",
        "direct_guard_wire_segment_MN": "Segmento M-N de cable de guarda",
        "direct_guard_wire_fragment_NN": "Fragmento N-N de cable de guarda",
        "direct_guard_wire_fragment": "Fragmento virtual de cable de guarda",
        "independent_guard_lines": "Cresta por guardas independientes",
        "independent_guard_lines_subcase2": "Cresta por guardas independientes subcaso 2",
        "shared_guard_plus_k": "Cresta 2 guardas + mástil K",
        "three_guard_chain": "Cresta cadena de 3 guardas",
        "four_guard_closed": "Cresta cuadrilátero cerrado",
        "one_guard_two_support_masts": "Cresta una guarda + dos mástiles de apoyo",
        "fase18_intersection_fragment": "Fragmento de cresta por intersección",
        "fase18_low_outer_fragment": "Fragmento exterior P_low",
        "fase18_low_to_I_internal_line": "Frontera interna P_low-I",
    }

    return source_names.get(source, kind)


# =========================================================
# 5) SUPERFICIES M-like EXISTENTES
# =========================================================

def triangle_label_set_key(tri):
    return tuple(sorted([n.get("label", "") for n in tri.get("nodes", [])]))


def get_all_mlike_surface_triangles(
    triangles,
    registry_result=None,
    include_virtual_from_registry=True
):
    surface_list = []
    seen = set()

    for tri in triangles:

        tri_type = classify_triangle_type_mlike(tri)

        if tri_type not in {"M-M-M", "M-M-N", "N-N-M"}:
            continue

        key = triangle_label_set_key(tri)

        if key not in seen:
            tri = {
                **tri,
                "mlike_surface_type": tri_type,
                "virtual": bool(tri.get("virtual", False)),
            }

            surface_list.append(tri)
            seen.add(key)

    if include_virtual_from_registry:
        for tri in get_special_fill_triangles_from_result_18(registry_result):

            tri_type = classify_triangle_type_mlike(tri)

            if tri_type not in {"M-M-M", "M-M-N", "N-N-M"}:
                continue

            key = triangle_label_set_key(tri)

            if key not in seen:
                tri = {
                    **tri,
                    "mlike_surface_type": tri_type,
                    "virtual": True,
                }

                surface_list.append(tri)
                seen.add(key)

    return surface_list


def get_all_mmm_triangles(
    triangles,
    registry_result=None,
    include_virtual_from_registry=True
):
    return get_all_mlike_surface_triangles(
        triangles=triangles,
        registry_result=registry_result,
        include_virtual_from_registry=include_virtual_from_registry
    )


def find_one_mlike_surface_triangle(triangles, index=0, registry_result=None):
    surface_list = get_all_mlike_surface_triangles(
        triangles,
        registry_result=registry_result
    )

    if len(surface_list) == 0:
        raise ValueError("No se encontró ningún triángulo M-M-M / M-M-N / N-N-M existente.")

    if index >= len(surface_list):
        raise ValueError(
            f"Solo hay {len(surface_list)} triángulos M-like existentes."
        )

    return surface_list[index]


def find_one_mmm_triangle(triangles, index=0, registry_result=None):
    return find_one_mlike_surface_triangle(
        triangles=triangles,
        index=index,
        registry_result=registry_result
    )


def find_mlike_index_by_labels(triangles, labels, registry_result=None):
    target = set(labels)

    surface_list = get_all_mlike_surface_triangles(
        triangles,
        registry_result=registry_result
    )

    for idx, tri in enumerate(surface_list):
        tri_labels = {m["label"] for m in get_mlike_nodes_from_triangle(tri)}

        if tri_labels == target:
            return idx

    raise ValueError(f"No se encontró una superficie M-like existente con nodos {labels}.")


def find_mmm_index_by_mast_labels(triangles, labels, registry_result=None):
    return find_mlike_index_by_labels(
        triangles=triangles,
        labels=labels,
        registry_result=registry_result
    )


# =========================================================
# 6) REORDENAMIENTO ESPECIAL PARA GUARDAS INDEPENDIENTES
# =========================================================

def get_edge_source_map_for_three_nodes(mast_nodes, registry_result):
    if len(mast_nodes) != 3:
        raise ValueError("Se requieren exactamente 3 nodos M-like.")

    edge_map = {}

    pairs = [
        (mast_nodes[0], mast_nodes[1]),
        (mast_nodes[0], mast_nodes[2]),
        (mast_nodes[1], mast_nodes[2]),
    ]

    for a, b in pairs:
        kind, source = get_registry_source_for_edge(
            registry_result,
            a["label"],
            b["label"]
        )

        key = local_edge_key(a["label"], b["label"])

        edge_map[key] = {
            "node_a": a,
            "node_b": b,
            "kind": kind,
            "source": source,
        }

    return edge_map


def get_source_between_nodes(edge_map, node_a, node_b):
    return edge_map.get(
        local_edge_key(node_a["label"], node_b["label"]),
        {}
    ).get("source", None)


def maybe_reorder_independent_guard_case(mast_nodes, registry_result):
    original_labels = [m["label"] for m in mast_nodes]

    info = {
        "applied": False,
        "reason": "No coincide con el patrón especial de guardas independientes.",
        "original_labels": original_labels,
        "ordered_labels": original_labels,
        "surface_model": "REGISTRY_BOUNDARY_INTERPOLATION",
        "independent_source": None,
    }

    # No reordenar subtetras con punto I ni con punto L.
    if any(is_intersection_I_node_18(m) or is_low_L_node_18(m) for m in mast_nodes):
        info["reason"] = "Subtetra con punto I/L: no se aplica reordenamiento de guardas independientes."
        return mast_nodes, info

    try:
        edge_map = get_edge_source_map_for_three_nodes(
            mast_nodes,
            registry_result
        )

    except Exception as exc:
        info["reason"] = f"No se pudo evaluar reordenamiento: {exc}"
        return mast_nodes, info

    edge_items = list(edge_map.values())

    direct_edges = [
        item for item in edge_items
        if item["source"] in DIRECT_GUARD_BOUNDARY_SOURCES_18
    ]

    base_edges = [
        item for item in edge_items
        if item["source"] == BASE_NORMAL_SOURCE_18
    ]

    independent_edges = [
        item for item in edge_items
        if item["source"] in INDEPENDENT_GUARD_SOURCES_18
    ]

    if not (
        len(direct_edges) == 1
        and len(base_edges) == 1
        and len(independent_edges) == 1
    ):
        return mast_nodes, info

    direct_item = direct_edges[0]
    a = direct_item["node_a"]
    b = direct_item["node_b"]

    direct_labels = {a["label"], b["label"]}

    opposite_candidates = [
        n for n in mast_nodes
        if n["label"] not in direct_labels
    ]

    if len(opposite_candidates) != 1:
        info["reason"] = "No se pudo identificar un único nodo opuesto a la guarda directa/fragmento."
        return mast_nodes, info

    c = opposite_candidates[0]

    source_a_c = get_source_between_nodes(edge_map, a, c)
    source_b_c = get_source_between_nodes(edge_map, b, c)

    if source_a_c == BASE_NORMAL_SOURCE_18 and source_b_c in INDEPENDENT_GUARD_SOURCES_18:
        ordered_nodes = [a, b, c]
        independent_source = source_b_c

    elif source_b_c == BASE_NORMAL_SOURCE_18 and source_a_c in INDEPENDENT_GUARD_SOURCES_18:
        ordered_nodes = [b, a, c]
        independent_source = source_a_c

    else:
        info["reason"] = (
            "El patrón existe, pero no permite forzar "
            "C13=base_normal_L_le_2S y C23=independent_guard_lines/subcase2."
        )
        return mast_nodes, info

    info["applied"] = True
    info["surface_model"] = "INDEPENDENT_GUARD_REORDER"
    info["independent_source"] = independent_source
    info["reason"] = (
        "Reordenamiento aplicado: "
        "C12=guarda directa/fragmento, "
        "C13=base_normal_L_le_2S, "
        f"C23={independent_source}."
    )
    info["ordered_labels"] = [m["label"] for m in ordered_nodes]

    return ordered_nodes, info


# =========================================================
# 7) DIAGNÓSTICO DE EJEMPLOS M-like
# =========================================================

def list_mlike_examples_by_source(triangles, registry_result=None, max_items=None):
    if registry_result is None:
        raise ValueError("Debes pasar registry_result=resultado_crestas_final.")

    surface_list = get_all_mlike_surface_triangles(
        triangles,
        registry_result=registry_result
    )

    if len(surface_list) == 0:
        print("No hay triángulos M-M-M / M-M-N / N-N-M disponibles.")
        return []

    rows = []

    print("=========================================================")
    print("LISTA DE SUPERFICIES M-like DISPONIBLES")
    print("M-M-M / M-M-N / N-N-M")
    print("=========================================================")

    for idx, tri in enumerate(surface_list):

        if max_items is not None and idx >= max_items:
            break

        mast_nodes = get_mlike_nodes_from_triangle(tri)

        if len(mast_nodes) != 3:
            continue

        m1, m2, m3 = mast_nodes

        kind12, source12 = get_registry_source_for_edge(
            registry_result,
            m1["label"],
            m2["label"]
        )

        kind13, source13 = get_registry_source_for_edge(
            registry_result,
            m1["label"],
            m3["label"]
        )

        kind23, source23 = get_registry_source_for_edge(
            registry_result,
            m2["label"],
            m3["label"]
        )

        mlike_class = classify_mmm_sources(source12, source13, source23)
        surface_model = classify_surface_model(source12, source13, source23)

        ordered_nodes, reorder_info = maybe_reorder_independent_guard_case(
            mast_nodes,
            registry_result
        )

        labels_txt = f"{m1['label']}-{m2['label']}-{m3['label']}"
        virtual_txt = "virtual" if tri.get("virtual", False) else "real"
        tri_type = tri.get("mlike_surface_type", classify_triangle_type_mlike(tri))

        print(f"[{idx}] {labels_txt} | tipo={tri_type} | {virtual_txt}")
        print(f"    {m1['label']}-{m2['label']}: {source12}")
        print(f"    {m1['label']}-{m3['label']}: {source13}")
        print(f"    {m2['label']}-{m3['label']}: {source23}")
        print(f"    clasificación: {mlike_class}")
        print(f"    modelo de superficie: {surface_model}")

        if reorder_info["applied"]:
            print(f"    orden de interpolación corregido: {'-'.join(reorder_info['ordered_labels'])}")
            print(f"    fuente independiente usada: {reorder_info.get('independent_source')}")

        print("")

        rows.append({
            "surface_index": idx,
            "labels": labels_txt,
            "type": tri_type,
            "virtual": tri.get("virtual", False),
            "source12": source12,
            "source13": source13,
            "source23": source23,
            "classification": mlike_class,
            "surface_model": surface_model,
            "reorder_applied": reorder_info["applied"],
            "ordered_labels": reorder_info["ordered_labels"],
            "independent_source": reorder_info.get("independent_source"),
        })

    return rows


def list_mmm_examples_by_source(triangles, registry_result=None, max_items=None):
    return list_mlike_examples_by_source(
        triangles=triangles,
        registry_result=registry_result,
        max_items=max_items
    )


# =========================================================
# 8) CONSTRUCCIÓN DEL PARCHE M-like NORMAL
# =========================================================


# =========================================================
# 8A) ANCLA FÍSICA DE ESFERA EN TRES SOPORTES M-LIKE
# PARA PARCHE M-M-M NORMAL Y M-M-N SIN SEGMENTOS DE GUARDA
# =========================================================
#
# Objetivo:
#   En el caso M-M-M común, donde las tres fronteras son crestas base
#   normales entre mástiles reales, se calcula adicionalmente la esfera de
#   radio S apoyada físicamente en las tres puntas superiores de los mástiles.
#
#   También se permite el mismo ajuste para superficies M-M-N, pero SOLO si
#   ninguna de sus tres aristas corresponde a un segmento/cable de guarda
#   directo o fragmentado. Es decir, se excluyen fronteras con fuente:
#
#       - direct_guard_wire
#       - direct_guard_wire_segment_MN
#       - direct_guard_wire_fragment_NN
#       - direct_guard_wire_fragment
#
#   Para M-M-N, la esfera se apoya en los tres puntos M-like de la superficie:
#   dos puntas de mástil y el punto N auxiliar. Esto permite usar el punto bajo
#   físico de la esfera como referencia de interpolación siempre que el parche
#   no esté siendo delimitado por un segmento real de guarda.
#
#   A partir de esa esfera se obtiene:
#       - centro de la esfera;
#       - punto más bajo de la barriga de la esfera P_belly = centro - [0, 0, S];
#       - verificación de si P_belly cae dentro del triángulo en planta XY.
#
#   Si el caso es válido, el parche interpolado se ajusta suavemente hacia la
#   superficie inferior real de esa esfera, pero con peso nulo en las fronteras.
#   Por tanto, las tres crestas C12, C13 y C23 se conservan exactamente.
#
# Qué NO toca:
#   - M-M-N con cualquier arista que sea segmento/cable de guarda;
#   - N-N-M;
#   - subtetras con punto I;
#   - cables de guarda directos o fragmentados;
#   - crest_registry_final;
#   - triangles_final_3B.
# =========================================================

ENABLE_THREE_MAST_PHYSICAL_SPHERE_ANCHOR_18 = True
THREE_MAST_SPHERE_ANCHOR_STRENGTH_18 = 0.85
THREE_MAST_APPLY_ONLY_IF_BELLY_INSIDE_XY_18 = True
THREE_MAST_SPHERE_BOUNDARY_POWER_18 = 0.85

# Alias semántico: se mantiene el nombre anterior de las constantes para no
# romper compatibilidad, pero ahora la ancla puede aplicarse a tres soportes
# M-like: M-M-M normal o M-M-N sin segmentos de guarda.
ENABLE_MLIKE_PHYSICAL_SPHERE_ANCHOR_18 = ENABLE_THREE_MAST_PHYSICAL_SPHERE_ANCHOR_18


def _cross2d_local_18(u, v):
    u = np.asarray(u, dtype=float)
    v = np.asarray(v, dtype=float)
    return float(u[0] * v[1] - u[1] * v[0])


def barycentric_xy_18(Pxy, Axy, Bxy, Cxy, tol=1e-9):
    Pxy = np.asarray(Pxy, dtype=float)
    Axy = np.asarray(Axy, dtype=float)
    Bxy = np.asarray(Bxy, dtype=float)
    Cxy = np.asarray(Cxy, dtype=float)

    v0 = Bxy - Axy
    v1 = Cxy - Axy
    v2 = Pxy - Axy

    den = _cross2d_local_18(v0, v1)

    if abs(den) <= tol:
        return None

    l2 = _cross2d_local_18(v2, v1) / den
    l3 = _cross2d_local_18(v0, v2) / den
    l1 = 1.0 - l2 - l3

    return np.array([l1, l2, l3], dtype=float)


def point_inside_triangle_xy_18(Pxy, Axy, Bxy, Cxy, tol=1e-6):
    bary = barycentric_xy_18(Pxy, Axy, Bxy, Cxy)

    if bary is None:
        return False, None

    inside = np.all(bary >= -tol) and np.all(bary <= 1.0 + tol)

    return bool(inside), bary


def is_mlike_sphere_support_node_18(node):
    """
    Nodo permitido como soporte de la esfera física de relleno:
      - M real;
      - N auxiliar.

    No se permiten Q, I ni L para esta ancla, porque esos puntos pertenecen a
    otros mecanismos de relleno/verificación.
    """
    return is_real_mast_node_18(node) or is_auxiliary_N_node_18(node)


def is_guard_segment_source_for_mlike_anchor_18(source):
    """
    Fuente considerada segmento/cable de guarda para bloquear la ancla física
    en M-M-N.
    """
    return source in DIRECT_GUARD_BOUNDARY_SOURCES_18


def classify_mlike_sphere_anchor_case_18(m1, m2, m3, source12, source13, source23):
    """
    Decide si se permite calcular/aplicar la esfera física de apoyo.

    Reglas:
      1) M-M-M normal:
           - los tres nodos son mástiles reales;
           - las tres fronteras son base_normal_L_le_2S.

      2) M-M-N protegido:
           - dos nodos son M y uno es N;
           - ninguna frontera es segmento/cable de guarda directo o fragmentado.

    En ambos casos se excluyen puntos I/L/Q y se conserva la interpolación
    exacta de las fronteras.
    """
    nodes = [m1, m2, m3]
    sources = [source12, source13, source23]

    n_mast = sum(is_real_mast_node_18(n) for n in nodes)
    n_auxN = sum(is_auxiliary_N_node_18(n) for n in nodes)
    n_I = sum(is_intersection_I_node_18(n) for n in nodes)
    n_L = sum(is_low_L_node_18(n) for n in nodes)
    n_q = sum(str(n.get("type", "")) == "Q" for n in nodes)

    has_only_supported_nodes = all(is_mlike_sphere_support_node_18(n) for n in nodes)
    has_guard_segment_edge = any(is_guard_segment_source_for_mlike_anchor_18(src) for src in sources)

    info = {
        "apply_candidate": False,
        "case": "not_applicable",
        "reason": "No coincide con M-M-M normal ni con M-M-N sin segmentos de guarda.",
        "n_mast": int(n_mast),
        "n_auxN": int(n_auxN),
        "sources": list(sources),
        "has_guard_segment_edge": bool(has_guard_segment_edge),
    }

    if not has_only_supported_nodes or n_I > 0 or n_L > 0 or n_q > 0:
        info["reason"] = "La superficie contiene nodos no permitidos para esta ancla física."
        return info

    is_common_real_MMM_case = (
        n_mast == 3
        and n_auxN == 0
        and source12 == "base_normal_L_le_2S"
        and source13 == "base_normal_L_le_2S"
        and source23 == "base_normal_L_le_2S"
    )

    if is_common_real_MMM_case:
        info.update({
            "apply_candidate": True,
            "case": "M-M-M_normal_base_crests",
            "reason": "M-M-M real con tres crestas base normales.",
        })
        return info

    is_MMN_without_guard_segments = (
        n_mast == 2
        and n_auxN == 1
        and not has_guard_segment_edge
    )

    if is_MMN_without_guard_segments:
        info.update({
            "apply_candidate": True,
            "case": "M-M-N_without_guard_segment_edges",
            "reason": "M-M-N con ninguna arista como segmento/cable de guarda.",
        })
        return info

    if n_mast == 2 and n_auxN == 1 and has_guard_segment_edge:
        info["reason"] = "M-M-N excluido porque al menos una arista es segmento/cable de guarda."

    return info


def compute_three_mast_support_sphere_belly_18(
    m1,
    m2,
    m3,
    sphere_radius,
    clamp_z_nonnegative=True
):
    """
    Calcula la esfera de radio S que pasa por tres soportes M-like.

    En M-M-M los soportes son tres puntas de mástil.
    En M-M-N los soportes son dos puntas de mástil y un punto N auxiliar.

    Retorna el centro físico superior y el punto más bajo de la esfera:
        P_belly = centro - [0, 0, S]
    """
    if not all(is_mlike_sphere_support_node_18(m) for m in [m1, m2, m3]):
        return {
            "status": "not_supported_MLIKE_supports",
            "applied": False,
        }

    R = float(sphere_radius)

    P1 = local_node_point(m1)
    P2 = local_node_point(m2)
    P3 = local_node_point(m3)

    v12 = P2 - P1
    d12 = float(np.linalg.norm(v12))

    if d12 <= 1e-9:
        return {
            "status": "degenerate_edge",
            "applied": False,
        }

    e1 = v12 / d12

    v13 = P3 - P1
    i = float(np.dot(e1, v13))

    temp = v13 - i * e1
    j = float(np.linalg.norm(temp))

    if j <= 1e-9:
        return {
            "status": "collinear_supports",
            "applied": False,
        }

    e2 = temp / j
    e3 = np.cross(e1, e2)

    e3_norm = float(np.linalg.norm(e3))

    if e3_norm <= 1e-9:
        return {
            "status": "invalid_plane_normal",
            "applied": False,
        }

    e3 = e3 / e3_norm

    # Circuncentro del triángulo formado por los tres soportes,
    # expresado en el plano local definido por P1, P2 y P3.
    x_c = d12 / 2.0
    y_c = (i**2 + j**2 - d12 * i) / (2.0 * j)

    circumcenter = P1 + x_c * e1 + y_c * e2
    circumradius_sq = x_c**2 + y_c**2

    if circumradius_sq > R**2 + 1e-8:
        return {
            "status": "sphere_radius_too_small",
            "applied": False,
            "circumradius": float(np.sqrt(circumradius_sq)),
            "sphere_radius": R,
        }

    h = float(np.sqrt(max(R**2 - circumradius_sq, 0.0)))

    center_a = circumcenter + h * e3
    center_b = circumcenter - h * e3

    # Centro físico para el método de la esfera rodante:
    # se elige el centro con mayor coordenada Z.
    center = center_a if center_a[2] >= center_b[2] else center_b

    belly_raw = center - np.array([0.0, 0.0, R], dtype=float)
    belly = belly_raw.copy()

    if clamp_z_nonnegative:
        belly[2] = max(belly[2], 0.0)

    Axy = P1[:2]
    Bxy = P2[:2]
    Cxy = P3[:2]

    inside_xy, bary = point_inside_triangle_xy_18(
        belly[:2],
        Axy,
        Bxy,
        Cxy
    )

    return {
        "status": "ok",
        "applied": False,
        "support_labels": [m1["label"], m2["label"], m3["label"]],
        "support_types": [str(m.get("type", "")) for m in [m1, m2, m3]],
        "sphere_radius": R,
        "center": center,
        "circumcenter": circumcenter,
        "circumradius": float(np.sqrt(circumradius_sq)),
        "belly_point": belly,
        "belly_point_raw": belly_raw,
        "belly_inside_xy": inside_xy,
        "belly_barycentric_xy": bary,
    }


def lower_sphere_z_from_anchor_18(X, Y, sphere_anchor):
    C = np.asarray(sphere_anchor["center"], dtype=float)
    R = float(sphere_anchor["sphere_radius"])

    rho2 = (X - C[0])**2 + (Y - C[1])**2

    Zs = np.full_like(X, np.nan, dtype=float)
    valid = rho2 <= R**2 + 1e-8

    Zs[valid] = C[2] - np.sqrt(np.maximum(R**2 - rho2[valid], 0.0))

    return Zs


def apply_three_mast_sphere_anchor_to_patch_18(
    X,
    Y,
    Z,
    sphere_anchor,
    strength=THREE_MAST_SPHERE_ANCHOR_STRENGTH_18,
    boundary_power=THREE_MAST_SPHERE_BOUNDARY_POWER_18
):
    """
    Ajusta suavemente el parche hacia la superficie inferior de la esfera
    apoyada en tres soportes M-like.

    El peso interno se anula en las tres fronteras. Por eso C12, C13 y C23
    se conservan exactamente.
    """
    if sphere_anchor is None:
        return Z

    if sphere_anchor.get("status") != "ok":
        return Z

    if (
        THREE_MAST_APPLY_ONLY_IF_BELLY_INSIDE_XY_18
        and not sphere_anchor.get("belly_inside_xy", False)
    ):
        return Z

    nt, ns = Z.shape

    s_values = np.linspace(0.0, 1.0, ns)[None, :]
    t_values = np.linspace(0.0, 1.0, nt)[:, None]

    # Coordenadas naturales del parche triangular:
    #   t = 0  -> frontera C12
    #   s = 0  -> frontera C13
    #   s = 1  -> frontera C23
    lam1 = (1.0 - s_values) * (1.0 - t_values)
    lam2 = s_values * (1.0 - t_values)
    lam3 = t_values

    # Burbuja interior:
    #   - vale 0 en las tres fronteras;
    #   - se acerca a 1 hacia el interior.
    bubble = 27.0 * lam1 * lam2 * lam3
    bubble = np.clip(bubble, 0.0, 1.0)
    bubble = np.power(bubble, boundary_power)

    Z_sphere = lower_sphere_z_from_anchor_18(X, Y, sphere_anchor)

    mask = np.isfinite(Z_sphere) & np.isfinite(Z)

    Z_new = Z.copy()

    w = strength * bubble
    w = np.clip(w, 0.0, 1.0)

    Z_new[mask] = (
        (1.0 - w[mask]) * Z[mask]
        + w[mask] * Z_sphere[mask]
    )

    Z_new = np.maximum(Z_new, 0.0)

    sphere_anchor["applied"] = True

    return Z_new

def build_mmm_patch_from_boundaries(
    C12,
    C13,
    C23,
    ns=90,
    nt=90,
    preserve_nonnegative=True,
    sphere_anchor_3mast=None,
    apply_sphere_anchor=True
):
    C12 = local_resample_curve_xyz(np.asarray(C12, dtype=float), ns)
    C13 = local_resample_curve_xyz(np.asarray(C13, dtype=float), nt)
    C23 = local_resample_curve_xyz(np.asarray(C23, dtype=float), nt)

    X = np.zeros((nt, ns))
    Y = np.zeros((nt, ns))
    Z = np.zeros((nt, ns))

    for it in range(nt):
        t = it / (nt - 1)

        Lt = C13[it]
        Rt = C23[it]

        for is_ in range(ns):
            s = is_ / (ns - 1)

            Cs = C12[is_]

            base_lr = (1.0 - s) * Lt + s * Rt
            top_linear = (1.0 - s) * C12[0] + s * C12[-1]
            top_correction = (1.0 - t) * (Cs - top_linear)

            P = base_lr + top_correction

            X[it, is_] = P[0]
            Y[it, is_] = P[1]
            Z[it, is_] = P[2]

    X[0, :] = C12[:, 0]
    Y[0, :] = C12[:, 1]
    Z[0, :] = C12[:, 2]

    X[:, 0] = C13[:, 0]
    Y[:, 0] = C13[:, 1]
    Z[:, 0] = C13[:, 2]

    X[:, -1] = C23[:, 0]
    Y[:, -1] = C23[:, 1]
    Z[:, -1] = C23[:, 2]

    if apply_sphere_anchor and sphere_anchor_3mast is not None:
        Z = apply_three_mast_sphere_anchor_to_patch_18(
            X=X,
            Y=Y,
            Z=Z,
            sphere_anchor=sphere_anchor_3mast
        )

        # Reimponer fronteras exactas por seguridad numérica.
        X[0, :] = C12[:, 0]
        Y[0, :] = C12[:, 1]
        Z[0, :] = C12[:, 2]

        X[:, 0] = C13[:, 0]
        Y[:, 0] = C13[:, 1]
        Z[:, 0] = C13[:, 2]

        X[:, -1] = C23[:, 0]
        Y[:, -1] = C23[:, 1]
        Z[:, -1] = C23[:, 2]

    if preserve_nonnegative:
        Z = np.maximum(Z, 0.0)

    return X, Y, Z


def build_mlike_patch_from_three_boundaries(
    m1,
    m2,
    m3,
    sphere_radius,
    guard_wire_inputs=None,
    registry_result=None,
    ns=90,
    nt=90
):
    if registry_result is None:
        raise ValueError("Debes pasar registry_result=resultado_crestas_final para construir la superficie M-like.")

    C12_raw, kind12, source12 = mm_edge_curve_from_registry(
        m1,
        m2,
        registry_result,
        npts=ns
    )

    C13_raw, kind13, source13 = mm_edge_curve_from_registry(
        m1,
        m3,
        registry_result,
        npts=nt
    )

    C23_raw, kind23, source23 = mm_edge_curve_from_registry(
        m2,
        m3,
        registry_result,
        npts=nt
    )

    if C12_raw is None or C13_raw is None or C23_raw is None:
        return None

    C12 = local_resample_curve_xyz(
        local_orient_curve_xyz(C12_raw, m1, m2),
        ns
    )

    C13 = local_resample_curve_xyz(
        local_orient_curve_xyz(C13_raw, m1, m3),
        nt
    )

    C23 = local_resample_curve_xyz(
        local_orient_curve_xyz(C23_raw, m2, m3),
        nt
    )

    mlike_class = classify_mmm_sources(source12, source13, source23)
    surface_model = classify_surface_model(source12, source13, source23)

    sphere_anchor_3mast = None
    apply_three_mast_anchor = False

    # Caso protegido de ancla física:
    #   1) M-M-M real con tres crestas base normales.
    #   2) M-M-N con ninguna arista como segmento/cable de guarda.
    sphere_anchor_case_info = classify_mlike_sphere_anchor_case_18(
        m1=m1,
        m2=m2,
        m3=m3,
        source12=source12,
        source13=source13,
        source23=source23
    )

    if (
        ENABLE_THREE_MAST_PHYSICAL_SPHERE_ANCHOR_18
        and sphere_anchor_case_info.get("apply_candidate", False)
    ):
        sphere_anchor_3mast = compute_three_mast_support_sphere_belly_18(
            m1=m1,
            m2=m2,
            m3=m3,
            sphere_radius=sphere_radius,
            clamp_z_nonnegative=True
        )

        if isinstance(sphere_anchor_3mast, dict):
            sphere_anchor_3mast["anchor_case"] = sphere_anchor_case_info.get("case")
            sphere_anchor_3mast["anchor_case_info"] = sphere_anchor_case_info

        apply_three_mast_anchor = (
            sphere_anchor_3mast.get("status") == "ok"
            and (
                sphere_anchor_3mast.get("belly_inside_xy", False)
                or not THREE_MAST_APPLY_ONLY_IF_BELLY_INSIDE_XY_18
            )
        )

    if mlike_class == "INTERPOLABLE_MLIKE_SURFACE":
        X, Y, Z = build_mmm_patch_from_boundaries(
            C12=C12,
            C13=C13,
            C23=C23,
            ns=ns,
            nt=nt,
            sphere_anchor_3mast=sphere_anchor_3mast if apply_three_mast_anchor else None,
            apply_sphere_anchor=apply_three_mast_anchor
        )
        status = "built"

        if apply_three_mast_anchor:
            surface_model = f"{surface_model}_WITH_MLIKE_SPHERE_ANCHOR"

    else:
        X = Y = Z = None
        status = "unsupported"

    return {
        "status": status,
        "classification": mlike_class,
        "surface_model": surface_model,
        "X": X,
        "Y": Y,
        "Z": Z,
        "C12": C12,
        "C13": C13,
        "C23": C23,
        "kind12": kind12,
        "kind13": kind13,
        "kind23": kind23,
        "source12": source12,
        "source13": source13,
        "source23": source23,
        "three_mast_sphere_anchor": sphere_anchor_3mast,
        "three_mast_sphere_anchor_applied": apply_three_mast_anchor,
        "mlike_sphere_anchor": sphere_anchor_3mast,
        "mlike_sphere_anchor_applied": apply_three_mast_anchor,
        "mlike_sphere_anchor_case": sphere_anchor_case_info,
    }


def build_mmm_patch_from_three_crests(
    m1,
    m2,
    m3,
    sphere_radius,
    guard_wire_inputs=None,
    registry_result=None,
    ns=90,
    nt=90
):
    return build_mlike_patch_from_three_boundaries(
        m1=m1,
        m2=m2,
        m3=m3,
        sphere_radius=sphere_radius,
        guard_wire_inputs=guard_wire_inputs,
        registry_result=registry_result,
        ns=ns,
        nt=nt
    )


# =========================================================
# 9) GRÁFICA DE UN PARCHE M-like NORMAL
# =========================================================

def plot_one_mlike_patch(
    triangles,
    sphere_radius,
    guard_wire_inputs=None,
    registry_result=None,
    surface_index=0,
    ns=90,
    nt=90,
    show_internal_mesh=True,
    show_boundary_only_when_unsupported=True
):
    tri = find_one_mlike_surface_triangle(
        triangles,
        index=surface_index,
        registry_result=registry_result
    )

    mast_nodes_original = get_mlike_nodes_from_triangle(tri)

    if len(mast_nodes_original) != 3:
        raise ValueError("El triángulo seleccionado no es M-like válido.")

    mast_nodes_ordered, reorder_info = maybe_reorder_independent_guard_case(
        mast_nodes_original,
        registry_result
    )

    m1, m2, m3 = mast_nodes_ordered

    built = build_mlike_patch_from_three_boundaries(
        m1=m1,
        m2=m2,
        m3=m3,
        sphere_radius=sphere_radius,
        guard_wire_inputs=guard_wire_inputs,
        registry_result=registry_result,
        ns=ns,
        nt=nt
    )

    if built is None:
        raise ValueError("No se pudo construir ni diagnosticar el parche M-like.")

    X = built["X"]
    Y = built["Y"]
    Z = built["Z"]

    C12 = built["C12"]
    C13 = built["C13"]
    C23 = built["C23"]

    kind12 = built["kind12"]
    kind13 = built["kind13"]
    kind23 = built["kind23"]

    source12 = built["source12"]
    source13 = built["source13"]
    source23 = built["source23"]

    status = built["status"]
    classification = built["classification"]
    surface_model = built["surface_model"]

    tri_type = tri.get("mlike_surface_type", classify_triangle_type_mlike(tri))

    fig = go.Figure()

    if status == "built":
        Z = np.maximum(Z, 0.0)

        fig.add_trace(go.Surface(
            x=X,
            y=Y,
            z=Z,
            opacity=0.75,
            showscale=False,
            name=f"Parche {tri_type} | {surface_model}"
        ))

        if show_internal_mesh:
            step_t = max(1, nt // 10)
            step_s = max(1, ns // 10)

            for row in range(0, nt, step_t):
                fig.add_trace(go.Scatter3d(
                    x=X[row, :],
                    y=Y[row, :],
                    z=Z[row, :],
                    mode="lines",
                    line=dict(width=2),
                    showlegend=False
                ))

            for col in range(0, ns, step_s):
                fig.add_trace(go.Scatter3d(
                    x=X[:, col],
                    y=Y[:, col],
                    z=Z[:, col],
                    mode="lines",
                    line=dict(width=2),
                    showlegend=False
                ))

    else:
        if not show_boundary_only_when_unsupported:
            raise ValueError("La superficie M-like seleccionada contiene una frontera no soportada.")

    name12 = name_from_source_or_kind(kind12, source12)
    name13 = name_from_source_or_kind(kind13, source13)
    name23 = name_from_source_or_kind(kind23, source23)

    for C, name, a, b in [
        (C12, name12, m1, m2),
        (C13, name13, m1, m3),
        (C23, name23, m2, m3),
    ]:
        fig.add_trace(go.Scatter3d(
            x=C[:, 0],
            y=C[:, 1],
            z=C[:, 2],
            mode="lines",
            line=dict(width=8),
            name=f"Frontera | {name} {a['label']}-{b['label']}"
        ))

    for m in [m1, m2, m3]:
        fig.add_trace(go.Scatter3d(
            x=[m["x"], m["x"]],
            y=[m["y"], m["y"]],
            z=[0.0, m["z"]],
            mode="lines+markers+text",
            line=dict(width=8),
            marker=dict(size=5),
            text=["", m["label"]],
            textposition="top center",
            name=m["label"]
        ))

    pts_x = [m1["x"], m2["x"], m3["x"]]
    pts_y = [m1["y"], m2["y"], m3["y"]]

    pad = 8

    Xg, Yg = np.meshgrid(
        np.linspace(min(pts_x) - pad, max(pts_x) + pad, 2),
        np.linspace(min(pts_y) - pad, max(pts_y) + pad, 2)
    )

    fig.add_trace(go.Surface(
        x=Xg,
        y=Yg,
        z=np.zeros_like(Xg),
        opacity=0.12,
        showscale=False,
        hoverinfo="skip",
        name="Plano z=0"
    ))

    title_status = "RELLENADO" if status == "built" else "NO RELLENADO | Fuente no soportada"

    fig.update_layout(
        title=(
            f"EJEMPLO 1 — {title_status}: {tri_type} "
            f"{m1['label']}-{m2['label']}-{m3['label']} | {surface_model}"
        ),
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=900,
        showlegend=True
    )

    print("=========================================================")
    print("EJEMPLO 1 — DIAGNÓSTICO DE SUPERFICIE M-like")
    print("=========================================================")
    print(f"surface_index = {surface_index}")
    print(f"Tipo de superficie: {tri_type}")
    print(f"Triángulo original: {'-'.join(reorder_info['original_labels'])}")
    print(f"Orden usado para interpolar: {'-'.join(reorder_info['ordered_labels'])}")
    print(f"Virtual desde registro: {tri.get('virtual', False)}")
    print(f"Clasificación: {classification}")
    print(f"Modelo de superficie: {surface_model}")
    print(f"Estado: {status}")

    if reorder_info["applied"]:
        print("")
        print("Reordenamiento especial aplicado:")
        print(f"  Motivo: {reorder_info['reason']}")
        print(f"  Fuente independiente: {reorder_info.get('independent_source')}")

    print("")
    print("Fronteras usadas en la interpolación:")
    print(f"  C12 = {m1['label']}-{m2['label']}: {kind12} | source={source12}")
    print(f"  C13 = {m1['label']}-{m3['label']}: {kind13} | source={source13}")
    print(f"  C23 = {m2['label']}-{m3['label']}: {kind23} | source={source23}")
    print("=========================================================")

    fig.show()

    return built


def plot_one_mmm_patch(
    triangles,
    sphere_radius,
    guard_wire_inputs=None,
    registry_result=None,
    mmm_index=0,
    ns=90,
    nt=90,
    show_internal_mesh=True,
    show_boundary_only_when_unsupported=True
):
    return plot_one_mlike_patch(
        triangles=triangles,
        sphere_radius=sphere_radius,
        guard_wire_inputs=guard_wire_inputs,
        registry_result=registry_result,
        surface_index=mmm_index,
        ns=ns,
        nt=nt,
        show_internal_mesh=show_internal_mesh,
        show_boundary_only_when_unsupported=show_boundary_only_when_unsupported
    )


# =========================================================
# 10) SUBTETRAS POR CRUCE DE CRESTAS — PROTOTIPO
# =========================================================

def cross2d_18(u, v):
    return u[0] * v[1] - u[1] * v[0]


def bbox_segments_overlap_xy_18(a, b, c, d, tol=1e-9):
    a = np.asarray(a, dtype=float)[:2]
    b = np.asarray(b, dtype=float)[:2]
    c = np.asarray(c, dtype=float)[:2]
    d = np.asarray(d, dtype=float)[:2]

    if max(a[0], b[0]) < min(c[0], d[0]) - tol:
        return False
    if max(c[0], d[0]) < min(a[0], b[0]) - tol:
        return False
    if max(a[1], b[1]) < min(c[1], d[1]) - tol:
        return False
    if max(c[1], d[1]) < min(a[1], b[1]) - tol:
        return False

    return True


def segment_intersection_xy_proper_18(
    a,
    b,
    c,
    d,
    tol=1e-9,
    interior_tol=1e-4
):
    a = np.asarray(a, dtype=float)[:2]
    b = np.asarray(b, dtype=float)[:2]
    c = np.asarray(c, dtype=float)[:2]
    d = np.asarray(d, dtype=float)[:2]

    if not bbox_segments_overlap_xy_18(a, b, c, d, tol=tol):
        return False, None, None, None

    r = b - a
    s = d - c
    qmp = c - a

    rxs = cross2d_18(r, s)

    if abs(rxs) <= tol:
        return False, None, None, None

    t = cross2d_18(qmp, s) / rxs
    u = cross2d_18(qmp, r) / rxs

    if (
        interior_tol < t < 1.0 - interior_tol
        and interior_tol < u < 1.0 - interior_tol
    ):
        P = a + t * r
        return True, P, t, u

    return False, None, None, None


def curve_pair_first_proper_crossing_xy_18(C1, C2):
    C1 = np.asarray(C1, dtype=float)
    C2 = np.asarray(C2, dtype=float)

    if len(C1) < 2 or len(C2) < 2:
        return None

    xy1 = C1[:, :2]
    xy2 = C2[:, :2]

    if np.nanmax(xy1[:, 0]) < np.nanmin(xy2[:, 0]) - INTERSECTION_TOL_18:
        return None
    if np.nanmax(xy2[:, 0]) < np.nanmin(xy1[:, 0]) - INTERSECTION_TOL_18:
        return None
    if np.nanmax(xy1[:, 1]) < np.nanmin(xy2[:, 1]) - INTERSECTION_TOL_18:
        return None
    if np.nanmax(xy2[:, 1]) < np.nanmin(xy1[:, 1]) - INTERSECTION_TOL_18:
        return None

    for i in range(len(xy1) - 1):
        a = xy1[i]
        b = xy1[i + 1]

        for j in range(len(xy2) - 1):
            c = xy2[j]
            d = xy2[j + 1]

            ok, Pxy, t, u = segment_intersection_xy_proper_18(
                a=a,
                b=b,
                c=c,
                d=d,
                tol=INTERSECTION_TOL_18,
                interior_tol=INTERSECTION_INTERIOR_TOL_18
            )

            if not ok:
                continue

            P1 = C1[i] + t * (C1[i + 1] - C1[i])
            P2 = C2[j] + u * (C2[j + 1] - C2[j])

            xI = float(Pxy[0])
            yI = float(Pxy[1])

            if INTERSECTION_Z_POLICY_18 == "min":
                zI = float(min(P1[2], P2[2]))
            elif INTERSECTION_Z_POLICY_18 == "average":
                zI = float(0.5 * (P1[2] + P2[2]))
            elif INTERSECTION_Z_POLICY_18 == "first":
                zI = float(P1[2])
            elif INTERSECTION_Z_POLICY_18 == "second":
                zI = float(P2[2])
            else:
                zI = float(min(P1[2], P2[2]))

            PI = np.array([xI, yI, max(zI, 0.0)], dtype=float)

            return {
                "point_xy": np.array([xI, yI], dtype=float),
                "point_3d": PI,
                "i": i,
                "j": j,
                "t": float(t),
                "u": float(u),
                "P1": P1,
                "P2": P2,
            }

    return None


def split_curve_at_crossing_18(C, seg_idx, local_t, P_insert):
    C = np.asarray(C, dtype=float)
    P_insert = np.asarray(P_insert, dtype=float)

    P_insert[2] = max(P_insert[2], 0.0)

    left = np.vstack([
        C[:seg_idx + 1],
        P_insert[None, :]
    ])

    right = np.vstack([
        P_insert[None, :],
        C[seg_idx + 1:]
    ])

    left[:, 2] = np.maximum(left[:, 2], 0.0)
    right[:, 2] = np.maximum(right[:, 2], 0.0)

    return left, right


def collect_node_by_label_18(triangles, registry_result):
    node_by_label = {}

    for tri in triangles:
        for n in tri.get("nodes", []):
            if isinstance(n, dict) and "label" in n:
                node_by_label[n["label"]] = n

    registry = get_crest_registry_from_result(registry_result)

    if registry is not None:
        for item in registry.values():
            for n in item.get("nodes", []) or []:
                if isinstance(n, dict) and "label" in n:
                    node_by_label[n["label"]] = n

    for tri in get_special_fill_triangles_from_result_18(registry_result):
        for n in tri.get("nodes", []):
            if isinstance(n, dict) and "label" in n:
                node_by_label[n["label"]] = n

    return node_by_label


def item_is_usable_for_subtetra_demo_18(item):
    if item is None:
        return False

    if item.get("omit", False):
        return False

    if item.get("curve", None) is None:
        return False

    source = item.get("source", "")

    if source in INDEPENDENT_GUARD_SOURCES_18:
        return False

    if source not in SUBTETRA_INTERSECTION_ALLOWED_SOURCES_18:
        return False

    return True


def collect_active_boundary_items_for_subtetra_demo_18(
    triangles,
    registry_result
):
    registry = get_crest_registry_from_result(registry_result)

    if registry is None:
        return []

    node_by_label = collect_node_by_label_18(
        triangles=triangles,
        registry_result=registry_result
    )

    items = []

    for edge, item in registry.items():
        if not item_is_usable_for_subtetra_demo_18(item):
            continue

        if len(edge) != 2:
            continue

        a, b = edge

        if a not in node_by_label or b not in node_by_label:
            continue

        n1 = node_by_label[a]
        n2 = node_by_label[b]

        C = local_curve_to_array(item.get("curve", None))

        if C is None:
            continue

        C = local_orient_curve_xyz(C, n1, n2)

        items.append({
            "edge": local_edge_key(a, b),
            "label_a": a,
            "label_b": b,
            "node_a": n1,
            "node_b": n2,
            "item": item,
            "source": item.get("source", ""),
            "kind": item.get("kind", ""),
            "curve": C,
        })

    return items


def cyclic_order_labels_around_point_18(labels, node_by_label, center_xy):
    def angle_of_label(lbl):
        n = node_by_label[lbl]
        return np.arctan2(n["y"] - center_xy[1], n["x"] - center_xy[0])

    return sorted(labels, key=angle_of_label)


def endpoints_are_opposite_in_cycle_18(edge, ordered_labels):
    a, b = edge
    pos = {lbl: i for i, lbl in enumerate(ordered_labels)}

    if a not in pos or b not in pos:
        return False

    d = abs(pos[a] - pos[b])
    d = min(d, len(ordered_labels) - d)

    return d == 2


def get_outer_edges_from_ordered_quad_18(ordered_labels):
    out = []

    for i in range(4):
        a = ordered_labels[i]
        b = ordered_labels[(i + 1) % 4]
        out.append(local_edge_key(a, b))

    return out


def detect_subtetra_intersection_cases_18(
    triangles,
    registry_result
):
    registry = get_crest_registry_from_result(registry_result)

    if registry is None:
        return []

    node_by_label = collect_node_by_label_18(
        triangles=triangles,
        registry_result=registry_result
    )

    items = collect_active_boundary_items_for_subtetra_demo_18(
        triangles=triangles,
        registry_result=registry_result
    )

    cases = []
    seen = set()

    for i in range(len(items)):
        item1 = items[i]
        edge1 = item1["edge"]

        for j in range(i + 1, len(items)):
            item2 = items[j]
            edge2 = item2["edge"]

            if (
                item1["source"] in INDEPENDENT_GUARD_SOURCES_18
                or item2["source"] in INDEPENDENT_GUARD_SOURCES_18
            ):
                continue

            labels1 = set(edge1)
            labels2 = set(edge2)

            if len(labels1.intersection(labels2)) > 0:
                continue

            labels_quad = list(labels1 | labels2)

            if len(labels_quad) != 4:
                continue

            crossing = curve_pair_first_proper_crossing_xy_18(
                item1["curve"],
                item2["curve"]
            )

            if crossing is None:
                continue

            ordered_labels = cyclic_order_labels_around_point_18(
                labels=labels_quad,
                node_by_label=node_by_label,
                center_xy=crossing["point_xy"]
            )

            if not endpoints_are_opposite_in_cycle_18(edge1, ordered_labels):
                continue

            if not endpoints_are_opposite_in_cycle_18(edge2, ordered_labels):
                continue

            outer_edges = get_outer_edges_from_ordered_quad_18(ordered_labels)

            valid_outer = True

            for outer_edge in outer_edges:
                outer_item = get_registry_item_for_edge(
                    registry_result,
                    outer_edge[0],
                    outer_edge[1]
                )

                if outer_item is None:
                    valid_outer = False
                    break

                if outer_item.get("source", "") in INDEPENDENT_GUARD_SOURCES_18:
                    valid_outer = False
                    break

                if outer_item.get("omit", False) or outer_item.get("curve", None) is None:
                    valid_outer = False
                    break

            if not valid_outer:
                continue

            case_key = (
                tuple(sorted(labels_quad)),
                tuple(sorted([edge1, edge2])),
            )

            if case_key in seen:
                continue

            seen.add(case_key)

            cases.append({
                "case_id": len(cases),
                "edge1": edge1,
                "edge2": edge2,
                "item1": item1,
                "item2": item2,
                "crossing": crossing,
                "ordered_labels": ordered_labels,
                "outer_edges": outer_edges,
            })

    return cases


def make_intersection_node_18(case, idx):
    P = case["crossing"]["point_3d"]

    return {
        "label": f"I_INT_18_{idx}",
        "type": "I",
        "x": float(P[0]),
        "y": float(P[1]),
        "z": float(P[2]),
        "source": "fase5_prototype_crest_intersection",
        "case_id": idx,
    }


def create_intersection_fragments_for_case_18(case, I_node):
    I_label = I_node["label"]
    PI = local_node_point(I_node)

    fragments = {}

    for item_key in ["item1", "item2"]:
        item = case[item_key]
        C = item["curve"]
        node_a = item["node_a"]
        node_b = item["node_b"]
        edge = item["edge"]

        if item_key == "item1":
            seg_idx = case["crossing"]["i"]
            local_t = case["crossing"]["t"]
        else:
            seg_idx = case["crossing"]["j"]
            local_t = case["crossing"]["u"]

        left, right = split_curve_at_crossing_18(
            C=C,
            seg_idx=seg_idx,
            local_t=local_t,
            P_insert=PI
        )

        key_a_i = local_edge_key(node_a["label"], I_label)
        fragments[key_a_i] = {
            "nodes": [node_a, I_node],
            "curve": left,
            "kind": "Fragmento de cresta por intersección local",
            "source": "fase18_intersection_fragment",
            "parent_source": item["source"],
            "parent_kind": item["kind"],
            "parent_edge": edge,
            "omit": False,
            "virtual": True,
        }

        key_i_b = local_edge_key(I_label, node_b["label"])
        fragments[key_i_b] = {
            "nodes": [I_node, node_b],
            "curve": right,
            "kind": "Fragmento de cresta por intersección local",
            "source": "fase18_intersection_fragment",
            "parent_source": item["source"],
            "parent_kind": item["kind"],
            "parent_edge": edge,
            "omit": False,
            "virtual": True,
        }

    return fragments


def make_subtetra_triangles_for_case_18(case, I_node, node_by_label):
    ordered = case["ordered_labels"]

    tris = []

    for i in range(4):
        a = ordered[i]
        b = ordered[(i + 1) % 4]

        tris.append({
            "nodes": [
                node_by_label[a],
                node_by_label[b],
                I_node,
            ],
            "virtual": True,
            "source": "fase5_prototype_intersection_subtetra",
            "parent_case_id": case["case_id"],
            "mlike_surface_type": "subtetra_M_like",
        })

    return tris


def build_registry_overlay_for_subtetra_case_18(
    triangles,
    registry_result,
    case_index=0
):
    cases = detect_subtetra_intersection_cases_18(
        triangles=triangles,
        registry_result=registry_result
    )

    if len(cases) == 0:
        return None, None, [], None

    if case_index >= len(cases):
        case_index = 0

    case = cases[case_index]

    out = copy.deepcopy(registry_result)

    if "crest_registry" not in out:
        out["crest_registry"] = {}

    if "intersection_fill_fragments_18" not in out:
        out["intersection_fill_fragments_18"] = {}

    if "intersection_fill_triangles_18" not in out:
        out["intersection_fill_triangles_18"] = []

    node_by_label = collect_node_by_label_18(
        triangles=triangles,
        registry_result=registry_result
    )

    I_node = make_intersection_node_18(case, case_index)
    node_by_label[I_node["label"]] = I_node

    fragments = create_intersection_fragments_for_case_18(case, I_node)

    for key, frag in fragments.items():
        out["crest_registry"][key] = frag
        out["intersection_fill_fragments_18"][key] = frag

    subtris = make_subtetra_triangles_for_case_18(
        case=case,
        I_node=I_node,
        node_by_label=node_by_label
    )

    out["intersection_fill_triangles_18"].extend(subtris)

    return out, I_node, subtris, case


def get_boundary_curve_item_for_local_patch_18(registry_result, n1, n2):
    item = get_registry_item_for_edge(
        registry_result,
        n1["label"],
        n2["label"]
    )

    if item is None:
        return None, None, None, None

    if item.get("omit", False):
        return None, item.get("kind", "Frontera omitida"), item.get("source", "omitted"), item

    C = local_curve_to_array(item.get("curve", None))

    if C is None:
        return None, item.get("kind", "Frontera sin curva"), item.get("source", "curve_none"), item

    C = local_orient_curve_xyz(C, n1, n2)

    return C, item.get("kind", "Frontera"), item.get("source", ""), item


def apply_three_guard_I_valley_reference_18(
    X,
    Y,
    Z,
    boundary_infos,
    nodes
):
    # El método de piso se conserva como respaldo, pero por defecto está apagado.
    if not ENABLE_THREE_GUARD_I_VALLEY_18:
        return Z

    if not any(is_intersection_I_node_18(n) for n in nodes):
        return Z

    effective_sources = [
        source_effective_18(info.get("item"))
        for info in boundary_infos
    ]

    if "three_guard_chain" not in effective_sources:
        return Z

    I_nodes = [n for n in nodes if is_intersection_I_node_18(n)]

    if len(I_nodes) != 1:
        return Z

    I_node = I_nodes[0]
    P_I = local_node_point(I_node)

    outer_non_guard_candidates = []

    for info in boundary_infos:
        nA, nB = info["nodes"]

        touches_I = (
            is_intersection_I_node_18(nA)
            or is_intersection_I_node_18(nB)
        )

        if touches_I:
            continue

        eff_source = source_effective_18(info.get("item"))

        if eff_source in DIRECT_GUARD_BOUNDARY_SOURCES_18:
            continue

        C = np.asarray(info["curve"], dtype=float)

        if C.ndim != 2 or C.shape[1] != 3 or len(C) < 2:
            continue

        outer_non_guard_candidates.append({
            "info": info,
            "effective_source": eff_source,
            "curve": C,
            "zmin": float(np.nanmin(C[:, 2])),
        })

    if not outer_non_guard_candidates:
        return Z

    outer = min(
        outer_non_guard_candidates,
        key=lambda item: item["zmin"]
    )

    C_outer = outer["curve"]

    idx_low = int(np.nanargmin(C_outer[:, 2]))
    P_low = C_outer[idx_low].astype(float)

    A = P_low[:2]
    B = P_I[:2]
    AB = B - A
    den = float(np.dot(AB, AB))

    if den <= 1e-12:
        return Z

    XY = np.column_stack([X.ravel(), Y.ravel()])
    Pxy = XY

    lam = np.dot(Pxy - A[None, :], AB) / den
    lam = np.clip(lam, 0.0, 1.0)

    closest = A[None, :] + lam[:, None] * AB[None, :]
    d_perp = np.linalg.norm(Pxy - closest, axis=1)

    dmax = float(np.nanmax(d_perp)) if len(d_perp) > 0 else 0.0

    if dmax <= 1e-12:
        d_norm = np.zeros_like(d_perp)
    else:
        d_norm = d_perp / dmax

    z_line = P_low[2] + lam * (P_I[2] - P_low[2])

    z_span = float(np.nanmax(Z) - min(P_low[2], P_I[2]))
    z_span = max(z_span, THREE_GUARD_VALLEY_MIN_SCALE_18)

    z_floor = (
        z_line
        + THREE_GUARD_VALLEY_LIFT_18
        * z_span
        * np.power(d_norm, THREE_GUARD_VALLEY_POWER_18)
    )

    Z_flat = Z.ravel().copy()
    mask = np.isfinite(Z_flat) & np.isfinite(z_floor)
    Z_flat[mask] = np.maximum(Z_flat[mask], z_floor[mask])

    return Z_flat.reshape(Z.shape)


def build_local_subtetra_patch_18(
    n1,
    n2,
    n3,
    registry_result,
    ns=90,
    nt=90
):
    C12_raw, kind12, source12, item12 = get_boundary_curve_item_for_local_patch_18(
        registry_result,
        n1,
        n2
    )

    C13_raw, kind13, source13, item13 = get_boundary_curve_item_for_local_patch_18(
        registry_result,
        n1,
        n3
    )

    C23_raw, kind23, source23, item23 = get_boundary_curve_item_for_local_patch_18(
        registry_result,
        n2,
        n3
    )

    if C12_raw is None or C13_raw is None or C23_raw is None:
        return None

    C12 = local_resample_curve_xyz(C12_raw, ns)
    C13 = local_resample_curve_xyz(C13_raw, nt)
    C23 = local_resample_curve_xyz(C23_raw, nt)

    X, Y, Z = build_mmm_patch_from_boundaries(
        C12=C12,
        C13=C13,
        C23=C23,
        ns=ns,
        nt=nt,
        preserve_nonnegative=True
    )

    boundary_infos = [
        {
            "name": "C12",
            "curve": C12,
            "kind": kind12,
            "source": source12,
            "item": item12,
            "nodes": (n1, n2),
        },
        {
            "name": "C13",
            "curve": C13,
            "kind": kind13,
            "source": source13,
            "item": item13,
            "nodes": (n1, n3),
        },
        {
            "name": "C23",
            "curve": C23,
            "kind": kind23,
            "source": source23,
            "item": item23,
            "nodes": (n2, n3),
        },
    ]

    Z = apply_three_guard_I_valley_reference_18(
        X=X,
        Y=Y,
        Z=Z,
        boundary_infos=boundary_infos,
        nodes=(n1, n2, n3)
    )

    # Reimponer fronteras exactas después del ajuste.
    X[0, :] = C12[:, 0]
    Y[0, :] = C12[:, 1]
    Z[0, :] = C12[:, 2]

    X[:, 0] = C13[:, 0]
    Y[:, 0] = C13[:, 1]
    Z[:, 0] = C13[:, 2]

    X[:, -1] = C23[:, 0]
    Y[:, -1] = C23[:, 1]
    Z[:, -1] = C23[:, 2]

    Z = np.maximum(Z, 0.0)

    return {
        "status": "built",
        "surface_model": "LOCAL_SUBTETRA_INTERPOLATION",
        "X": X,
        "Y": Y,
        "Z": Z,
        "C12": C12,
        "C13": C13,
        "C23": C23,
        "kind12": kind12,
        "kind13": kind13,
        "kind23": kind23,
        "source12": source12,
        "source13": source13,
        "source23": source23,
    }


# =========================================================
# 10B) RELLENO ESPECIAL POR BARRIDO PARALELO P_low-I
# PARA CASO three_guard_chain
# =========================================================
#
# Idea:
#   En vez de dividir la subtetra en dos, se conserva una sola superficie.
#   Para la subtetra especial asociada a three_guard_chain:
#     1) Se identifica la frontera exterior que NO toca I y que NO es guarda directa.
#     2) Se ubica P_low, el punto más bajo de esa frontera exterior.
#     3) Se toma la dirección de referencia P_low -> I.
#     4) Desde varios puntos de la frontera exterior se trazan rectas internas
#        paralelas a esa dirección hasta interceptar las otras crestas laterales.
#     5) La superficie se construye como un barrido de esas rectas.
#
# Esto evita el piso artificial y evita subdividir la subtetra.
# No toca guardas independientes ni sus subcasos.
# =========================================================

ENABLE_PARALLEL_SWEEP_THREE_GUARD_18 = True
PARALLEL_SWEEP_FALLBACK_TO_I_18 = True
PARALLEL_SWEEP_MIN_DIR_NORM_18 = 1e-9
PARALLEL_SWEEP_ALPHA_TOL_18 = 1e-7


def build_local_subtetra_patch_without_valley_18(
    n1,
    n2,
    n3,
    registry_result,
    ns=90,
    nt=90
):
    """
    Construye una subtetra sin aplicar el piso artificial del caso three_guard.
    El nuevo método especial usa barrido paralelo, no clipping por piso.
    """
    old_flag = globals().get("ENABLE_THREE_GUARD_I_VALLEY_18", False)
    globals()["ENABLE_THREE_GUARD_I_VALLEY_18"] = False

    try:
        built = build_local_subtetra_patch_18(
            n1=n1,
            n2=n2,
            n3=n3,
            registry_result=registry_result,
            ns=ns,
            nt=nt
        )
    finally:
        globals()["ENABLE_THREE_GUARD_I_VALLEY_18"] = old_flag

    return built


def find_three_guard_outer_non_guard_boundary_18(
    nodes,
    registry_result
):
    """
    Identifica si la subtetra pertenece al caso especial:
      - contiene un punto I;
      - alguna frontera viene de three_guard_chain;
      - la frontera exterior, la que no toca I, NO es una guarda directa.

    Retorna la frontera exterior no-guarda donde se buscará P_low.
    """
    if not ENABLE_PARALLEL_SWEEP_THREE_GUARD_18:
        return None

    if not any(is_intersection_I_node_18(n) for n in nodes):
        return None

    I_nodes = [n for n in nodes if is_intersection_I_node_18(n)]

    if len(I_nodes) != 1:
        return None

    I_node = I_nodes[0]

    pairs = [
        (nodes[0], nodes[1]),
        (nodes[0], nodes[2]),
        (nodes[1], nodes[2]),
    ]

    boundary_infos = []

    for nA, nB in pairs:
        C, kind, source, item = get_boundary_curve_item_for_local_patch_18(
            registry_result,
            nA,
            nB
        )

        if C is None:
            return None

        eff_source = source_effective_18(item)

        boundary_infos.append({
            "nodes": (nA, nB),
            "curve": C,
            "kind": kind,
            "source": source,
            "item": item,
            "effective_source": eff_source,
            "touches_I": (
                is_intersection_I_node_18(nA)
                or is_intersection_I_node_18(nB)
            ),
        })

    effective_sources = [info["effective_source"] for info in boundary_infos]

    # No tocar guardas independientes ni sus subcasos.
    if any(src in INDEPENDENT_GUARD_SOURCES_18 for src in effective_sources):
        return None

    # El caso debe estar asociado a three_guard_chain.
    if "three_guard_chain" not in effective_sources:
        return None

    outer_candidates = []

    for info in boundary_infos:

        # La frontera exterior es la que NO toca I.
        if info["touches_I"]:
            continue

        # Si la frontera exterior es guarda directa, no se aplica este ajuste.
        if info["effective_source"] in DIRECT_GUARD_BOUNDARY_SOURCES_18:
            continue

        C = np.asarray(info["curve"], dtype=float)

        if C.ndim != 2 or C.shape[1] != 3 or len(C) < 3:
            continue

        outer_candidates.append({
            **info,
            "zmin": float(np.nanmin(C[:, 2])),
        })

    if not outer_candidates:
        return None

    outer_info = min(
        outer_candidates,
        key=lambda x: x["zmin"]
    )

    outer_info["I_node"] = I_node
    outer_info["boundary_infos"] = boundary_infos

    return outer_info


def line_segment_intersection_xy_18(P0, direction, A, B, tol=1e-9):
    """
    Intersección entre una recta infinita:
        P = P0 + alpha * direction
    y un segmento:
        S = A + beta * (B-A), beta en [0, 1]

    Retorna alpha, beta y punto XY si existe.
    """
    P0 = np.asarray(P0, dtype=float)[:2]
    direction = np.asarray(direction, dtype=float)[:2]
    A = np.asarray(A, dtype=float)[:2]
    B = np.asarray(B, dtype=float)[:2]

    s = B - A
    den = cross2d_18(direction, s)

    if abs(den) <= tol:
        return None

    qmp = A - P0
    alpha = cross2d_18(qmp, s) / den
    beta = cross2d_18(qmp, direction) / den

    if beta < -tol or beta > 1.0 + tol:
        return None

    beta_clamped = float(np.clip(beta, 0.0, 1.0))
    Pxy = A + beta_clamped * s

    return {
        "alpha": float(alpha),
        "beta": beta_clamped,
        "point_xy": Pxy,
    }


def line_curve_intersections_xy_18(P0, direction, C, tol=1e-9):
    """
    Intersecciones entre una recta infinita y una curva discretizada.
    """
    C = np.asarray(C, dtype=float)
    out = []

    if C.ndim != 2 or C.shape[1] != 3 or len(C) < 2:
        return out

    for i in range(len(C) - 1):
        hit = line_segment_intersection_xy_18(
            P0=P0,
            direction=direction,
            A=C[i, :2],
            B=C[i + 1, :2],
            tol=tol
        )

        if hit is None:
            continue

        beta = hit["beta"]
        P3 = C[i] + beta * (C[i + 1] - C[i])
        P3[2] = max(P3[2], 0.0)

        out.append({
            **hit,
            "point_3d": P3,
            "segment_index": i,
        })

    return out


def choose_parallel_sweep_endpoint_18(P0, direction, I_node, side_curves):
    """
    Para un punto P0 en la frontera exterior, busca el punto final de la recta
    paralela a P_low-I sobre las crestas laterales que llegan a I.

    Prioridad:
      1) Intersección en la dirección hacia I.
      2) Intersección más cercana si no cumple el criterio anterior.
      3) Fallback al punto I.
    """
    P0 = np.asarray(P0, dtype=float)
    direction = np.asarray(direction, dtype=float)

    I_point = local_node_point(I_node)

    candidates = []

    # Parámetro esperado hacia I sobre la dirección guía.
    den = float(np.dot(direction[:2], direction[:2]))

    if den <= PARALLEL_SWEEP_MIN_DIR_NORM_18:
        return I_point.copy(), {
            "method": "fallback_I_zero_direction",
            "alpha": None,
            "side_index": None,
        }

    alpha_I = float(np.dot(I_point[:2] - P0[:2], direction[:2]) / den)

    for side_idx, Cside in enumerate(side_curves):
        hits = line_curve_intersections_xy_18(
            P0=P0[:2],
            direction=direction[:2],
            C=Cside,
            tol=INTERSECTION_TOL_18
        )

        for hit in hits:
            alpha = hit["alpha"]

            same_direction = (
                alpha >= -PARALLEL_SWEEP_ALPHA_TOL_18
                if alpha_I >= 0.0
                else alpha <= PARALLEL_SWEEP_ALPHA_TOL_18
            )

            between_P0_and_I = (
                -PARALLEL_SWEEP_ALPHA_TOL_18 <= alpha <= alpha_I + PARALLEL_SWEEP_ALPHA_TOL_18
                if alpha_I >= 0.0
                else alpha_I - PARALLEL_SWEEP_ALPHA_TOL_18 <= alpha <= PARALLEL_SWEEP_ALPHA_TOL_18
            )

            candidates.append({
                **hit,
                "side_index": side_idx,
                "same_direction": bool(same_direction),
                "between_P0_and_I": bool(between_P0_and_I),
                "distance_to_expected_I": abs(alpha - alpha_I),
                "distance_from_P0": abs(alpha),
            })

    if candidates:
        preferred = [c for c in candidates if c["same_direction"] and c["between_P0_and_I"]]

        if preferred:
            # Elegir el punto más lejos de P0 dentro del segmento hacia I,
            # para que la recta atraviese la región interior.
            chosen = max(preferred, key=lambda c: c["distance_from_P0"])
        else:
            same_dir = [c for c in candidates if c["same_direction"]]

            if same_dir:
                chosen = min(same_dir, key=lambda c: c["distance_to_expected_I"])
            else:
                chosen = min(candidates, key=lambda c: c["distance_to_expected_I"])

        return chosen["point_3d"].copy(), {
            "method": "side_intersection",
            "alpha": chosen["alpha"],
            "side_index": chosen["side_index"],
            "between_P0_and_I": chosen["between_P0_and_I"],
        }

    if PARALLEL_SWEEP_FALLBACK_TO_I_18:
        return I_point.copy(), {
            "method": "fallback_I_no_intersection",
            "alpha": alpha_I,
            "side_index": None,
        }

    return None, {
        "method": "failed_no_intersection",
        "alpha": None,
        "side_index": None,
    }


def build_parallel_sweep_patch_for_three_guard_subtetra_18(
    nodes,
    registry_result,
    ns=90,
    nt=90
):
    """
    Constructor especial sin división:
    genera una superficie por barrido de rectas paralelas a P_low-I.
    """
    outer_info = find_three_guard_outer_non_guard_boundary_18(
        nodes=nodes,
        registry_result=registry_result
    )

    if outer_info is None:
        return None

    I_node = outer_info["I_node"]
    nA, nB = outer_info["nodes"]

    C_outer_raw = np.asarray(outer_info["curve"], dtype=float)
    C_outer = local_resample_curve_xyz(C_outer_raw, ns)

    # Asegurar orientación de la frontera exterior nA -> nB.
    C_outer = local_orient_curve_xyz(C_outer, nA, nB)
    C_outer = local_resample_curve_xyz(C_outer, ns)

    idx_low = int(np.nanargmin(C_outer[:, 2]))
    P_low = C_outer[idx_low].astype(float)
    P_low[2] = max(P_low[2], 0.0)

    P_I = local_node_point(I_node)

    direction = P_I - P_low
    direction[2] = 0.0

    if np.linalg.norm(direction[:2]) <= PARALLEL_SWEEP_MIN_DIR_NORM_18:
        return None

    # Las dos fronteras laterales son las que tocan I.
    side_infos = [
        info for info in outer_info["boundary_infos"]
        if info["touches_I"]
    ]

    if len(side_infos) != 2:
        return None

    side_curves = []

    for info in side_infos:
        nS1, nS2 = info["nodes"]
        Cside = np.asarray(info["curve"], dtype=float)
        Cside = local_orient_curve_xyz(Cside, nS1, nS2)
        Cside = local_resample_curve_xyz(Cside, nt)
        side_curves.append(Cside)

    # Construir endpoints de barrido sobre las crestas laterales.
    Q_end = []
    endpoint_methods = []

    for i in range(ns):
        P0 = C_outer[i]

        Q, method_info = choose_parallel_sweep_endpoint_18(
            P0=P0,
            direction=direction,
            I_node=I_node,
            side_curves=side_curves
        )

        if Q is None:
            return None

        Q_end.append(Q)
        endpoint_methods.append(method_info)

    Q_end = np.asarray(Q_end, dtype=float)
    Q_end[:, 2] = np.maximum(Q_end[:, 2], 0.0)

    X = np.zeros((nt, ns))
    Y = np.zeros((nt, ns))
    Z = np.zeros((nt, ns))

    # Cada columna es una recta interna paralela a P_low-I.
    # v=0: frontera exterior.
    # v=1: intersección con las fronteras laterales.
    v_values = np.linspace(0.0, 1.0, nt)

    for i in range(ns):
        P0 = C_outer[i]
        P1 = Q_end[i]

        for j, v in enumerate(v_values):
            P = (1.0 - v) * P0 + v * P1
            X[j, i] = P[0]
            Y[j, i] = P[1]
            Z[j, i] = max(P[2], 0.0)

    # Reimponer exactamente la frontera exterior.
    X[0, :] = C_outer[:, 0]
    Y[0, :] = C_outer[:, 1]
    Z[0, :] = C_outer[:, 2]

    # La última fila es la curva compuesta de intersecciones laterales.
    X[-1, :] = Q_end[:, 0]
    Y[-1, :] = Q_end[:, 1]
    Z[-1, :] = Q_end[:, 2]

    # Para mantener compatibilidad con el plot existente,
    # se reportan las tres fronteras originales de la subtetra.
    n1, n2, n3 = nodes

    C12, kind12, source12, item12 = get_boundary_curve_item_for_local_patch_18(
        registry_result,
        n1,
        n2
    )
    C13, kind13, source13, item13 = get_boundary_curve_item_for_local_patch_18(
        registry_result,
        n1,
        n3
    )
    C23, kind23, source23, item23 = get_boundary_curve_item_for_local_patch_18(
        registry_result,
        n2,
        n3
    )

    C12 = local_resample_curve_xyz(C12, ns)
    C13 = local_resample_curve_xyz(C13, nt)
    C23 = local_resample_curve_xyz(C23, nt)

    Z = np.maximum(Z, 0.0)

    return {
        "status": "built",
        "surface_model": "PARALLEL_SWEEP_THREE_GUARD_PLOW_I",
        "X": X,
        "Y": Y,
        "Z": Z,
        "C12": C12,
        "C13": C13,
        "C23": C23,
        "kind12": kind12,
        "kind13": kind13,
        "kind23": kind23,
        "source12": source12,
        "source13": source13,
        "source23": source23,
        "parallel_sweep_applied": True,
        "P_low": P_low,
        "I_point": P_I,
        "outer_nodes": (nA, nB),
        "outer_source": outer_info["effective_source"],
        "endpoint_methods": endpoint_methods,
    }


def build_subtetra_patch_records_with_parallel_sweep_18(
    nodes,
    registry_result,
    local_index=0,
    ns=90,
    nt=90
):
    """
    Construye una subtetra. Si aplica el caso three_guard, usa barrido
    paralelo P_low-I en una sola superficie. No divide la subtetra.
    """
    built = build_parallel_sweep_patch_for_three_guard_subtetra_18(
        nodes=nodes,
        registry_result=registry_result,
        ns=ns,
        nt=nt
    )

    if built is not None:
        return [{
            "built": built,
            "nodes": nodes,
            "parallel_sweep_applied": True,
            "P_low": built.get("P_low"),
            "I_point": built.get("I_point"),
        }]

    # Caso normal: no aplica barrido especial.
    n1, n2, n3 = nodes

    built = build_local_subtetra_patch_without_valley_18(
        n1=n1,
        n2=n2,
        n3=n3,
        registry_result=registry_result,
        ns=ns,
        nt=nt
    )

    if built is None:
        return []

    return [{
        "built": built,
        "nodes": nodes,
        "parallel_sweep_applied": False,
        "P_low": None,
        "I_point": None,
    }]


# =========================================================
# 10C) GRÁFICA DE SUBTETRAS CON BARRIDO PARALELO P_low-I
# =========================================================

def plot_one_subtetra_example_18(
    triangles,
    registry_result,
    case_index=0,
    ns=90,
    nt=90,
    show_internal_mesh=True
):
    overlay_result, I_node, subtris, case = build_registry_overlay_for_subtetra_case_18(
        triangles=triangles,
        registry_result=registry_result,
        case_index=case_index
    )

    if overlay_result is None:
        print("=========================================================")
        print("EJEMPLO 2 — SUBTETRAS POR INTERSECCIÓN")
        print("=========================================================")
        print("No se encontró ningún cruce válido de crestas para generar subtetras.")
        print("No se tocaron guardas independientes ni sus subcasos.")
        print("=========================================================")

        return None

    fig = go.Figure()

    built_subpatches = []
    failed_subpatches = []
    parallel_sweep_count = 0
    p_low_points_to_plot = []

    for idx, tri in enumerate(subtris):
        nodes = tri["nodes"]

        patch_records = build_subtetra_patch_records_with_parallel_sweep_18(
            nodes=nodes,
            registry_result=overlay_result,
            local_index=idx,
            ns=ns,
            nt=nt
        )

        if not patch_records:
            failed_subpatches.append({
                "idx": idx,
                "labels": "-".join([n["label"] for n in nodes]),
            })
            continue

        for local_piece_idx, rec in enumerate(patch_records):
            built = rec["built"]
            piece_nodes = rec["nodes"]

            n1, n2, n3 = piece_nodes

            X = built["X"]
            Y = built["Y"]
            Z = built["Z"]

            if rec["parallel_sweep_applied"]:
                parallel_sweep_count += 1
                P_low = rec.get("P_low")

                if P_low is not None:
                    p_low_points_to_plot.append({
                        "label": f"P_LOW_18_{idx}",
                        "point": P_low,
                    })

                surface_name = (
                    f"Subtetra {idx+1} barrido P_low-I: "
                    f"{n1['label']}-{n2['label']}-{n3['label']}"
                )

            else:
                surface_name = (
                    f"Subtetra {idx+1}: {n1['label']}-{n2['label']}-{n3['label']}"
                )

            fig.add_trace(go.Surface(
                x=X,
                y=Y,
                z=Z,
                opacity=0.74,
                showscale=False,
                name=surface_name,
                hovertemplate=(
                    f"{surface_name}<br>"
                    f"Modelo: {built.get('surface_model', '')}<br>"
                    f"C12: {built['source12']}<br>"
                    f"C13: {built['source13']}<br>"
                    f"C23: {built['source23']}<br>"
                    f"parallel_sweep_Plow_I: {rec['parallel_sweep_applied']}<br>"
                    "x=%{x:.2f}<br>"
                    "y=%{y:.2f}<br>"
                    "z=%{z:.2f}<extra></extra>"
                )
            ))

            if show_internal_mesh:
                step_t = max(1, nt // 10)
                step_s = max(1, ns // 10)

                for row in range(0, nt, step_t):
                    fig.add_trace(go.Scatter3d(
                        x=X[row, :],
                        y=Y[row, :],
                        z=Z[row, :],
                        mode="lines",
                        line=dict(width=1),
                        showlegend=False
                    ))

                for col in range(0, ns, step_s):
                    fig.add_trace(go.Scatter3d(
                        x=X[:, col],
                        y=Y[:, col],
                        z=Z[:, col],
                        mode="lines",
                        line=dict(width=1),
                        showlegend=False
                    ))

            for C, name, a, b in [
                (built["C12"], "C12", n1, n2),
                (built["C13"], "C13", n1, n3),
                (built["C23"], "C23", n2, n3),
            ]:
                fig.add_trace(go.Scatter3d(
                    x=C[:, 0],
                    y=C[:, 1],
                    z=C[:, 2],
                    mode="lines",
                    line=dict(width=6),
                    name=f"{name} | {a['label']}-{b['label']}"
                ))

            # Dibujar, solo para diagnóstico, la recta guía P_low-I.
            if rec["parallel_sweep_applied"] and rec.get("P_low") is not None:
                P_low = rec["P_low"]
                P_I = rec.get("I_point", local_node_point(I_node))

                fig.add_trace(go.Scatter3d(
                    x=[P_low[0], P_I[0]],
                    y=[P_low[1], P_I[1]],
                    z=[P_low[2], P_I[2]],
                    mode="lines",
                    line=dict(width=7, dash="dot"),
                    name=f"Guía P_low-I subtetra {idx+1}"
                ))

            built_subpatches.append({
                "tri": tri,
                "nodes": piece_nodes,
                "built": built,
                "parallel_sweep_applied": rec["parallel_sweep_applied"],
                "P_low": rec.get("P_low"),
                "I_point": rec.get("I_point"),
            })

    # Dibujar las dos crestas originales cruzadas como referencia.
    for edge_name, item_key in [
        ("Diagonal original 1", "item1"),
        ("Diagonal original 2", "item2"),
    ]:
        item = case[item_key]
        C = item["curve"]

        fig.add_trace(go.Scatter3d(
            x=C[:, 0],
            y=C[:, 1],
            z=C[:, 2],
            mode="lines",
            line=dict(width=10, dash="dash"),
            name=f"{edge_name}: {item['edge']}"
        ))

    # Punto I.
    fig.add_trace(go.Scatter3d(
        x=[I_node["x"]],
        y=[I_node["y"]],
        z=[I_node["z"]],
        mode="markers+text",
        marker=dict(size=9, symbol="diamond"),
        text=[I_node["label"]],
        textposition="top center",
        name="Punto I de intersección"
    ))

    # Puntos P_low de referencia.
    if p_low_points_to_plot:
        fig.add_trace(go.Scatter3d(
            x=[rec["point"][0] for rec in p_low_points_to_plot],
            y=[rec["point"][1] for rec in p_low_points_to_plot],
            z=[rec["point"][2] for rec in p_low_points_to_plot],
            mode="markers+text",
            marker=dict(size=8, symbol="circle"),
            text=[rec["label"] for rec in p_low_points_to_plot],
            textposition="top center",
            name="Puntos P_low de referencia"
        ))

    # Puntos exteriores.
    node_by_label = collect_node_by_label_18(
        triangles=triangles,
        registry_result=registry_result
    )

    for lbl in case["ordered_labels"]:
        n = node_by_label[lbl]

        fig.add_trace(go.Scatter3d(
            x=[n["x"], n["x"]],
            y=[n["y"], n["y"]],
            z=[0.0, n["z"]],
            mode="lines+markers+text",
            line=dict(width=6),
            marker=dict(size=5),
            text=["", n["label"]],
            textposition="top center",
            name=n["label"]
        ))

    pts_x = [node_by_label[lbl]["x"] for lbl in case["ordered_labels"]] + [I_node["x"]]
    pts_y = [node_by_label[lbl]["y"] for lbl in case["ordered_labels"]] + [I_node["y"]]

    if p_low_points_to_plot:
        pts_x.extend([rec["point"][0] for rec in p_low_points_to_plot])
        pts_y.extend([rec["point"][1] for rec in p_low_points_to_plot])

    pad = 8

    Xg, Yg = np.meshgrid(
        np.linspace(min(pts_x) - pad, max(pts_x) + pad, 2),
        np.linspace(min(pts_y) - pad, max(pts_y) + pad, 2)
    )

    fig.add_trace(go.Surface(
        x=Xg,
        y=Yg,
        z=np.zeros_like(Xg),
        opacity=0.12,
        showscale=False,
        hoverinfo="skip",
        name="Plano z=0"
    ))

    fig.update_layout(
        title=(
            "EJEMPLO 2 — Relleno de subtetras por cruce de crestas "
            f"con barrido paralelo P_low-I | caso={case_index}"
        ),
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=900,
        showlegend=True
    )

    print("=========================================================")
    print("EJEMPLO 2 — DIAGNÓSTICO DE SUBTETRAS POR INTERSECCIÓN")
    print("=========================================================")
    print(f"case_index usado: {case_index}")
    print(f"Punto I: {I_node['label']} = ({I_node['x']:.3f}, {I_node['y']:.3f}, {I_node['z']:.3f})")
    print(f"Cresta cruzada 1: {case['edge1']} | source={case['item1']['source']}")
    print(f"Cresta cruzada 2: {case['edge2']} | source={case['item2']['source']}")
    print(f"Orden exterior: {case['ordered_labels']}")
    print(f"Bordes exteriores: {case['outer_edges']}")
    print(f"Subtetras originales creadas: {len(subtris)}")
    print(f"Piezas finales rellenadas: {len(built_subpatches)}")
    print(f"Barridos paralelos P_low-I aplicados: {parallel_sweep_count}")
    print(f"Subtetras fallidas: {len(failed_subpatches)}")

    if p_low_points_to_plot:
        print("")
        print("Puntos P_low de referencia:")
        for rec in p_low_points_to_plot:
            P = rec["point"]
            print(f"  {rec['label']} = ({P[0]:.3f}, {P[1]:.3f}, {P[2]:.3f})")

    if failed_subpatches:
        print("")
        print("Subtetras no construidas:")
        for rec in failed_subpatches:
            print(f"  {rec['idx']}: {rec['labels']}")

    print("=========================================================")

    fig.show()

    return {
        "case": case,
        "I_node": I_node,
        "p_low_points": p_low_points_to_plot,
        "subtris": subtris,
        "overlay_result": overlay_result,
        "built_subpatches": built_subpatches,
        "failed_subpatches": failed_subpatches,
        "parallel_sweep_count": parallel_sweep_count,
        "fig": fig,
    }



