def plot_full_surface_with_mmq_and_mlike_fill_fase6X(
    masts,
    sphere_radius,
    results,
    tri_nodes,
    triangles,
    guard_wire_inputs=None,
    registry_result=None,
    show_single_mast_surfaces=True,
    show_red_q_edges=True,
    show_mmq_fill=True,
    show_mlike_fill=True,
    show_mmm_borders=True,
    show_mm_crests=True,
    show_mq_segments=True,
    show_q_points=True,
    show_i_intersection_points=True,
    mmq_flatten_power=3.5
):
    fig = go.Figure()

    registry_result_to_plot = registry_result
    tri_nodes_to_plot = tri_nodes
    subdivision_records = []

    if show_single_mast_surfaces:
        fn_add_mast = globals().get("add_mast_to_figure", None)

        if not callable(fn_add_mast):
            raise NameError(
                "No se encontró add_mast_to_figure. "
                "Ejecuta primero la celda donde se definen las superficies de mástil solo."
            )

        for i, mast in enumerate(masts):
            fn_add_mast(
                fig=fig,
                mast=mast,
                idx=i,
                sphere_radius=sphere_radius,
                results=results,
                show_mast_line=True,
                show_base_circle=True
            )

    if show_red_q_edges:
        fn_dibujar_q = globals().get("dibujar_aristas_Q", None)

        if callable(fn_dibujar_q):
            fn_dibujar_q(
                fig=fig,
                masts=masts,
                results=results,
                S=sphere_radius,
                n_pts=200
            )
        else:
            print(
                "Advertencia: no se encontró dibujar_aristas_Q. "
                "No se dibujaron las aristas rojas hacia Q."
            )

    if show_mmq_fill:
        fn_add_mmq = globals().get("add_all_mmq_patches_to_fig", None)

        if not callable(fn_add_mmq):
            raise NameError(
                "No se encontró add_all_mmq_patches_to_fig. "
                "Ejecuta primero la FASE 4B."
            )

        fig = fn_add_mmq(
            fig=fig,
            triangles=triangles,
            sphere_radius=sphere_radius,
            guard_wire_inputs=guard_wire_inputs,
            registry_result=registry_result,
            ns=75,
            nt=75,
            opacity=0.70,
            flatten_power=mmq_flatten_power,
            apply_xy_mask=True,
            xy_mask_radius=1e-9
        )

    if show_mlike_fill:
        fig, registry_result_to_plot, tri_nodes_to_plot, subdivision_records = (
            add_all_mlike_patches_to_fig_fase6X(
                fig=fig,
                triangles=triangles,
                sphere_radius=sphere_radius,
                guard_wire_inputs=guard_wire_inputs,
                registry_result=registry_result,
                tri_nodes=tri_nodes,
                ns=75,
                nt=75,
                opacity=0.70,
                show_internal_summary=True
            )
        )

    fn_add_triangles = globals().get("add_triangles_crests_and_mq_to_existing_fig", None)

    if callable(fn_add_triangles):
        fig = fn_add_triangles(
            fig=fig,
            tri_nodes=tri_nodes_to_plot,
            triangles=triangles,
            sphere_radius=sphere_radius,
            guard_wire_inputs=guard_wire_inputs,
            registry_result=registry_result_to_plot,
            show_mmm_borders=show_mmm_borders,
            show_mm_crests=show_mm_crests,
            show_mq_segments=show_mq_segments,
            show_q_points=show_q_points,
            show_special_auxiliaries=True
        )
    else:
        print(
            "Advertencia: no se encontró add_triangles_crests_and_mq_to_existing_fig. "
            "No se agregaron crestas, segmentos M-Q ni puntos Q desde esta función."
        )

    if show_i_intersection_points:
        i_nodes = [
            n for n in tri_nodes_to_plot
            if str(n.get("label", "")).startswith("I_INT_6X")
            or str(n.get("type", "")) == "I"
        ]

        if i_nodes:
            fig.add_trace(go.Scatter3d(
                x=[n["x"] for n in i_nodes],
                y=[n["y"] for n in i_nodes],
                z=[n["z"] for n in i_nodes],
                mode="markers+text",
                marker=dict(size=8, color="cyan", symbol="diamond"),
                text=[n["label"] for n in i_nodes],
                textposition="top center",
                name="Puntos I de intersección"
            ))

    all_x = [m.x for m in masts]
    all_y = [m.y for m in masts]
    max_a = max(local_effective_radius_fase6X(m.h, sphere_radius) for m in masts)

    xmin = min(all_x) - max_a - 5
    xmax = max(all_x) + max_a + 5
    ymin = min(all_y) - max_a - 5
    ymax = max(all_y) + max_a + 5

    Xg, Yg = np.meshgrid(
        np.linspace(xmin, xmax, 2),
        np.linspace(ymin, ymax, 2)
    )

    Zg = np.zeros_like(Xg)

    fig.add_trace(go.Surface(
        x=Xg,
        y=Yg,
        z=Zg,
        showscale=False,
        opacity=0.15,
        name="Plano z=0",
        hoverinfo="skip"
    ))

    fig.update_layout(
        title=(
            "FASE 5B: M-M-Q + M-M-M/M-M-N/N-N-M "
            "con subdivisión local por cruce de crestas "
            "+ ancla física MMM/MMN sin guarda"
        ),
        scene=dict(
            xaxis_title="X",
            yaxis_title="Y",
            zaxis_title="Z",
            aspectmode="data"
        ),
        height=950,
        showlegend=True
    )

    fig.show()

    return fig, registry_result_to_plot, tri_nodes_to_plot, subdivision_records


