print("  - fase6_surface_patches")
print("  - fase6_surface_interpolators")
print("  - fase6_point_results_df")
print("  - fase6_equipment_summary_df")
print("  - fase6_resultados_por_equipo")
print("  - fig_fase6_verificacion")
print("=========================================================")

